def rule_ids(keys):
    """원문 키들 → 규칙 번호 목록(순서 유지, 중복 제거)."""
    return sorted(dict.fromkeys(RULE_ID[k] for k in keys if k in RULE_ID))


# ---------------------------------------------------------------------------
# 금액 읽기 — 값, 쓰임(role), 기간(period), 출처(src)
# ---------------------------------------------------------------------------
_NUM = r'\d{1,3}(?:,\d{3})+|\d+(?:\.\d+)?'
# 1억 2천만 원 · 1억2천5백만 · 3억 · 1,800만 원 · 2천만원 · 1천8백만 · 18,000,000원
_MONEY = re.compile(
    rf'(?P<eok>{_NUM})\s*억(?:\s*(?P<eok_cheon>\d)\s*천)?(?:\s*(?P<eok_baek>\d)\s*백)?(?:\s*(?P<eok_man>{_NUM}))?\s*만?\s*원?'
    rf'|(?<![\d.])(?P<cheon>\d(?:\.\d)?)\s*천(?:\s*(?P<baek>\d)\s*백)?(?:\s*(?P<cman>{_NUM}))?\s*만\s*원?'
    # '천만원이면요?' — 숫자 없는 천만(1,000만). '추천만'처럼 낱말 안의 천은 아니다(C10 대화: 재작성이 '천만 원'을 남기면 금액을 못 읽었다)
    rf'|(?<![\d가-힣])(?P<bcheon>천)(?:\s*(?P<bbaek>\d)\s*백)?\s*만\s*원?'
    # won() 이 쓰는 '33만 6천 원', '1,173만 3,333원' — 만 뒤의 천·원 단위까지 한 금액으로 읽는다
    rf'|(?P<mc>{_NUM})\s*만\s*(?P<mc_cheon>\d)\s*천(?!\s*만)(?:\s*원)?'
    rf'|(?P<mw>{_NUM})\s*만\s*(?P<mw_won>\d{{1,3}}(?:,\d{{3}})?)\s*원'
    rf'|(?P<man>{_NUM})\s*만\s*원?'
    rf'|(?P<won>\d{{1,3}}(?:,\d{{3}})+)\s*원')
# '연봉 6천' '총급여 5천5백' — 소득 자리에서만 '만'이 빠진 표기를 받는다.
# \s*(?:이|가)?\s*(?:약)?\s* 처럼 선택 항목 사이에 \s* 를 겹쳐 두면 공백이 길 때 세제곱으로 느려진다
# (검토: 공백 800개에 2.2초, 그동안 서버 전체가 멈춤 — 정규식 엔진이 GIL 을 놓지 않는다). 선형 꼴로 쓴다.
# 종합소득(금액)·사업소득금액도 소득 자리다 — 연봉·총급여·급여만 보아 '종합소득금액이 3천 정도'를 못 읽고 '공제율을 정할 소득이
# 분명하지 않음'이라며 두 갈래를 냈다(stab 2221·2229·2276). '금액' 없는 '사업소득 N천'은 수입일 수 있어 읽지 않는다
# ('사업소득이 5천인데 필요경비 빼면 3천' — 5천을 소득으로 보아 13.2%, 맞는 값은 소득금액 3천 → 16.5%)
_INCOME_BARE_WORD = r'종합\s*소득(?:\s*금액)?|사업\s*소득\s*금액'
_INCOME_BARE = re.compile(r'(?:연봉|총\s*급여|(?<!퇴직)(?<!퇴직\s)급여|' + _INCOME_BARE_WORD + r')\s*(?:(?:이|가|은|는)\s*)?(?:(?:약|대략)\s*)?'
                          r'(\d)\s*천(?:\s*(\d)\s*백)?(?!\s*만|\s*\d)')
# 소득 뒤 기준 말 — 넘는 쪽(1)·못 미치는 쪽(2). '종합소득 5천 넘는'의 소득은 5천이 아니라 그 위다.
# '까지'는 넣지 않는다 — '연봉이 6천까지 올랐어요'는 그 값이다
_INCOME_SIDE = re.compile(r'\s*(?:을|를|이|가|은|는)?\s*(?:(넘|초과|이상)|(이하|미만|안\s*되|못\s*미치))')
_INCOME_CUT = {'총급여': 5500, '종합소득': 4500}       # 공제율 기준(doc41)


def _f(s):
    return float(s.replace(',', '')) if s else 0.0


def money_spans(q):
    """[(만원 단위 값, 시작, 끝)]."""
    out = []
    for m in _MONEY.finditer(q):
        g = m.groupdict()
        if g['eok']:
            v = _f(g['eok']) * 10000 + _f(g['eok_cheon']) * 1000 + _f(g['eok_baek']) * 100 + _f(g['eok_man'])
        elif g['cheon']:
            v = _f(g['cheon']) * 1000 + _f(g['baek']) * 100 + _f(g['cman'])
        elif g['bcheon']:
            v = 1000 + _f(g['bbaek']) * 100
        elif g['mc']:
            v = _f(g['mc']) + _f(g['mc_cheon']) * 0.1
        elif g['mw']:
            v = _f(g['mw']) + _f(g['mw_won']) / 10000
        elif g['man']:
            v = _f(g['man'])
        else:
            v = _f(g['won']) / 10000
        if v > 0:
            out.append((v, m.start(), m.end()))
    return out


# 금액 앞(같은 문장)에서 가장 가까운 출처 말. 국민연금·월급·남편 금액이 연금저축 금액을 대신하지 않게 한다.
_SRC = [
    ('public', r'국민연금|공무원연금|사학연금|군인연금|기초연금|공적연금'),
    ('person', r'남편|아내|배우자|와이프|부인|부모님?|아버지|어머니|아버님|어머님|자녀|아들|딸'),
    # '퇴직급여'의 급여는 월급이 아니다 — 퇴직금 쪽 출처(10-14 3차 검토 200: '회사가 퇴직급여로 준 600만 원'을 월급 출처로 읽었다)
    ('earned', r'근로소득|월급|연봉|(?<!퇴직)(?<!퇴직\s)급여|사업소득|임대소득|이자|배당'),
    # 변액연금·즉시연금은 보험 상품이다 — 연금계좌(연금저축·IRP) 연금소득세로 계산하지 않는다(10-14 검토)
    ('insure', r'(?<!연금저축)보험|주택연금|농지연금|변액\s*연금|즉시\s*연금'),
    ('retire', r'퇴직금|퇴직급여|퇴직연금|DC|DB|확정\s*(?:기여|급여)'),
    ('private', r'연금저축|IRP|개인형|연금계좌|사적연금'),
]


# 출처 말을 부정하는 말 — '퇴직금 말고', '퇴직금이랑 별개로', '퇴직금 외에', '퇴직금은 빼고'. 이 말이 붙은 출처 말은 금액이 나온 곳이
# 아니다(10-14 4차 검토 301: 'IRP에 퇴직금 말고 따로 300만 원 넣으면'을 퇴직금 쪽 돈으로 읽고 블록에 '퇴직금 쪽에서 온 돈'을 실었다).
# '따로·별도로'는 '퇴직금이랑 따로'처럼 견주는 조사와 함께일 때만 부정이다 — '퇴직금(은) 따로 300만 원'은 '퇴직금 300만 원을 따로'일 수도
# 있어 모른다(_SRC_APART), 'IRP는 따로 300만 원'은 IRP 에 따로 넣는 말이다(부정으로 보면 IRP 납입을 연금저축으로 셌다)
# '퇴직금이랑은 별개로'처럼 견주는 조사 뒤 '은'도 받는다(10-14 5차 검토 408). '퇴직금은 없고·안 받았고'도 출처가 아니다
_SRC_NEG = re.compile(r'\s*(?:은|는|이|가|을|를)?\s*(?:(?:아직|전혀)\s*)?(?:말고|빼고|제외하고|외에|이외에|아닌|아니라|아니고|대신|없|(?:안|못)\s*(?:넣|옮|이체|받))'
                      r'|\s*(?:이랑|랑|하고|과|와)\s*(?:(?:은|는)\s*)?(?:별개로|별도로|따로)|\s*별개로')
_SRC_APART = re.compile(r'\s*(?:은|는)?\s*(?:따로|별도로)')
# 넣는 곳(계좌 이름)을 지우는 부정 — 출처 부정에서 '없·안/못 받'을 뺀 것. 'IRP가 없어서 새로 만들어 800만 원 넣으면'의 IRP는 넣는 곳
# 그대로다(10-14 6차 검토 500: 출처 부정을 같이 써 IRP를 지우고 연금저축 99만 원 — 맞는 값 132만 원). 넣는 곳은 넣는 동사에 가까운
# 계좌 이름이 정한다('IRP는 없고 연금저축에 800만 원'은 뒤의 연금저축)
_DEST_NEG = re.compile(r'\s*(?:은|는|이|가|을|를)?\s*(?:말고|빼고|제외하고|외에|이외에|아닌|아니라|아니고|대신|없이|(?:안|못)\s*(?:넣|옮|이체))'
                       r'|\s*(?:이랑|랑|하고|과|와)\s*(?:(?:은|는)\s*)?(?:별개로|별도로|따로)|\s*별개로')
# 덜어 내는 부정어 — '말고·빼고·제외하고·외에'. 뒤에 '없'이 오면('퇴직금 말고는 모아둔 돈이 없어서', '받은 거 외에는 돈이 없는데')
# '그것뿐'이라는 이중 부정이라 출처 말은 부정되지 않는다(6차 503: 이 꼴을 부정으로 읽어 본인 돈 49만 5천 원)
_SUBTRACT_NEG = re.compile(r'\s*(?:은|는|이|가|을|를)?\s*(?:말고|빼고|제외하고|외에|이외에)')
_ONLY_TAIL = re.compile(r'[^.?!\n]{0,24}?없(?!이|애|앴)')
# 출처 말에서 일부를 덜어 내는 꼴 — '퇴직금에서 세금 뗀 거 말고', '퇴직금 중 대출 갚을 돈 외에'. '에서·중'이 출처 말에 바로 붙어야
# 한다 — 'DC에 회사에서 넣어준 돈 빼고'의 '에서'는 회사 말이다(6차 504: 이를 덜어 냄으로 읽어 '퇴직금 쪽에서 온 돈'이라고 적었다).
# 덜어 내는 것이 출처에서 받은 돈 자체면('DC에서 받은 돈 빼고 제 돈') 부정 그대로다
_TAKE_V = r'(?:받|나온|나왔|들어온|들어왔|준|주신|지급|탄|쌓인|쌓여|모인|넣어|넣은|넣는)'
_SUB_AMT = r'(?:[\d,.]+\s*(?:억|천만|천|백만|만)?\s*원?\s*)?'      # '퇴직금 3천만 원 중'처럼 사이에 낀 금액
_WITHIN = re.compile(r'\s*' + _SUB_AMT + r'(?:에서|중에서|중에|중|가운데)\s+(?!' + _TAKE_V + ')')
# 계좌가 없다는 말 — '퇴직금 받을 IRP가 없어서 새로 만들어'의 '없'은 계좌가 없다는 말이지 퇴직금이 아니라는 말이 아니다
_ACCT_HEAD = re.compile(r'(?:개인형|IRP|연금\s*저축|계좌|DC|퇴직\s*연금)', re.I)
_EXIST_NEG = re.compile(r'\s*(?:은|는|이|가|을|를)?\s*(?:(?:아직|전혀)\s*)?없(?!이)')
# '퇴직금 안 받고 IRP로 300만 원 바로 넣으면' — 퇴직금을 현금으로 받지 않고 IRP로 옮기는 말일 수 있다. 출처(_source)에서는 부정이지만
# ('퇴직연금은 안 받고 연금저축에서 받으면'), 넣는 돈을 가를 때는 퇴직금 쪽 말로 남겨 _money_rel 이 가른다 — 마디가 끊긴 뒤 본인 돈
# 말이 오면 본인 돈, 아니면 모름(6차 501: 출처 부정으로 읽어 49만 5천 원). '아직 안 받았고'(지난 일)는 부정 그대로다
_NOT_TAKEN = re.compile(r'\s*(?:은|는|을|를)?\s*(?:(?:아직|전혀)\s*)?(?:안|못)\s*받고(?:서)?(?=[\s,]|$)')
# 출처 말을 꾸미는 말까지 묶어 부정하는 꼴 — '퇴직금 받은 거 말고', 'DC에 회사가 넣어준 돈 말고', '퇴직할 때 받은 돈 말고',
# '회사가 DC에 넣어주는 거랑 별개로'. 출처 말 바로 뒤 부정어만 보면 명사구 전체를 부정한 말을 못 읽어 '퇴직금 쪽에서 온 돈'이라고
# 적었다(10-14 5차 검토 407·408). 출처 말을 꾸미는 말(받은·넣어준·쌓인·들어온 …)이 '돈·거·것' 같은 이름에 붙고 그 뒤에 부정어가
# 올 때만 부정으로 본다 — 사이에 연결 어미('받아서·두고')가 있으면 한 명사구가 아니다. 꾸밈을 받는 이름이 계좌여도 같다('퇴직금 받은 IRP 말고')
_SRC_NEG_NP = re.compile(r'(?P<gap>[^.?!\n,]{0,24}?)\s+(?P<head>돈|거|것|걸|건|금액|부분|분|몫|부담금|적립금|퇴직\s*금|퇴직\s*급여'
                         r'|(?:개인형\s*)?IRP(?:\s*계좌)?|연금\s*저축(?:\s*계좌)?|계좌|DC|퇴직\s*연금)'
                         r'(?P<neg>' + _SRC_NEG.pattern + ')', re.I)
# 마디를 잇는 연결 어미 — '받아서·받고·두고·옮기고·받으면·받는데'. '하고'는 조사('퇴직금하고'), '에서'·'말고·빼고'는 연결 어미가 아니다
_CONNECT = r'[가-힣](?<![하에말빼])(?:고|서)(?=[\s,])|면서|[는은]데(?:요)?(?=[\s,])|지만|니까|(?:으면|[가-힣](?<![이])면)(?=[\s,])'


def _adnominal(ch):
    """꾸미는 꼴(관형형)로 끝나는 글자인가 — 받은·넣어준·쌓인·주는(받침 ㄴ), 받을(ㄹ), 받던."""
    return ch == '던' or ('가' <= ch <= '힣' and (ord(ch) - 0xAC00) % 28 in (4, 8))


def _only(text, m, grp=0):
    """부정어 뒤에 '없'이 와 '그것뿐'이라는 말인가 — '퇴직금 말고는 돈이 없어서'."""
    return bool(_SUBTRACT_NEG.match(m.group(grp)) and _ONLY_TAIL.match(text, m.end(grp)))


def _dest_negated(text, end):
    """text[:end] 끝의 계좌 이름이 넣는 곳에서 빠졌는가 — 'IRP 말고 연금저축에'. 'IRP가 없어서 새로 만들어'·'IRP 말고는 계좌가 없어서'는 아니다."""
    m = _DEST_NEG.match(text, end)
    return bool(m) and not _only(text, m)


def _neg_kind(text, end):
    """text[:end] 끝의 출처 말 뒤 부정어의 쓰임 → 'neg'(부정) / 'only'(말고는 … 없다 = 그것뿐) / 'sub'(출처에서 덜어 냄) / None."""
    m = _SRC_NEG.match(text, end)
    if m:
        return 'only' if _only(text, m) else 'neg'
    m = _SRC_NEG_NP.match(text, end)
    if not m or re.search(_CONNECT, m.group('gap')):
        return None
    if _only(text, m, 'neg'):
        return 'only'
    if _ACCT_HEAD.match(m.group('head')) and _EXIST_NEG.match(m.group('neg')):
        return None                     # '퇴직금 받을 IRP가 없어서' — 계좌가 없다는 말
    # '퇴직금에서 세금 뗀 거 말고·중 대출 갚을 돈 외에'는 퇴직금에서 덜어 내는 말이다 — 퇴직금은 그대로 출처
    if _SUBTRACT_NEG.match(m.group('neg')) and _WITHIN.match(m.group('gap')):
        return 'sub'
    if m.group('gap').strip() in ('', '의', '쪽', '쪽의'):
        return 'neg'                    # '퇴직금 돈 말고', 'DC 쪽 돈 말고'
    return 'neg' if _adnominal(text[:m.start('head')].rstrip()[-1]) else None


def _negated(text, end):
    """text[:end] 끝의 출처 말이 부정됐는가 — 바로 뒤 부정어('퇴직금 말고'), 또는 출처 말이 든 명사구 전체를 부정('퇴직금 받은 거 말고')."""
    return _neg_kind(text, end) == 'neg'


def _source(q, s):
    pre = re.split(r'[.?!\n]', q[max(0, s - 24):s])[-1]
    # 같은 마디('…받고 남편이 IRP에서 연 2,000만원')에 사람 말이 있으면 계좌 말보다 앞선다 — 남의 돈이다
    clause = re.split(r',|하고\s|받고\s|이고\s|그리고|이랑|랑\s|[와과]\s', pre)[-1]
    if re.search(_SRC[1][1], clause):
        return 'person'
    best, pos = None, -1
    for name, rx in _SRC:
        for m in re.finditer(rx, pre):
            if m.start() > pos and not _negated(pre, m.end()):
                best, pos = name, m.start()
    return best


# 규칙을 말하는 나이(55세 이후·70세 미만…)는 고객 나이가 아니다.
# '150 세금은요'의 '50 세'처럼 금액 끝자리와 세금·세액의 '세'를 나이로 읽지 않게 앞뒤를 막는다.
# 받는 나이('○세에 연금·개시·받')처럼 '○세에 수령하려던·타려던'도 고객 나이가 아니다(10차 검토 1003 이웃: '나이 50인데 65세에
# 수령하려던 연금저축 2000만원을 해지하면'을 65세 고객의 55세 이후 해지로 읽었다)
_AGE = re.compile(r'(?:만\s*)?(?<![\d,.])(\d{2})\s*(?:살|세(?![금액율제법]))'
                  r'(?!\s*(?:이후|이상|이하|미만|이전|전|부터|까지|넘|되|가\s*되|도\s*안|도\s*아직|안\s*됐|안\s*되'
                  r'|에\s*(?:연금|개시|받|수령|(?:타|탈|탄)(?=려|기|고|는|던|면|게|서|\s))))')
_DECADE = re.compile(r'([5-9])0\s*대')


# '65세에 연금저축에서 연 1,200만 원을 받으면' — 받는 나이(10-14 외부 검토: age·rate_age 둘 다 비어 블록이 구간 셋을 다 실었다).
# '에'는 뒤 동사가 앞으로 받는 꼴(받으면·받을 때·개시하면)일 때만 — '65세에 개시해서 지금 7년째 받고 있어요'(지난 개시 나이),
# 'IRP는 70세에 받고 연금저축은 지금'(다른 계좌)의 나이로 세율을 정하면 틀린다(10-14 검토: 5.5% → 4.4%로 44만 원)
_RECV_LATER = (r'(?:받(?:으면|으려면|을\s*(?:때|경우|거|건|계획|예정|생각)|는다면|게\s*되면|기\s*시작하면|고(?!\s*있))'
               r'|(?:수령|개시)(?:하면|하려면|할\s*(?:때|경우|거|건|계획|예정|생각)|한다면|하게\s*되면|하기\s*시작하면))')
_FUTURE_AGE = re.compile(r'(?<![\d,.])(\d{2})\s*(?:살|세)\s*(?:부터|이\s*되면|가\s*되면|되면|되어서|넘어서|넘으면|이후에'
                         r'|(에)(?=[^.?!\n]{0,30}?' + _RECV_LATER + r'))')
# '연금저축은 지금 받으려고' — 지금 받는다는 말이 있으면 '○세에'는 받는 나이로 쓰지 않는다.
# 지금 받는 것이 연금이 아니면('지금 받는 월급이 5천인데 75세에 연금저축에서 …') 연금 얘기가 아니다 —
# 10-14 2차 검토: '지금 받는 월급'을 보고 75세를 버려 4.4% 44만 원이 5.5% 55만 원으로 틀렸다
_NOT_PENSION_NOUN = (r'(?:월급|급여|연봉|봉급|월\s*소득|소득|이자|배당|월세|임대료|성과급|보너스|상여|용돈'
                     r'|국민\s*연금|공무원\s*연금|사학\s*연금|군인\s*연금|기초\s*연금|공적\s*연금)')
_RECV_NOW = re.compile(r'(?:지금|현재|당장)\s*(?:은|부터)?\s*(?:바로\s*)?(?:연금\s*(?:을|으로)?\s*)?(?:받|수령|개시)'
                       r'(?!(?:하|하고\s*있|고\s*있)?(?:는|은|던|았던|한)\s*' + _NOT_PENSION_NOUN + r')')
# '지금 받는 ○○' — 받는 것을 꾸미는 꼴이면 그 낱말(○○)
_RECV_NOW_NOUN = re.compile(r'(?:하|하고\s*있|고\s*있)?(?:는|은|던|았던|한)\s+([가-힣A-Za-z]+)')
_RECV_LATER_RX = re.compile(_RECV_LATER)


def _recv_now_kind(q):
    """'지금 받…'이 받는 나이 '○세에'와 엇갈리는가 → None(그런 말이 없거나 연금 아닌 것을 받음) / 'pension' / 'unsure'.
    받는 것을 말하지 않거나('연금저축은 지금 받으려고' — 1차 결함 3) 연금이면 지금 받는 연금이다. 받는 것이 연금 아닌 낱말 목록에
    없는 다른 낱말이면('지금 받는 수당이') 무엇인지 확신할 수 없다 — 낱말 목록을 늘리지 않고 받는 나이를 정하지 않는다(숫자 하나로 정하지 않음)."""
    kind = None
    for m in _RECV_NOW.finditer(q):
        if '연금' in m.group(0):
            return 'pension'
        n = _RECV_NOW_NOUN.match(q, m.end())
        if not n or re.match(r'(?:연금|IRP|개인형|수령액)', n.group(1), re.I):
            return 'pension'
        kind = 'unsure'
    return kind


def rate_age(p):
    """세율을 정할 나이 — 받는 나이를 따로 말했으면 그 나이, 아니면 고객 나이. 받는 나이가 지금인지 ○세인지 엇갈리면 None."""
    if p.get('rate_age_unsure'):
        return None
    return p.get('rate_age') or p.get('age')


def customer_age(q):
    """질문에 나이가 하나로 분명하면 그 나이, 아니면 None. 60대처럼 연대면 ('대', 60)."""
    ages = {int(a) for a in _AGE.findall(q) if 19 <= int(a) <= 99}
    if len(ages) == 1:
        return ages.pop()
    if ages:
        return None                     # 나이가 둘 이상 — 누구 나이인지 모른다
    ds = {int(d) * 10 for d in _DECADE.findall(q)}
    if len(ds) == 1:
        return ('대', ds.pop())
    return None


def rate_for_age(age):
    """(세율 %, 구간 설명) 또는 None. 문서 표(doc38) 구간 그대로."""
    if isinstance(age, tuple):              # 연대: 60대 → 55~69 구간에 온전히 든다
        d = age[1]
        if d == 60:
            return 5.5, '55세 이상 70세 미만'
        if d == 70:
            return 4.4, '70세 이상 80세 미만'
        if d >= 80:
            return 3.3, '80세 이상'
        return None                     # 50대는 55세 전후가 섞인다
    if age is None or age < 55:
        return None
    if age < 70:
        return 5.5, '55세 이상 70세 미만'
    if age < 80:
        return 4.4, '70세 이상 80세 미만'
    return 3.3, '80세 이상'


_YEARLY = re.compile(r'(?:1년|일년|연간?|매년|한\s*해|해마다)\s*(?:에|에만|동안)?\s*(?:납입(?:액|금)?\s*)?(?:은|는|이|가)?\s*(?:약|대략|한)?\s*$')
_MONTHLY = re.compile(r'(?:(?<![\d개])월|매달|매월|한\s*달(?:에)?|달마다)\s*(?:에|에만)?\s*(?:납입(?:액|금)?\s*)?(?:은|는|이|가)?\s*(?:약|대략|한)?\s*$')
_INCOME_PRE = re.compile(r'(총\s*급여|연봉|(?<!퇴직)(?<!퇴직\s)급여|근로소득|종합소득(?:금액)?|사업소득|소득)\s*(?:\([^)]{0,8}\)\s*)?(?:기준(?:으로)?\s*)?(?:이|가|은|는|이요|가요)?\s*(?:약|대략|한)?\s*$')
_OTHER_PERSON = re.compile(r'남편|아내|배우자|와이프|부인|부모|아버지|어머니|자녀|아들|딸')
# 납입하는 사람이 남(회사·가족)이라는 말 — '회사에서 … DC에 넣어 주는데', '아내가 … 연금저축에 넣으면', '아내 연금저축에'
_PAYER_OTHER = re.compile(r'(?:회사|사측|사업주|고용주)\s*(?:에서|가|이|측에서|측이)(?=\s)'
                          r'|(?:남편|아내|배우자|와이프|부인|부모|아버지|어머니|아버님|어머님|자녀|아들|딸)(?:님)?'
                          r'(?:\s*(?:이|가|께서|의|은|는|도)(?=\s)|\s*(?=연금\s*저축|IRP|개인형|계좌|명의))', re.I)


def _payer_is_source(who, mid):
    """남(회사·가족) 말과 금액 사이(mid)에서 다른 동사가 그 마디를 닫았으면 남은 넣는 사람이 아니라 돈이 나온 곳이다.
    '회사에서 성과급 받은 600만 원 IRP에 넣으면', '부모님이 주신 600만 원 IRP에 넣으면' — 넣는 사람은 고객이다
    (10-14 2차 검토: '회사에서'만 보고 본인 납입을 빼 99만 원이던 답이 공제율만 냈다).
    닫는 말이 납입·부담금이면('회사에서 넣어 준 300만 원', '회사에서 내주는 부담금') 남이 넣은 돈 그대로다.
    가족이 받은 돈('아내가 받은 성과급')은 누가 넣는지 모르므로 남의 돈으로 둔다(확신이 없으면 숫자를 내지 않는다)."""
    if re.search(_IN_VERB + r'|(?<!보)내\s*(?:준|주는|줬|주신)|부담|적립', mid):
        return False
    give = r'(?:(?<![가-힣])|(?<=[어아내]))(?:준|주신|주는|줬|주셨)(?=\s|$)'     # '기준'의 '준'은 아니다, '보내준'은 준 것
    if re.match(r'회사|사측|사업주|고용주', who):
        return bool(re.search(r'받(?:은|는|았|던)|(?<![가-힣])탄(?=\s)|지급(?:한|된|받은)|나온|나왔|들어온|들어왔|' + give, mid))
    return bool(re.search(give, mid))


# 남(회사·가족) 말과 금액 사이의 부정·대체 말 — '성과금 대신', '격려금 외에', '지원금과 별도로', '넣어준 돈 말고'. '해외에'는 아니다
_PAYER_ALT = re.compile(r'(?:과|와|이랑|랑|은|는|을|를)?\s*(?<!해)(?:이외에|외에|별개로|별도로|대신|말고|빼고|제외하고)'
                        r'(?:에|는|도|에도|에는)?(?=[\s,]|$)')
# 남이 넣은·준 다른 돈을 꾸미는 마디 — '(매달) 넣어주는 돈', '쌓아준 돈', '내준 부담금', '받은 성과급'. 이 꼴로 닫힌 명사구 안의
# 회사·가족은 그 명사구(다른 돈)의 주어다. 끝 글자 받침(ㄴ·ㄹ)으로 가리면 '이번·연말·매달' 같은 이름씨·어찌씨도 걸려(6차 검토 600~609의
# '성과금·현금'처럼 맨 명사도 끝 글자로 끊었다) 돈을 옮기는 움직씨의 꾸미는 꼴만 받는다 — 모르는 움직씨면 남이 넣는 돈으로 둔다
_PAYER_REL = re.compile(r'(?<![가-힣])(?:(?:넣어|쌓아|부어|채워|내|해)\s*)?'
                        r'(?:준|주는|주신|주시는|주던|줬던|받은|받는|받던|쌓인|모인|모은|들어온|들어오는|나온|나오는|넣은|넣는|낸|내는'
                        r'|지급한|지급하는|지급된|지급되는|적립한|적립하는|적립된|적립되는|부담한|부담하는|입금한|입금된|이체한|이체된)'
                        r'(?:\s+\S+){1,2}\s*$')
# 본인 돈·본인이 넣는다는 말 — 금액 쪽 마디(부정·대체 말 뒤)에 있을 때만 본인 납입이다. '직접'만으로는 넣는 사람을 모르고
# ('회사에서 직접 넣어 준대요'), '제 IRP에'의 '제'는 계좌 주인이지 넣는 사람이 아니다
_OWN_SIDE = re.compile(r'(?:본인|개인|가입자)\s*(?:부담금?|돈)|(?<![가-힣])(?:제|내|나의|저의|여윳?)\s*돈|자비|사비|개인\s*적으로'
                       r'|(?:월급|봉급)\s*(?:에서|으로|로)|(?<![가-힣])(?:제가|내가|본인이|본인도|본인은|저도|저는|나는)(?![가-힣])')
# '아내 명의 말고 제 명의로', '아내 IRP가 아니라 제 IRP에' — 남 말이 계좌 주인(아내 명의·아내의 연금저축)이면 '제 계좌'는 넣는 곳이
# 본인 계좌라는 말이다. 남이 주어일 때('아버지가 제 연금저축에 넣어 주시면')는 넣는 사람이 그대로 남이다
_OWN_ACCT = re.compile(r'(?<![가-힣])(?:제|내|저의|나의)\s*(?:명의|이름|계좌|개인형|IRP|연금\s*저축|DC|퇴직\s*연금)', re.I)


def _own_side(text, who):
    """남 말(who) 뒤 금액 쪽 말(text)에 본인이 넣는다는 말이 있는가."""
    owner = not re.search(r'(?:이|가|께서|은|는|도|에서|측이)$', who.rstrip())
    return bool(_OWN_SIDE.search(text) or owner and _OWN_ACCT.search(text))


# 금액 뒤 본동사가 남이 해 주는 꼴 — '넣어 준대요', '넣어 주시면', '부어 준다는데', '내준대요'
_GIVE_MAIN = re.compile(r'[^.?!\n,]{0,30}?(?:(?:넣어|부어|채워|쌓아|적립해|납입해|입금해|불입해|이체해)\s*|(?<![가-힣])내)'
                        r'(?:주|준|줄|줘|줬|드리|드릴)')


def _payer_other(q, x):
    """금액 x 를 넣는 사람이 남(회사·가족)인가 — 남이 넣는 돈은 질문한 사람의 세액공제 납입이 아니다.
    남 말과 금액 사이의 '대신·외에·별도로·말고'는 무엇을 대신하는지(성과금·현금·용돈)를 가리킬 뿐 넣는 사람을 바꾸지 않는다 —
    '회사에서 성과금 대신 300만 원을 DC에 넣어 준다는데'는 회사가 넣는 돈이다(10-14 7차 검토 600~609: 6차가 맨 명사 끝 글자 '금'
    뒤에서 마디를 끊어 회사를 지우고 가입자부담금 49만 5천 원). 본인 납입은 본인 돈 말(제 돈·자비·본인 부담·제가)이 금액 쪽 마디에
    있을 때('회사에서 쌓아준 돈 외에 본인 부담으로 300만 원'), 또는 남이 다른 돈을 꾸미는 마디의 주어일 뿐이고('회사에서 넣어준 돈
    말고 300만 원 더 넣으면') 본동사가 남이 해 주는 꼴('넣어 준대요')이 아닐 때다."""
    sa = max(q.rfind(c, 0, x['s']) for c in '.?!\n') + 1
    # 마디는 쉼표·연결 어미에서 끊는다. '말고·빼고·제외하고'는 연결 어미가 아니라 명사구를 부정하는 말이라 끊지 않고 아래에서 본다
    # (끊으면 '회사에서 성과금 말고 300만 원 넣어 준대요'의 회사가 지워진다)
    payer = re.split(r'[,]|(?:(?<!말)(?<!빼)(?<!제외하)고|는데|지만|면서|며)\s', q[max(sa, x['s'] - 30):x['s']])[-1]
    po = list(_PAYER_OTHER.finditer(payer))
    if not po:
        return False
    who, mid = po[-1].group(0), payer[po[-1].end():]
    alt = list(_PAYER_ALT.finditer(mid))
    if alt:
        a = alt[-1]
        if _own_side(mid[a.end():], who):
            return False                # 금액 쪽 마디에 본인 돈 말
        np = mid[:a.start()]
        if _PAYER_REL.search(np) or _payer_is_source(who, np):
            # 남은 다른 돈(명사구)의 주어 — 이 금액을 넣는 사람은 본동사가 정한다
            return bool(_GIVE_MAIN.match(q, x['e']))
        return True                     # '회사에서 성과금 대신', '회사가 지원금과 별도로', '회사에서 별도로' — 넣는 사람은 남
    # 부정·대체 말이 없을 때도 같은 본인 말로 본다 — 전엔 '제\s'를 받아 '아버지가 제 연금저축에 300만 원 넣어 주시면'을 본인 납입으로 셌다
    return not _own_side(mid, who) and not _payer_is_source(who, mid)


# 계좌가 있다·없다는 말 — 'IRP만 있고', '연금저축은 없어서', 'IRP 계좌가 아직 없는데', 'IRP 가입돼 있고'. 이 말로만 나온 계좌는
# 가진 계좌를 밝힌 것이지 넣는 곳을 말한 것이 아니다. 'IRP 없이'(_DEST_NEG)는 넣는 곳에서 빠진 말이라 따로 본다
_ACCT_EXIST = re.compile(r'\s*(?:계좌)?\s*(?:은|는|이|가|만|도)?\s*(?:(?:아직|전혀|하나도|하나|따로|이미|벌써)\s*)?'
                         r'(?:가입\s*(?:이\s*)?(?:돼|되어|해|된\s*게|한\s*게)?\s*|(?:가지고|갖고|보유하고|들고)\s*)?(?:(있)|없(?!이|애|앨|앴))')
# '없애·없앨'은 계좌를 닫는 말이지 '없다'가 아니다 — '연금저축은 없애려고 하는데 IRP도 있어서'(10차 검토 1000 이웃)
# 계좌를 새로 만든다는 말 — 'IRP가 없어서 새로 만들어 800만 원'의 IRP는 넣는 곳이다
_ACCT_NEW = re.compile(r'만들|개설|가입|신규|(?<![가-힣])(?:트고|터서|터|열어|열고)(?![가-힣])')


def _acct_id(name):
    """계좌 이름 → 같은 계좌면 같은 값('개인형 IRP'·'IRP'·'개인형' → 'IRP')."""
    return re.sub(r'\s+|개인형', '', name).upper() or 'IRP'


# 앞 계좌 마디가 넣겠다는 말인지 — '넣으려고 하는데·넣으려는데·납입하려고·넣고 싶은데·넣고자·넣기로·넣어야 하는데·넣겠'.
# 'ㄹ 건데·ㄹ 예정·ㄹ까'는 _will_spots 가 본다. '넣으려고 했는데·넣고 싶었는데'는 하려다 바꾼 말일 수 있어 모름.
# 어미만으로는 넣겠다는 말이 아니다 — 어미가 넣는 말(_PUT_STEM)에 붙었을 때만 본다(_put_intent, 10차 검토 1000~1002)
_CL_INTENT = re.compile(r'려(?:고|는|던|면|\s*(?:하|해|한))|고\s*싶|고자|기로|(?:어|아|여|해|워)\s*야|겠')
_CL_INTENT_PAST = re.compile(r'려\s*(?:고\s*)?(?:했|하였)|싶었|야\s*했|까\s*했|려던')
# 넣는 말의 줄기 — 어미 바로 앞에 오는 꼴. '채·모·부'는 '채울·모을·부을·채워야·모아야·부어야'처럼 어미와 붙은 꼴의 앞 글자,
# '넣어 보려고·넣어 두려고'는 보조 동사를 건너 본다. 9차는 어미만 봐서 '해지하려는데·깨려고 하는데'(닫는 말)와 '모르겠고'의
# '겠'까지 넣겠다는 말로 읽어 닫을 계좌를 넣는 곳으로 골랐다(1000: '연금저축은 해지하려는데 IRP도 있어서 800만 원'이 연금저축 99만 원)
_PUT_CORE = r'(?:넣|(?:납입|입금|불입|적립)\s*(?:을|를)?\s*(?:하|해)?|붓|(?<![가-힣])(?:부|채|채우|모|모으))'
# 계좌를 새로 만든다는 말('IRP를 새로 만들려고·개설하려고·가입하려는데')도 그 계좌가 넣는 곳이다(_ACCT_NEW 와 같은 뜻, 9차 그대로)
_NEW_CORE = r'(?:만들|(?:개설|가입)\s*(?:만|을|를)?\s*(?:하|해)?|(?<![가-힣])(?:트|열))'
_PUT_STEM = re.compile(r'(?:' + _PUT_CORE + r'|' + _NEW_CORE + r')(?:(?:어|아|워)\s*(?:보|두|놓|놔))?\s*으?$')
# 넣지 않겠다는 말 — '넣지 않으려고·납입하지 말까'. 그 계좌는 넣는 곳이 아니다
_PUT_NEG_STEM = re.compile(_PUT_CORE + r'\s*지\s*(?:는|도|만)?\s*(?:않|말|마)\s*(?:으|을)?$')
# 넣으려다 만 말 — 'IRP에 넣으려다 말고 연금저축도 있어서'의 IRP는 넣는 곳이 아니다
_PUT_DROP = re.compile(_PUT_CORE + r'\s*으?려다(?:가)?\s*(?:말|그만|못)')
# 계좌를 닫는 말(_CL_SHUT)은 _HAEJI·_BREAK 뒤에 둔다
# 이미 하고 있는 일 — '넣고 있고', '넣는 중', '매달 넣고'
_CL_ONGOING = re.compile(r'고\s*있|는\s*중|매달|매월|매년|꾸준히|자동\s*이체')
# 남이 넣어 주는 말 — 'DC에 넣어주고'(주어가 빠져도 넣는 사람은 고객이 아니다)
_CL_GIVE = re.compile(r'(?:넣어|부어|채워|쌓아|적립해|납입해|입금해)\s*(?:주|준|줘|줬)|(?<![가-힣])내\s*(?:주|준|줘|줬)')
_CL_BARE_NUM = re.compile(r'(?<![\d,.A-Za-z])\d{2,5}(?![\d,.])(?!\s*(?:년|세|살|%|형|TDF|빈티지))', re.I)


def _will_spots(text):
    """받침 ㄹ 꾸밈꼴 + 앞일 말의 자리 — (ㄹ 글자 위치, 앞일 말 끝). '넣을 것 같은데'의 '것'도 앞일 말이다."""
    for m in re.finditer(r'([가-힣])\s*(?:건|거|겁|것|예정|계획|생각|참|까|지)', text):
        if (ord(m.group(1)) - 0xAC00) % 28 == 8:
            yield m.start(), m.end()


def _put_intent(mid):
    """앞일 어미가 넣는 말에 붙었나 → 'intent'(넣겠다) / 'past'(하려다 바꾼 말 — '넣으려고 했는데') / 'neg'(안 넣겠다) / None.
    어미만 보면 '해지하려는데·깨려고 하는데'(닫는 말)·'모르겠고'(동사가 '모르')도 넣겠다는 말로 읽는다(10차 검토 1000~1002) —
    어미 바로 앞이 넣는 말(넣·납입·입금·붓·채우·적립·모으)일 때만 본다. ㄹ 꾸밈꼴('넣을 건데·채울 생각')은 ㄹ 글자 앞까지가 줄기다."""
    if _PUT_DROP.search(mid):
        return 'neg'                        # '넣으려다 말고' — 하려다 그만둔 계좌
    spots = [(m.start(), m.end()) for m in _CL_INTENT.finditer(mid)] + list(_will_spots(mid))
    for s, e in sorted(spots):
        if _PUT_NEG_STEM.search(mid, 0, s):
            return 'neg'                    # '넣지 않으려고' — 그 계좌에는 넣지 않는다
        stem = _PUT_STEM.search(mid, 0, s)
        if not stem:
            continue
        if _CL_SHUT_NEG_BEFORE.search(mid, 0, stem.start()):
            return 'neg'                    # '안 넣으려고·더는 안 넣고 싶은데·못 넣을 것 같은데'
        return 'past' if _CL_INTENT_PAST.search(mid, s, e + 6) else 'intent'
    return None


def _shut_kind(mid):
    """앞 계좌 마디에 계좌를 닫는 말이 있나 → 'shut'(해지·깨·빼·옮기·이전·갈아타·정리·인출하려는 계좌) / 'move_in'(돈이 옮겨 가는
    계좌 — '연금저축으로 옮기려고') / 'kept'(부정된 닫는 말 — '해지하지 않고·해지 안 하고·안 깨고') / None."""
    kept = None
    for m in _CL_SHUT.finditer(mid):
        if _CL_SHUT_NEG_AFTER.match(mid, m.end()) or _CL_SHUT_NEG_BEFORE.search(mid, 0, m.start()):
            kept = 'kept'
            continue
        if _CL_MOVE.match(m.group(0)) and re.match(r'\s*(?:계좌)?\s*(?:으로|로|에다가|에다|에)(?![가-힣])', mid):
            return 'move_in'
        return 'shut'
    return kept


def _clause_kind(lead, mid):
    """앞 계좌 마디 → 'done'(이미 넣은 돈·남이 넣는 돈·닫을 계좌 — 이 금액을 넣는 곳이 아니다) / 'intent'(넣겠다는 말 — 그 계좌가
    넣는 곳) / None(모름). lead 는 계좌 이름 앞(같은 마디), mid 는 이름 뒤부터 다른 계좌의 있다·없다 말 앞까지.
    8차가 '이름 + 연결 어미 + 다른 계좌의 있다·없다'만 보고 닫아, 넣겠다는 마디('IRP에 넣으려고 하는데 연금저축도 있어서 800만 원')의
    IRP까지 빼고 연금저축 99만 원을 냈다(9차 검토 800 — 8차 전 사본은 IRP 132만 원). 닫는 근거는 남이 넣는 말, 그 마디의 금액,
    닫는 동사(해지·깨·옮기…), 지난·진행 동사다. 넣겠다는 말이면 그 계좌, 둘 다 아니면('IRP에 넣고 연금저축도 있는데') 판마다 갈린
    꼴이라 모름(되묻기). 9차는 어미(려고·고 싶·겠)만 보고 동사를 안 봐 '연금저축은 해지하려는데 IRP도 있어서 800만 원'을 연금저축
    99만 원, '연금저축에 넣었는데 잘 모르겠고 IRP도 있는데'를 연금저축으로 냈다(10차 검토 1000~1002 — HEAD·9차 전은 IRP)."""
    if _PAYER_OTHER.search(lead + mid) or _CL_GIVE.search(mid):
        return 'done'
    if _MONEY.search(mid) or _CL_BARE_NUM.search(mid):
        return 'done'                       # '연금저축에 600만 원 채웠고' — 그 마디의 금액이 따로 있다
    shut = _shut_kind(mid)
    if shut == 'shut':
        return 'done'                       # '연금저축은 해지하려는데' — 닫을 계좌에 새 돈을 넣지 않는다
    if shut == 'move_in':
        return None                         # '연금저축으로 옮기려는데' — 옮겨 받는 계좌, 이 금액도 거기인지는 모름
    put = _put_intent(mid)
    if put == 'intent':
        return 'intent'
    if put == 'neg':
        return 'done'
    if put == 'past':
        return None
    # 지난 일 — 받침 ㅆ('넣었·채웠·납입했·냈·부었'). '있'(있다)·'겠'(앞일)은 아니다
    if _CL_ONGOING.search(mid) or any('가' <= ch <= '힣' and ch not in '있겠' and (ord(ch) - 0xAC00) % 28 == 20 for ch in mid):
        return 'done'
    return None


def _dest_parts(wide):
    """금액 앞 같은 마디(wide)에서 넣는 곳 계좌 이름 → (이름 목록, 넣는 곳을 모름, 앞 마디에 닫힌 계좌 이름 목록).
    넣는 곳은 넣는 동사에 가장 가까운 계좌 이름이 아니라 넣겠다고 한 계좌('연금저축에', 'IRP 300')나 새로 만든다고 한 계좌다.
    있다·없다로만 나온 계좌는 넣는 곳이 아니다 — 'IRP만 있고 연금저축은 없어서 800만 원 넣으면'은 어느 계좌에 넣는지 분명하지
    않다(10-14 7차 검토 610: 6차가 넣는 곳 부정에서 '없'을 빼 넣는 동사에 가까운 연금저축으로 99만 원, 5차는 '없'으로 연금저축을
    지워 IRP 132만 원 — 판마다 갈리는 것 자체가 모른다는 뜻). 있다고 한 계좌 하나만 나오면('IRP만 있어서 800만 원') 그 계좌,
    없다고 한 계좌를 새로 만든다고 하면('IRP가 없어서 새로 만들어') 그 계좌, 나머지는 모름(숫자 없이 되묻기).
    계좌 이름 뒤 연결 어미로 마디가 닫히고 다른 계좌의 있다·없다 말이 이어지면('연금저축에 600만 원 채웠고 IRP는 있는데',
    'DC에 회사가 넣어주고 IRP도 있는데') 앞 계좌는 그 마디의 일(이미 넣은 돈·회사가 넣는 돈)을 말한 것이지 이 금액을 넣는 곳이
    아니다 — 넣는 곳은 뒤에 있다·새로 만든다고 한 계좌다(8차 700~707: 7차가 앞 계좌를 넣는 곳으로 읽어 HEAD 에서 맞던
    IRP 148만 5천 원이 연금저축 99만 원이 됐다). 닫힌 앞 계좌는 셋째 값으로 돌려 parse 가 되묻기 판단에 쓴다.
    닫힘은 앞 마디가 이미 한 일·남이 하는 일일 때만이다 — 넣겠다는 마디('IRP에 넣으려고 하는데 연금저축도 있어서')의 계좌는
    넣는 곳이고, 어느 쪽인지 모르면 되묻는다(_clause_kind, 9차 검토 800)."""
    plain, exist = [], []
    for m in re.finditer(r'개인형\s*IRP|IRP|개인형|DC|퇴직\s*연금|확정\s*기여|연금저축', wide, re.I):
        if _dest_negated(wide, m.end()):
            continue
        ex = _ACCT_EXIST.match(wide, m.end())
        if ex:
            exist.append((m.group(0), bool(ex.group(1)), ex.end(), m.start()))
        else:
            plain.append((m.group(0), m.end(), m.start()))
    state = []
    for n, end, st in plain:
        nxt = [e for e in exist if _acct_id(e[0]) != _acct_id(n) and e[3] >= end and re.search(_CONNECT, wide[end:e[3]])]
        if not nxt:
            # 닫는 말은 연결 어미가 _CONNECT 밖이어도('해지할 건데·깰 건데') 그 계좌를 닫는다 — 닫을 계좌에 새 돈을 넣지 않는다
            # (10차 검토 1000 이웃: '연금저축은 해지할 건데 IRP도 있어서 800만 원'이 연금저축 99만 원, HEAD 는 IRP 132만 원)
            # 부정된 닫는 말('해지 안 하고 IRP도 있는데')은 마디가 끝난 말이지만 넣겠다는 말도 아니라 모름. '넣으려다 말고'(말고는
            # _CONNECT 밖)도 넣지 않는다는 말이라 닫힌 계좌
            after = [e[3] for e in exist if _acct_id(e[0]) != _acct_id(n) and e[3] >= end]
            # 그 계좌의 마디 — 다음 계좌 이름 앞까지('연금저축에 넣으려는데 IRP는 해지해서'의 해지는 IRP 것)
            nxt_names = [x[2] for x in plain if x[2] >= end] + [e[3] for e in exist if e[3] >= end]
            seg = wide[end:min(nxt_names)] if nxt_names else wide[end:]
            sk = _shut_kind(seg)
            if sk is None and _put_intent(seg) == 'neg':
                sk = 'shut'
            if after:
                state.append({'shut': 'closed', 'kept': 'unsure'}.get(sk, 'open'))
            else:
                # 뒤에 다른 계좌의 있다·없다 말이 없으면(금액까지가 그 마디) 다른 넣는 곳 후보가 있을 때만 닫는다 — 'IRP도 있는데
                # 연금저축은 해지하려고 해서 800만 원'(앞에 있다고 한 IRP)·'연금저축에 넣으려는데 IRP는 해지해서'(HEAD 부터 닫을 계좌로
                # 계산). 후보가 없으면('연금저축 깨서 800만 원 넣으면') 지금처럼 그 계좌로 본다
                state.append('soft' if sk == 'shut' else 'open')
            continue
        cuts = [c.end() for c in re.finditer(_CONNECT, wide[:st])]
        kind = _clause_kind(wide[cuts[-1] if cuts else 0:st], wide[end:min(e[3] for e in nxt)])
        if kind == 'intent' and any(not e[1] and _ACCT_NEW.search(wide, e[2]) for e in nxt):
            kind = 'torn'                   # 'IRP에 넣으려는데 연금저축이 없어서 새로 만들어' — 넣겠다는 계좌와 새로 만드는 계좌가 갈린다
        state.append({'done': 'closed', 'intent': 'open', 'torn': 'torn'}.get(kind, 'unsure'))
    if 'soft' in state:
        live = {_acct_id(p[0]) for p, s in zip(plain, state) if s == 'open'} | {_acct_id(e[0]) for e in exist if e[1]}
        state = [('closed' if live - {_acct_id(p[0])} else 'open') if s == 'soft' else s for p, s in zip(plain, state)]
    closed = [p[0] for p, s in zip(plain, state) if s == 'closed']
    cur = [p[0] for p, s in zip(plain, state) if s == 'open']
    if cur or not exist:
        return cur, False, closed
    if 'torn' in state:
        return [], True, closed
    neg = [e for e in exist if not e[1]]
    if neg and _ACCT_NEW.search(wide, neg[-1][2]):
        return [neg[-1][0]], False, closed      # 없는 계좌를 새로 만들어 넣는다
    if 'unsure' in state:
        return [], True, closed             # 앞 마디가 넣겠다는 말인지 이미 한 일인지 모름 — 숫자 없이 되묻는다
    if not neg and len({_acct_id(e[0]) for e in exist}) == 1:
        return [exist[-1][0]], False, closed    # 있다고 한 계좌 하나뿐
    return [], True, closed


def _dest_names(wide):
    """금액 앞 같은 마디(wide)에서 넣는 곳 계좌 이름 → (이름 목록, 넣는 곳을 모름). _dest_parts 참고."""
    return _dest_parts(wide)[:2]


# 퇴직금 쪽 낱말 — 돈 이름(퇴직금·퇴직급여)과 계좌 이름(DC·DB·퇴직연금)
# '퇴직소득세'는 세금 이름이지 돈 이름이 아니다
_RETIRE_WORD = re.compile(r'(퇴직\s*금|퇴직\s*급여|퇴직\s*소득(?!\s*세)|이연\s*퇴직)|((?<![A-Za-z])D[CB](?![A-Za-z])|퇴직\s*연금|확정\s*(?:기여|급여))',
                          re.I)
# DC·퇴직연금 계좌에 본인이 넣는 말 — 'DC에 제가 매달 30만 원', 'DC에 개인부담금 300만 원', 'DC로 300만 원 넣으면'.
# 계좌 이름과 금액 사이에 이런 말만 있을 때('퇴직연금(DC)에'처럼 괄호로 닫은 이름도)
_RETIRE_DEST = re.compile(r'^\)?(?:형)?\)?(?:\s*계좌)?\s*(?:에|에다|에다가|으로|로)\s*(?:도|만|는)?\s*'
                          r'(?:(?:제가|내가|본인이|본인도|본인은|저도|저는|나는|직접|(?:개인|가입자|본인)\s*부담금(?:으로|로)?|추가로?|더|따로'
                          r'|별도로?|매달|매월|월|연간?|1년에|올해|한\s*달에?)\s*){0,4}$')
# 본인 돈이라는 말 — '본인 부담으로', '제 돈으로', '내 돈', '자비로', '사비로', '개인적으로'. 문서(doc55)는 가입자가 본인 부담으로
# 추가로 넣는 가입자부담금을 연 900만 원까지 세액공제 대상으로 적는다(10-14 4차 검토 300: 'DC에 본인 부담으로 300만 원'을 퇴직금 쪽 돈으로 읽었다)
_OWN_PAY = re.compile(r'(?:본인|개인|가입자)\s*(?:부담금?|돈)|(?<![가-힣])(?:제|내|나의|저의|여윳?)\s*돈|자비|사비|개인\s*적으로|직접'
                      r'|(?<![가-힣])(?:제가|내가|본인이|본인도|본인은|저도|저는|나는)(?![가-힣])')
# 돈이 본인 것이라는 말 — 돈을 가리키는 말만('제 돈·자비·본인 부담·월급에서'). 주어 말(제가·내가·본인이·직접)은 넣는 사람을 가리킬 뿐
# 돈이 어디서 왔는지는 말하지 않는다(10-14 5차 검토 406: '퇴직금을 제가 IRP에 300만 원'을 '제가'만 보고 본인 돈으로 읽어 49만 5천 원).
# DC·퇴직연금은 넣는 사람이 곧 부담금을 가르므로(회사 부담금 / 가입자부담금) 그쪽 판정은 주어 말까지 보는 _OWN_PAY 를 쓴다
_OWN_MONEY = re.compile(r'(?:본인|개인|가입자)\s*(?:부담금?|돈)|(?<![가-힣])(?:제|내|나의|저의|여윳?)\s*돈|자비|사비'
                        r'|(?:월급|봉급|(?<!퇴직)(?<!퇴직\s)급여)\s*(?:에서|으로|로)')
# 계좌 이름(DC·퇴직연금)과 금액 사이에서 그 계좌가 돈이 나온 곳임을 보이는 말 — 'DC에서', 'DC로 준·받은', 'DC에 쌓인·쌓아 준'
_RETIRE_FROM = re.compile(r'에서|(?:으로|로)\s*(?:준|주신|주는|받|나온|나왔|들어온|지급)'
                          r'|(?<![가-힣])(?:준|주신|받은|받았던|나온|쌓인|모인|들어온)(?![가-힣])|쌓아\s*(?:준|둔)|넣어\s*(?:준|주신|주는)')


# 퇴직하면서 받은 돈 — '퇴직할 때 받은 600만 원', '퇴직하면서 회사에서 받은 600만 원'. 퇴직금 이름이 없어도 퇴직금 쪽 돈일 수 있다
_RETIRE_GOT = re.compile(r'퇴직\s*(?:할\s*때|하면서|하며|해서|하고서?|한\s*(?:뒤|후)에?|시)\s*(?:회사\s*(?:에서|가|로부터)\s*)?'
                         r'(?P<v>받|나온|나왔|준|주신|지급)')
# 돈 이름(퇴직금) 뒤에서 금액을 다른 마디로 떼어 놓는 말 — 연결 어미('받아서·받고·두고·옮기고'), 쉼표, 시간 말('받은 뒤에'),
# 계좌를 꾸미는 말('퇴직금 받은 IRP에' — 퇴직금은 계좌를 꾸민다). 이 말 뒤의 금액은 퇴직금과 다른 동사에 걸린다
_REL_CUT = re.compile(_CONNECT + r'|(?<=[가-힣])(?<!제외)하고(?=[\s,])|,|(?:뒤|후|다음)(?:에|에는)?(?=[\s,])'
                      r'|(?:받은|받았던|들어간|들어온|들어\s*있는|있는|옮긴|넣은|넣어\s*둔|이체한|쌓인)\s*'
                      r'(?:IRP|개인형|연금\s*저축|연금\s*계좌|계좌|DC|퇴직\s*연금)', re.I)
# 이미 받은 돈으로 넣는 말 — '퇴직금 받은 걸로·받은 돈으로'. 통장에 받은 돈을 본인이 넣는지(본인 납입) 퇴직금을 옮기는지 모른다
_REL_RECV = re.compile(r'\s*(?:을|를|은|는|이|가|으로|로)?\s*(?:받은|받았던|받던|수령\s*(?:받은|한|했던)|나온|들어온|준|주신|지급\s*(?:받은|된)|탄)'
                       r'\s*(?:걸|거|것|돈|금액)')
# 퇴직금이 넣는 돈 그 자체라는 꼴 — 돈 이름 바로 뒤 금액('퇴직금 300만 원'), 목적어·수단·덜어 냄('퇴직금을·으로·일부를·중에서·
# 3천만 원 중에') 뒤에 넣는 사람·부사·넣는 곳('제가 직접 IRP에')만 오거나, 금액을 바로 꾸밈('퇴직금으로 받은 600만 원').
# 이 꼴이 아니면 퇴직금은 다른 얘기('퇴직금 세금이 궁금한데')일 수 있어 단정하지 않는다.
# 퇴직금을 나눈 나머지('퇴직금 중 생활비 쓸 거 말고', '퇴직금에서 대출 갚을 돈 말고 나머지')도 퇴직금을 넣는 말이다(6차 502).
# '중·가운데'(나눔)나 '나머지·남은'이 있을 때만 — '퇴직금에서 세금 뗀 거 말고'의 '뗀 거'는 세금을 뗀 퇴직금 전체일 수도 있어 모른다
_REL_SUB_NP = (r'\s+(?!' + _TAKE_V + r')(?:[가-힣]+\s+){1,4}?(?:거|것|걸|건|돈|금액|부분|분|몫)\s*(?:은|는|을|를)?\s*'
               r'(?:빼고|제외하고|말고|외에|이외에)\s*')
_REL_REMAIN = r'(?:나머지|남은\s*(?:돈|거|것|금액)?)\s*'
_REL_SUB = (_SUB_AMT + r'(?:(?:중에서|중에|중|가운데)' + _REL_SUB_NP + r'(?:' + _REL_REMAIN + r')?'
            r'|에서' + _REL_SUB_NP + _REL_REMAIN + r')')
_REL_ORIGIN = re.compile(
    r'\s*(?:의\s*)?(?:' + _REL_SUB + r'|[\d,.]+\s*(?:억|천만|천|백만|만)?\s*원?\s*(?:중|중에|중에서|가운데)\s*)?'
    r'(?:(?:일부|전부|전액|절반|반|나머지|중|중에|중에서|가운데)\s*)?(?:을|를|으로|로|에서|은|는|이|가|만|도|중)?\s*'
    r'(?:(?:제가|내가|본인이|본인도|본인은|저도|저는|나는|직접|바로|다|전부|모두|그대로|이번에|올해|일단|우선|약|대략|한'
    r'|(?:개인형\s*)?IRP(?:\s*계좌)?|연금\s*저축(?:\s*계좌)?|연금\s*계좌|계좌|DC(?:형)?|퇴직\s*연금)'
    r'\s*(?:에|에다|에다가|으로|로|에는)?\s*)*'
    r'(?:(?:받은|받았던|준|주신|나온|들어온|지급\s*(?:받은|된)|들어간|넣을|넣은)\s*)?$', re.I)


def _money_rel(b):
    """돈 이름(퇴직금·퇴직급여·'퇴직할 때 받은') 끝에서 금액 앞까지의 말(b)로 그 금액이 퇴직금인가 → 'origin' / 'unsure' / None(본인 돈).
    '퇴직금 300만 원'·'퇴직금을·으로·일부를·중에서 (제가) IRP에 300만 원'은 퇴직금을 넣는 말이다 — 넣는 사람(제가)은 상관없다.
    '퇴직금 받은 걸로·받아서·받고 (제가) 300만 원'은 통장에 받은 돈을 넣는 것일 수도 있어 모른다(숫자 없이 되묻기).
    다른 마디를 연 뒤 본인 돈 말이 오면('퇴직금은 그대로 두고 제 돈 300만 원', '퇴직금 받은 IRP에 내 돈') 본인 돈이다."""
    if _SRC_APART.match(b):
        return 'unsure'                 # '퇴직금 따로 300만 원' — 퇴직금과 따로인 돈인지 퇴직금 300만 원을 따로 넣는 것인지 모른다
    own = _OWN_MONEY.search(b)
    cut = _REL_CUT.search(b)
    if own:
        # 마디가 끊기지 않고 본인 돈 말이 붙으면('퇴직금으로 받은 제 돈') 그 돈이 퇴직금일 수 있다
        return None if cut and cut.start() < own.start() else 'unsure'
    if cut or _REL_RECV.match(b) or not _REL_ORIGIN.match(b):
        return 'unsure'
    return 'origin'


def _retire_origin(q, x):
    """납입으로 읽힌 금액이 퇴직금 쪽(퇴직금·퇴직급여·DC·퇴직연금)에서 온 돈인가 → 'origin'(그렇다) / 'unsure'(모름) /
    'db'(DB 에 넣는 돈 — 문서에 세액공제 규칙 없음) / None(아니다).
    퇴직금 쪽 돈이면 누가 줬든 세액공제 납입이 아니다 — 문서(doc38)는 연금계좌의 돈을 세액공제 안 받은 돈·퇴직금·세액공제 받은 돈으로
    나눈다(10-14 3차 검토 200: '회사가 퇴직급여로 준 600만 원 IRP에 넣으면'을 본인 납입으로 읽어 99만 원). 금액 바로 앞 출처 말이 퇴직금
    쪽일 때 — 돈 이름(퇴직금·퇴직급여)은 늘 온 곳이다. 계좌 이름(DC·퇴직연금)은 'DC에서·DC로 준·DC에 쌓인'이나 금액 뒤에 다른 계좌가
    오면 온 곳, 'DC에 제가 넣으면'·'DC에 본인 부담으로'처럼 그 계좌에 본인이 넣는 말이면 넣는 곳(가입자부담금 — doc55 세액공제 대상)이다.
    '퇴직금 말고'·'퇴직금 받은 거 말고'처럼 부정된 말은 출처가 아니다. 어느 쪽인지 모르면 'unsure' — 숫자를 내지 않되 '퇴직금 쪽에서 온 돈'이라고 단정하지
    않는다(10-14 4차 검토 300: 모를 때도 온 곳으로 보아 'DC에 본인 부담으로 넣는 300만 원'을 퇴직금 쪽 돈이라고 블록에 적었다).
    돈 이름은 금액 앞 출처 말이 계좌(IRP)여도 본다 — '퇴직금을 제가 IRP에 300만 원'의 출처 말은 IRP지만 넣는 돈은 퇴직금이다(5차 400)."""
    pre = re.split(r'[.?!\n]', q[max(0, x['s'] - 24):x['s']])[-1]
    # 덜어 냄('퇴직금 중에서 주택 대출 갚을 돈 말고 나머지')·이중 부정('퇴직금 받은 것 외에는 따로 모아 둔 돈이 없어서')은 출처 말과
    # 금액을 명사구로 잇는 꼴이라 24자를 넘어도 한 마디다 — 이 꼴로 이어진 퇴직금 말만 더 앞(48자)에서 찾는다(6차 502·503의 긴 꼴:
    # 퇴직금이 24자 밖이라 본인 돈 49만 5천 원)
    far = re.split(r'[.?!\n]', q[max(0, x['s'] - 48):x['s']])[-1]
    ext = [w for w in _RETIRE_WORD.finditer(far) if w.start() < len(far) - len(pre) and _neg_kind(far, w.end()) in ('sub', 'only')]
    if ext:
        pre = far[ext[0].start():]
    # '퇴직금(퇴직연금) 안 받고'는 부정으로 지우지 않고 돈 이름처럼 _money_rel 에 넘긴다 — 받지 않은 퇴직금을 옮기는 말일 수 있다(6차 501)
    words = [w for w in _RETIRE_WORD.finditer(pre) if not _negated(pre, w.end()) or _NOT_TAKEN.match(pre, w.end())]
    money = [(w.end(), pre[w.end():]) for w in words if w.group(1) or _NOT_TAKEN.match(pre, w.end())] + \
        [(g.end(), pre[g.start('v'):]) for g in _RETIRE_GOT.finditer(pre) if not _negated(pre, g.end())]
    rel = _money_rel(max(money)[1]) if money else 'none'     # 금액에 가장 가까운 돈 이름
    # 계좌 이름(DC·퇴직연금)은 금액 앞 출처 말이 그 계좌이고 돈 이름보다 금액에 가까울 때만 본다
    acct = _retire_acct(q, x, pre, words[-1]) if x['src'] == 'retire' and words and words[-1].group(2) and \
        (not money or words[-1].end() > max(money)[0]) else None
    if acct == 'origin':
        return 'origin'                 # '퇴직금은 두고 DC에서 받은 300만 원' — 계좌에서 나온 돈
    return acct if rel == 'none' else rel


def _retire_acct(q, x, pre, w):
    """계좌 이름(DC·DB·퇴직연금) w 와 금액 사이의 말로 그 계좌가 돈이 나온 곳인지 넣는 곳인지 → 'origin' / 'unsure' / 'db' / None."""
    between = pre[w.end():]
    po = list(_PAYER_OTHER.finditer(between))
    own_after = bool(po) and bool(_OWN_PAY.search(between[po[-1].end():]))
    firm = bool(po) and not own_after and bool(re.match(r'회사|사측|사업주|고용주', po[-1].group(0)))
    cut = [m.end() for m in re.finditer(_CONNECT, between) if m.start() >= po[-1].end()] if firm else []
    if cut:
        # 'DC에 회사가 넣어주고 IRP는 있는데 300만 원', 'DC에 회사가 넣어준 돈이 있는데 300만 원 더 넣으면' — 회사 말 뒤 연결 어미로
        # 마디가 닫히면 그 마디(회사가 DC에 넣는 돈)의 말('넣어준'·'회사에서')은 이 금액이 나온 곳이 아니다(_payer_other 도 같은
        # 자리에서 마디를 끊는다). 8차 706 이웃: 앞 마디의 '넣어주는'·'에서'를 이 금액의 출처로 읽어 '퇴직금 쪽에서 온 돈'이라고 적었다.
        # 닫힌 뒤 마디에 다른 계좌의 있다·없다 말이 오면 DC 는 이 금액과 관계없고(넣는 계좌는 _dest_parts 가 가른다), 금액에 '더'가
        # 붙으면 회사 몫에 본인이 더 넣는 돈이다. 둘 다 아니면('DC에 회사가 넣어주는데 300만 원 IRP에 넣으면') 확신이 없어 모름
        rest = between[cut[0]:]
        if _RETIRE_FROM.search(rest):
            return 'origin'
        other = any(_ACCT_EXIST.match(rest, m.end()) for m in re.finditer(r'개인형\s*IRP|IRP|개인형|연금저축', rest, re.I))
        more = re.match(r'\s*(?:을|를|씩)?\s*' + _PERIOD_MID + _ACCT_MID + _ADV + r'(?:더|추가)', q[x['e']:x['e'] + 30]) or \
            re.search(r'(?:더|추가로?)\s*$', rest)
        return None if other or more else 'unsure'
    if _RETIRE_FROM.search(between) or _ACCT_AFTER.match(q[x['e']:x['e'] + 26]):
        return 'origin'                 # 'DC로 준 600만 원 IRP에 넣으면' — 넣는 곳은 금액 뒤 계좌다
    if po and not own_after:
        # 'DC에 회사가 300만 원 넣어 주면' — 회사가 DC에 넣는 돈은 퇴직급여다. 가족이 넣는 돈은 본인 납입이 아니라 아래 납입자 검사가 뺀다
        return 'origin' if re.match(r'회사|사측|사업주|고용주', po[-1].group(0)) else None
    if re.match(r'DB|확정\s*급여', w.group(2), re.I):
        return 'db'                     # DB 에 본인이 넣는 돈(가입자부담금)은 받은 문서에 없다 — 세액공제 납입으로 정하지 않는다
    if _RETIRE_DEST.match(between) or \
            (re.match(r'\)?(?:형)?\)?(?:\s*계좌)?\s*(?:에|에다|에다가|으로|로)(?![가-힣])', between) and _OWN_PAY.search(between)):
        return None                     # 'DC에 제가·본인 부담으로 300만 원 넣으면' — 본인이 넣는 가입자부담금
    return 'unsure'


_THRESHOLD_POST = re.compile(r'\s*(?:이하|이상|초과|미만|넘|기준|까지|한도|을\s*넘|를\s*넘)')
_LUMP_CTX = re.compile(r'지금까지|그동안|누적|모은|모았|쌓인|쌓였|평가|총\s*\d|전부|목돈')     # '퇴직금'은 _retire_origin 이 부정·본인 돈 말과 함께 본다


# 재원 이름 바로 뒤(조사·'약'까지)에 오는 금액이 그 재원의 금액이다. 끝($)에 붙여 쓴다.
_FUND_TAIL = r'(?:\s*(?:재원|부분|분))?\s*(?:이|가|은|는|이요|만|도)?\s*(?:약|대략|한)?\s*$'
# 재원 이름 — '공제 안 받고 넣은 게 3천'처럼 넣는 말로 꾸민 꼴도 같은 재원이다(stab 2238: 이 꼴을 못 읽어 공제 안 받은 3천을
# 버리고 2,000만 원 인출에 330만 원을 냈다 — 맞는 값은 먼저 빠지는 비과세 원금이라 0원, doc39)
_FREE_NAME = (r'(?:(?:(?:세액\s*)?공제\s*(?:를\s*)?(?:안|못)\s*받은|공제\s*받지\s*않은)\s*(?:돈|납입금|납입액|원금|금액)?'
              r'|(?:세액\s*)?공제\s*(?:를\s*)?(?:안|못)\s*받고\s*(?:넣은|부은|납입한|모은)\s*(?:게|거|것|돈|금액)'
              r'|비과세\s*(?:원금|재원|납입금)|과세\s*제외\s*(?:금액)?)')
_CREDIT_NAME = (r'(?:(?:세액\s*)?공제\s*(?:를\s*)?받은\s*(?:돈|납입금|납입액|원금|금액)'
                r'(?:\s*(?:과|와|이랑|하고|및|·|,)\s*(?:운용\s*)?수익(?:금)?)?'
                r'|(?:세액\s*)?공제\s*(?:를\s*)?받고\s*(?:넣은|부은|납입한|모은)\s*(?:게|거|것|돈|금액)'
                r'|(?<![가-힣])(?:운용\s*)?수익(?:금)?)')
_FUND_PRE = [
    ('free', re.compile(_FREE_NAME + _FUND_TAIL)),
    ('credit', re.compile(_CREDIT_NAME + _FUND_TAIL)),
    ('retire', re.compile(r'(?:퇴직금|퇴직\s*급여|이연\s*퇴직\s*소득)' + _FUND_TAIL)),
]
# 금액 뒤에서 그 돈의 재원을 밝히는 꼴 — '그중 1,500만 원은 연말정산 때 공제받은 거고 나머지 900은 공제 안 받은 돈이에요'.
# 이름이 금액 앞에 올 때만 읽어(_FUND_PRE) 1,500은 쓰임 없음, 900은 못 읽고 2,400만 원 전부를 ③으로 보아 396만 원을 냈다
# (stab 2222 — 맞는 값은 ① 900만 원 비과세 + ③ 1,500만 원 × 16.5% = 247만 5천 원, doc39 인출 순서). 지난 일로 밝힌 꼴만 —
# '600만 원은 세액공제 받을 수 있나요'는 아니다
_FUND_POST = re.compile(r'\s*(?:은|는|이|가)\s*(?:(?:연말\s*정산\s*(?:때|에|에서)?|작년에|그동안|이미|다|모두|전부)\s*){0,2}'
                        r'(?:세액\s*)?공제\s*(?:를|는|도)?\s*(?P<neg>(?:안|못)\s*)?'
                        r'(?:받(?:은|았던|던)\s*(?:거|것|게|돈|금액|납입금|납입액|원금|분|몫|부분)'
                        r'|받았(?:고|어요|어|습니다|으며|는데|지만)|받지\s*(?P<neg2>않|못)(?:은|았))')
# '퇴직소득세가 원래 800만 원', '퇴직소득세가 대충 600만 원' — 이름과 금액 사이의 부사도 받는다(stab 2243·2251·2257: 퇴직소득세를
# 못 읽고 되묻거나 수령액으로 읽었다)
_RTAX_PRE = re.compile(r'퇴직\s*소득\s*세(?:액)?\s*(?:는|은|이|가)?\s*(?:(?:원래|대충|대략|약|총)\s*)?$')
_EFF = re.compile(r'(?:퇴직\s*소득\s*세\s*)?실효\s*세율\s*(?:은|는|이|가)?\s*(?:약\s*)?(\d+(?:\.\d+)?)\s*%'
                  r'|퇴직\s*소득\s*세율\s*(?:은|는|이|가)?\s*(?:약\s*)?(\d+(?:\.\d+)?)\s*%')
_ACTUAL = re.compile(r'실제\s*(?:연금\s*)?수령\s*(?:연차\s*)?(?:가|는|이)?\s*(\d{1,2})\s*년\s*차?|연금\s*(?:을\s*)?받은\s*지\s*(\d{1,2})\s*년')
# '연금저축 600, IRP 300 넣으면' — 계좌 이름 바로 뒤 단위 없는 숫자(만 원). 납입·공제 질문에서만 읽는다.
_BARE_ACCT = re.compile(r'(?:연금저축(?:펀드|계좌)?|IRP|개인형\s*IRP)\s*(?:에|에만|에는|은|는|만|로|으로)?\s*'
                        r'(\d{2,4})(?!\d|[.,]\d)(?!\s*(?:만|원|%|세|살|년|개|억|천|백|대|호|좌|주|배|건|명|회|차|월|일|시|분))',
                        re.I)
# 퇴직연금 제도(DC·DB)의 돈을 IRP·연금계좌로 옮긴다는 말 — 옮기지 않는다는 말('옮기지 않고·받지 말고')은 아니다
_PLAN_MOVED = re.compile(r'(?:(?<![A-Za-z])D[CB](?![A-Za-z])|퇴직\s*연금|확정\s*(?:기여|급여))[^.?!\n]{0,30}?'
                         r'(?:IRP|개인형|연금\s*저축|연금\s*계좌)\s*(?:으로|로)\s*(?:옮[기겨긴겼길]|이전|이체|받|넘[기겨긴겼어]|들어)'
                         r'(?!(?:하|해)?\s*지\s*(?:않|말|못|마)|(?:하)?기\s*전)', re.I)
# 금액 바로 뒤 IRP·연금계좌로 옮기는 말 — '퇴직연금 2천을 IRP로 옮겨서'
_MOVED_POST = re.compile(r'\s*(?:을|를|이|가|은|는)?\s*(?:(?:모두|전부|다|바로)\s*)?(?:IRP|개인형(?:\s*IRP)?|연금\s*저축|연금\s*계좌)\s*'
                         r'(?:으로|로)\s*(?:옮[기겨긴겼길]|이전|이체|받|넘[기겨긴겼어]|들어)'
                         r'(?!(?:하|해)?\s*지\s*(?:않|말|못|마)|(?:하)?기\s*전)', re.I)
_MENTION = [('retire', r'퇴직금|퇴직\s*급여|이연\s*퇴직'),
            ('credit', r'(?:세액\s*)?공제\s*(?:를\s*)?받은|공제분|세액공제\s*받았'),
            ('free', r'공제\s*(?:를\s*)?(?:안|못)\s*받|공제\s*받지\s*않|비과세\s*원금|과세\s*제외')]


def _income_kind(word):
    if re.search(r'종합소득|사업소득', word):
        return '종합소득'
    if re.search(r'총\s*급여|연봉|급여|근로소득', word):
        return '총급여'
    return None                     # '소득'만으로는 총급여(5,500만)인지 종합소득금액(4,500만)인지 모른다


# 금액과 동사 사이에 끼는 부사 — 'IRP에 300만원 이미 넣었어요'를 납입으로 못 읽었다.
# '그 600 다시 빼야', '2천 그냥 빼면'도 같다 — 못 읽어 인출 질문을 앞의 '공제받았는데'로 세액공제 블록에 보냈다(stab 2229)
_ADV = r'(?:(?:이미|벌써|미리|다시|도로|바로|당장|그냥|급하게|급히|일단|좀|다|모두|전부|꽉|각각|같이|함께|동시에|둘\s*다)\s*){0,2}'
# 나열한 계좌 가운데 하나를 고르는 말 — '… 중에 어느 걸', '둘 중 뭘', '하나만 해지하려면', '어느 쪽 세금이'
_PICK_ONE = re.compile(r'(?<![가-힣])중(?:에서|에)?(?![가-힣])|가운데|어느|어디|어떤\s*(?:게|걸|것|쪽|계좌)|하나만|한\s*쪽만'
                       r'|(?<![가-힣])뭘|(?<![가-힣])뭐(?:가|를|부터)?(?![가-힣])|먼저')
# 금액과 납입 동사 사이의 계좌 이름 — '50,000원씩 연금저축에 넣으면'
_ACCT_MID = (r'(?:(?:연금\s*저축(?:\s*계좌|\s*펀드)?|개인형\s*IRP|IRP(?:\s*계좌)?|개인형|퇴직\s*연금|DC|연금\s*계좌)'
             r'\s*(?:에|에다|에다가|으로|로)?\s*(?:도|만|는)?\s*)?')
_DED_ASK = re.compile(r'세액\s*공제|공제|돌려\s*받|환급|연말\s*정산'
                      # 납입 조합 비교('연금저축 600 + IRP 300 vs 연금저축 900 비교해줘')도 세액공제를 묻는 말이다
                      r'|비교|(?<![A-Za-z])vs(?![A-Za-z])|어느\s*쪽|뭐가\s*(?:더|나)|어떤\s*게\s*(?:더|나)|차이|유리|나을', re.I)
_ACCT_LIST_PRE = re.compile(r'(?:연금저축|IRP|개인형)\s*(?:계좌)?\s*(?:에|에는|에다)?\s*(?:(?:단독|만|만으로|에만)\s*)?(?:(?:월|매월|매달|연간|연|1년에|올해|한\s*달에?)\s*)?'
                            r'(?:납입(?:액|금)?\s*)?(?:은|는|이|가|으로|로)?\s*(?:약|대략)?\s*$', re.I)
# '깨면·깨서'(해지)만 — '원금 200만 원 깨졌어요'·'깨진'은 손실을 말한다(10-14 검토: 손실액을 인출액으로 읽어 해지 세금이
# 평가액 1,000만 원 기준 165만 원에서 33만 원으로 줄었다). '깨지 않고'는 해지 말이다
_BREAK = r'깨(?![끗졌져질진짐]|지(?!\s*않))'
# '해지' — '정해지는·불리해지면·편해지고'(형용사 + 지다)의 '해지'는 계좌 해지가 아니다. 9차 검토 900 이웃: 'DC와 DB, 퇴직금이 정해지는
# 방식'을 해지 질문으로 읽었다(55세 전·해지 판정 p['early'] 도 같은 글자를 본다)
_HAEJI = r'(?<![정리편끗뜻잡심강친숙능렴족요])해지'
# 계좌를 닫는 말 — 해지·해약·깨·빼·꺼내·인출·옮기·이전·갈아타·정리·없애. 이 말이 붙은 앞 계좌는 새 돈을 넣는 곳이 아니다
# (_clause_kind, 10차 검토 1000·1001). '빼고'는 덜어 내는 말('회사 돈 빼고')이라 '빼고 싶'만, '이전에'(때)·'정리해 보면'은 아니다
_CL_SHUT = re.compile(_HAEJI + r'|해약|' + _BREAK + r'|(?<![가-힣])(?:깰|깼|빼(?!고(?!\s*싶))|뺄|뺐|꺼내|꺼낼|꺼냈)|인출'
                      r'|옮기|옮겨|옮길|옮긴|옮겼|이전\s*(?:하|해|할|한|했|시키)|갈아\s*(?:타|탈|탄|탔)'
                      r'|정리\s*(?:하|해|할|한|했)(?!\s*보)|없애|없앨|없앴')
# 옮기는 말 — '연금저축으로 옮기려고'의 연금저축은 돈이 옮겨 가는 곳이라 닫힌 계좌가 아니다(새 돈을 넣는 곳인지는 모름)
_CL_MOVE = re.compile(r'옮|이전|갈아')
# 닫는 말의 부정 — '해지하지 않고·깨지 말고·옮기지는 못하고·해지는 안 하고'(뒤), '안 깨고·못 옮기고'(앞)
_CL_SHUT_NEG_AFTER = re.compile(r'[가-힣]{0,2}?\s*지\s*(?:는|도|만)?\s*(?:않|말|마|못)'
                                r'|\s*(?:은|는|도|까지)?\s*(?:안|못)\s*(?:하|해|할|함|했|시키)')
_CL_SHUT_NEG_BEFORE = re.compile(r'(?<![가-힣])(?:안|못)\s*$')
# '중도인출하면'·'중도 해지하면' — 인출 동사 앞의 '중도'(C10 대화: 금액이 있는데 '인출하려는 금액'을 되물었다)
_OUT_VERB = r'(?:중도\s*)?(?:빼|인출|찾|꺼내|출금|해지|' + _BREAK + r')'
# 금액 뒤의 기간 말 — '50만 원씩 매월 넣으면', '30만 원씩 12개월'. 앞말만 보면 월 납입을 연 납입으로 읽는다
# (10-14 검토: 'IRP에 50만 원씩 매월 넣으면'을 연 50만 원으로 읽어 8만 2,500원 — 맞는 값 99만 원)
_PERIOD_MID = (r'(?:(?:매월|매달|월마다|달마다|한\s*달에?|매년|해마다|1년에|연간|(?:1년|한\s*해|\d{1,2}\s*개월)(?:\s*(?:동안|간))?)'
               r'\s*)?')
# 'N개월'·'1년 동안'은 '씩'(회차마다 같은 금액) 뒤일 때만 기간이다 — '300만 원 3개월 전에', '360만 원을 12개월 동안 나눠'는 아니다
_POST_PERIOD = re.compile(r'\s*(?:을|를)?\s*(씩)?\s*(?:(매월|매달|월마다|달마다|한\s*달에?)|(매년|해마다|1년에|연간)'
                          r'|(\d{1,2})\s*개월|(?:1년|한\s*해)\s*(?:동안|간))')
# 금액 바로 뒤의 계좌 이름 — '300만 원 IRP에', '50만 원씩 1년 동안 IRP에'(기간 말이 끼어도 그 계좌)
_ACCT_AFTER = re.compile(r'\s*(?:을|를|씩|정도|쯤|으로|로)?\s*(?:씩)?\s*' + _PERIOD_MID
                         + r'(연금\s*저축|개인형|IRP|퇴직\s*연금|DC|연금\s*계좌)', re.I)
# 질문의 '세액공제'가 재원을 설명하는 말('세액공제 받은 돈이에요')이면 공제를 묻는 말이 아니다
_FUND_DESC = re.compile(r'(?:세액\s*)?공제\s*(?:를\s*)?(?:안\s*|못\s*)?받(?:은|았던|지\s*않은)\s*(?:돈|납입금|납입액|원금|금액|분|재원)?'
                        r'|공제분')
_IN_VERB = r'넣|납입|입금|불입|채우|채워|채운|채웠|붓|부어|부으|부었'
# 공제 말을 꾸미는 '받' — '받을 수 있는 세액공제', '받는 공제액', '받게 되는 최대 환급'. 이 '받'은 공제를 받는 말이다
_DED_WORD = r'(?:세액\s*)?공제|환급|돌려\s*받|연말\s*정산|혜택'
# '받…'과 공제 말 사이의 꾸밈 낱말 — '받을 수 있는 세금 환급', '받을 수 있는 소득공제', '받게 되는 최대 공제'.
# 10-14 3차 검토 203: 사이 낱말을 '최대·총·예상·연간·올해'로만 열거해 '세금 환급'·'소득공제'를 금액 수령으로 읽고 되물었다.
# 낱말을 늘어놓지 않고 꼴로 본다 — 조사·어미가 붙지 않은 낱말 두 개까지. 다만 받는 돈·때를 가리키는 낱말(돈·금액·연금·경우·때·해…)이
# 오면 그 '받'은 금액을 받는 말이다('1,000만 원 받는 경우 연말정산') — 공제 말로 이어지지 않으면 숫자를 내지 않는다(되묻기)
_NOT_DED_NOUN = (r'(?:때|경우|거|것|게|건|걸|수|중|데|동안|후|뒤|전|만큼|해|달|날|분|돈|금액|수령액|일시금)(?![가-힣])'
                 r'|[가-힣]*(?:연금|퇴직)')
_DED_GAP = (r'(?:(?!' + _NOT_DED_NOUN + r')[가-힣A-Za-z]+(?<![는은을던면고서며])(?=\s|$|' + _DED_WORD + r')\s*){0,2}')
_DED_RECV_V = r'받(?:을\s*수\s*있는|을|는|게\s*(?:되는|될))\s*'
_DED_RECV = _DED_RECV_V + _DED_GAP          # orchestrator 가 낯선 금액 뒤의 '공제를 받는' 말을 지울 때도 쓴다
# 사이 낱말을 아무 낱말이나 받는 것은 금액이 '받'의 목적어일 수 없을 때만이다 — '600만 원으로·기준·이면 받을 수 있는 ○○ 공제'.
# 금액 바로 뒤에 '받…'이 오면('연 1,000만 원 받는 분들 연말정산', '월 100만 원 받는 시니어 연말정산') 그 '받'은 금액을 받는 말일 수
# 있다(10-14 4차 검토 303: 3차에 사이 낱말을 꼴로만 보아 '분들·사람·시니어'를 공제 꾸밈으로 읽고 받는 1,000만 원을 납입으로 계산했다).
# 이때는 공제를 꾸미는 세금 낱말(세금·세액·소득·최대·예상 …)만 사이 낱말로 받고, 그 밖의 낱말이면 받는 금액으로 둔다(숫자 없음)
_DED_LINK = (r'\s*(?:으로|로|기준(?:으로)?|이면|면|이라면|라면|(?:정도|쯤)(?:이면|면)?)\s*'
             r'(?:(?:최대(?:로|한)?|최고|모두|다|전부)\s*)?')
_DED_GAP_TAX = (r'(?:(?:최대(?:로|한)?|최고|총|예상(?:되는)?|연간|올해|한\s*해|추가|세금|세액|세제|소득|절세)'
                r'(?=\s|$|' + _DED_WORD + r')\s*){0,2}')
_DED_RECV_LINKED = re.compile(_DED_LINK + _DED_RECV_V + _DED_GAP + r'$')
_DED_RECV_TAIL = re.compile(_DED_RECV_V + _DED_GAP_TAX + r'$')
# 금액 바로 뒤가 그 꼴이면('IRP 900만 원 받을 수 있는 세액공제') 받기·수령 말로 보지 않는다
_DED_RECV_NEXT = re.compile(r'(?:' + _DED_LINK + _DED_RECV_V + _DED_GAP + r'|\s*(?:을|를)?\s*' + _DED_RECV_V + _DED_GAP_TAX
                            + r')(?:' + _DED_WORD + r')')
# 금액 바로 뒤 '받는'이 꾸미는 낱말 없이 공제 말에 붙은 꼴 — '1,000만 원 받는 연말정산·받는 세액공제·받는 소득 공제'
# ('소득 공제'·'세금 환급'은 한 낱말이다). 금액이 '받는'의 목적어(받는 연금)일 수도, 공제를 받는 납입액일 수도 있다 — parse 가
# 소득·나이로 가른다(10-14 5차 검토 409: 4차는 이 꼴을 공제 꾸밈으로 보아 '연 1,000만 원 받는 연말정산? 65세'를 납입 99만 원으로 계산)
_DED_RECV_BARE = re.compile(r'\s*(?:을|를)?\s*받는\s*(?:(?:소득|세금|세액)\s*)?$')


def _role(q, s, e, no_isa=False):
    """금액의 쓰임을 앞뒤 말로 가른다 → (role, period, kind). no_isa=True 면 ISA 전환액으로 보지 않는다."""
    pre = q[max(0, s - 14):s]
    post = q[e:e + 14]
    period = 'monthly' if _MONTHLY.search(pre) else 'yearly' if _YEARLY.search(pre) else None
    if period is None:
        # '매달 연금저축에 5만 원' — 기간 말과 금액 사이에 계좌 이름이 낀 어순(같은 뜻 다른 표현 시험: 연 5만 원으로 읽어 8,250원)
        far = q[max(0, s - 24):s]
        if re.search(r'(?:매달|매월|(?<![\d개])월|한\s*달에?|달마다)\s*(?:연금저축|IRP|개인형)(?:\s*계좌)?\s*(?:에|에다|으로|로)?\s*$', far, re.I):
            period = 'monthly'
        elif re.search(r'(?:1년에?|연간|매년|해마다|올해)\s*(?:연금저축|IRP|개인형)(?:\s*계좌)?\s*(?:에|에서|에다|으로|로)?\s*$', far, re.I):
            period = 'yearly'
    pp = _POST_PERIOD.match(q, e)
    post_period = None
    if pp and not (pp.group(2) or pp.group(3)):
        # 'N개월'·'1년 동안' — 회차 수만 있고 한 번에 얼마인지(달마다인지)는 '씩' + 12개월일 때만 분명하다
        if pp.group(1):
            if pp.group(4) and int(pp.group(4)) == 12:
                post_period = 'monthly'     # '30만 원씩 12개월' = 매달 30만 원
            elif pp.group(4) or period is None:
                # '(월) 30만 원씩 6개월'(한 해 금액이 ×12가 아니다), '50만 원씩 1년 동안'(달마다인지 모름) —
                # 한 해 금액을 확신할 수 없다. 틀린 숫자보다 되묻기('월 50만 원씩 1년 동안'은 앞말 기간 그대로)
                return None, None, None
    elif pp:
        post_period = 'monthly' if pp.group(2) else 'yearly'
    if period is None:
        period = post_period                # 앞말이 있으면 앞말 — '월 50만 원씩 1년 동안'의 1년은 기간의 길이다
    m = _INCOME_PRE.search(pre)
    if m and '연금' not in pre[-6:]:
        # '총급여 5,500만 원 이하면'·'5,500만 원 기준'은 기준 인용이지만 '총급여 5,000만 원 기준으로요'는 고객 소득이다(같은 뜻 다른 표현 시험)
        th = _THRESHOLD_POST.match(post)
        if th and re.match(r'\s*기준', post) and not re.search(r'5,?500|4,?500|5천\s*5백|4천\s*5백', q[s:e]):
            th = None
        if th or _OTHER_PERSON.search(q[max(0, s - 16):s]):
            return 'skip', None, None   # '총급여 5,500만 원 이하면'은 기준 인용, '남편 연봉'은 남의 소득
        return 'income', None, _income_kind(m.group(1))
    m = re.match(r'\s*(?:정도|쯤)?\s*(?:의|인)?\s*(연봉|총\s*급여|급여|종합소득(?:금액)?|사업소득)', post)
    if m:
        return 'income', None, _income_kind(m.group(1))
    # ISA 전환액 — 금액과 같은 문장 안에 ISA 가 있어야 한다('…900만원 채웠어요. ISA 만기 3천만원…'의 900은 아니다)
    sent_a = max(q.rfind(c, 0, s) for c in '.?!\n') + 1
    sent_b = min([i for i in (q.find(c, e) for c in '.?!\n') if i >= 0] or [len(q)])
    sent = q[sent_a:sent_b]
    around = q[max(sent_a, s - 25):min(sent_b, e + 45)]
    after_move = re.search(r'(?:옮기|옮겨|이체하|전환하)\w{0,2}(?:고|서|뒤|후|면서)\s', q[sent_a:s]) and \
        re.match(r'\s*(?:을|를|씩)?\s*(?:씩)?\s*' + _ADV + r'(?:더\s*)?(?:넣|납입|입금|불입)', post)
    if not no_isa and not after_move and re.search(r'ISA', sent, re.I) and \
            re.search(r'만기|해지|전환|옮|이체|넣|입금|납입', around):
        if re.match(r'\s*(?:의|이|가)?\s*(?:수익|이익|이자|한도|비과세|추가)', post) or \
                re.search(r'(?:매년|연간|매달|매월)\s*$', pre):
            return 'skip', None, None   # ISA 수익·비과세 한도·연간 납입은 전환액이 아니다
        return 'isa', None, None
    # 'IRP 1억 원(퇴직금 6,000만 …)' — 계좌 이름 바로 뒤 금액에 괄호로 구성이 붙으면 평가액이다
    if re.search(r'(?:IRP|연금저축|연금계좌|계좌)\s*(?:에|에는|은|는|이|가)?\s*$', pre, re.I) and re.match(r'\s*\(', post):
        return 'balance', None, None
    # 재원 구성 — '퇴직금 6,000만 원', '공제받은 돈과 수익 4,000만', '퇴직소득세 240만 원'
    wide = q[max(0, s - 26):s]
    if _RTAX_PRE.search(wide):
        return 'rtax', None, None
    # '퇴직연금 2천을 IRP로 옮겨서 깨면' — 퇴직연금 제도(DC·DB)에서 IRP·연금계좌로 옮긴 금액은 퇴직금 재원이다(_PLAN_MOVED 와 같은 뜻)
    if re.search(r'(?:(?<![A-Za-z])D[CB](?![A-Za-z])|퇴직\s*연금|확정\s*(?:기여|급여))(?:형)?\s*(?:에|에서|의|은|는|이|가|도)?\s*'
                 r'(?:(?:있던|쌓인|적립금|돈)\s*)?$', wide, re.I) and _MOVED_POST.match(q, e):
        mp = _MOVED_POST.match(q, e)
        # IRP 로 옮긴 퇴직금과 따로 연금저축을 해지·인출하는 질문이면, 이 퇴직금을 꺼내는 계좌의 재원으로 섞지 않는다 —
        # '회사 DC 4천을 IRP로 옮겼어요. 연금저축에서 500만 원만 빼면'을 'IRP 퇴직금 → 퇴직소득세 100%'로 냈다(stab 재검증 R1)
        if not (re.search(r'IRP|개인형', mp.group(0), re.I) and re.search(r'연금\s*저축', q[:s] + ' ' + q[mp.end():])):
            return 'fund', None, 'retire'
    # '퇴직금도 1,500만 원에 들어가나요'의 1,500은 기준 인용이지 퇴직금 금액이 아니다
    if not re.match(r'\s*(?:을|를|씩|만)?\s*(?:씩)?\s*' + _ADV + r'(?:받|수령|' + _OUT_VERB + r'|넣|납입|입금|불입)', post) and \
            not re.match(r'\s*(?:에|에도|에는)\s*(?:들어가|들어\s*가|포함|해당|합산)', post):
        for kind, rx in _FUND_PRE:
            if rx.search(wide):
                return 'fund', None, kind
    fp = _FUND_POST.match(q, e)
    if fp:
        return 'fund', None, 'free' if fp.group('neg') or fp.group('neg2') else 'credit'
    # 병원비·의료비·간병비는 계좌 돈이 아니다 — '병원비 영수증이 450만 원 있어요'를 '있어요'로 평가액으로 읽었다(stab 2225).
    # 요양 인출 한도 계산은 없어(부득이 블록은 숫자 없음) 쓰지 않는 금액으로 둔다
    # '영수증'만으로는 보지 않는다 — '원천징수영수증 기준으로 600 넣으면'은 납입액이다
    if re.search(r'(?:병원비|의료비|치료비|간병비|간병인|수술비|입원비|요양비|의료\s*실비)[^.?!\n\d]{0,6}?'
                 r'(?:이|가|은|는|로|으로)?\s*(?:약|대략|한)?\s*$', wide):
        return 'skip', None, None
    # 평가액 — 'IRP에 1억원 있고', 'IRP 평가금액 1억 원', 'IRP 1억 원 중에 퇴직금이 …'(같은 뜻 다른 표현 시험: 평가액을 못 읽어
    # '평가액 = 퇴직금'으로 가정하고 63만 3,600원을 냈다 — 맞는 값 57만 6천 원).
    # '중에' 뒤가 재원 이름(퇴직금·공제받은 돈·금액)일 때만 구성이다 — '연금저축 600만 원과 IRP 900만 원 중에 세액공제 더 받는 건'은
    # 두 납입안을 고르는 말이다(10-14 검토: 900만 원을 평가액으로 읽어 '남은 한도 300만 원 → 49만 5천 원 더'를 첫 줄에 넣었다)
    # '평가액이 연초에 9천6백만 원', '평가액 합쳐서 8천' — 이름과 금액 사이의 때·합계 말도 받는다(stab 2253·2257).
    # '퇴직금 6천이랑 제가 넣은 돈 1천 있어요'의 1천은 나열의 한 몫이지 계좌 전체가 아니다 — 있다 말이 나열 전체에 걸린다
    # (stab 2230·2257: 1천·3천을 평가액으로 읽어 연금수령한도를 120만·360만 원으로 적었다)
    # 재원 이름(퇴직금 …) 뒤 금액에 쉼표·'에'·'이고'·'있고'·'말고도'로 이어진 금액도 나열의 한 몫이다('IRP에 퇴직금 6천 있고 제 돈
    # 1천 있어요', '퇴직금 5천, 제가 넣은 돈 3천' — 1천·3천을 평가액으로 읽어 한도를 120만·360만 원으로 적었다). 재원 이름이 없으면
    # 쓰지 않는다('연봉 5천이고 IRP에 3천 있어요'의 3천은 평가액이다). 사이에 계좌 이름이 있으면 다른 계좌의 평가액이다
    # ('… 4천, 아내 연금저축에 2천5백 있어요')
    tail = re.search(r'(?:\d|천|백|만|억|원)\s*(?:,|\+|에|이고|그리고|및|(?:이|가)?\s*(?:들어\s*)?있(?:고|는데|으며|지만)|말고도?|외에도?)'
                     r'\s*([^.?!\n,\d]{0,24})$', q[sent_a:s])
    in_list = re.search(r'(?:\d|천|백|만|억|원)\s*(?:이랑|랑|와|과|하고|에다가?)\s+[^.?!\n,\d]{0,24}$', q[sent_a:s]) or \
        (tail and not re.search(r'IRP|개인형|연금\s*저축|연금\s*계좌|계좌', tail.group(1), re.I)
         and re.search(r'퇴직\s*(?:금|급여)|이연\s*퇴직|공제\s*(?:를\s*)?(?:안\s*|못\s*)?받은', q[sent_a:s]))
    if re.match(r'\s*(?:이|가|정도|쯤)?\s*(?:들어\s*있|들어있|있어|있고|있으며|있음|있는데|있습니다|모였|모았|쌓였)', post) and not in_list or \
            re.search(r'(?:평가\s*금액|평가액|잔액|잔고|적립금|계좌에)\s*(?:이|은|는|가)?\s*'
                      r'(?:(?:합쳐서|합치면|합계|모두|전부|총|연초에?|연말에?|현재|지금)\s*)?(?:약|대략)?\s*$', pre) or \
            (re.search(r'(?:IRP|연금저축|연금계좌|계좌)\s*(?:에|에는|은|는|이|가)?\s*$', pre, re.I)
             and re.match(r'\s*(?:중|중에|중에서)\s*(?:퇴직금|(?:세액\s*)?공제\s*(?:를\s*)?(?:안\s*|못\s*)?받(?:은|지|고(?!\s*싶))|\d)',
                          q[e:e + 20])) or \
            (period is None and re.search(r'IRP|연금|계좌', q, re.I)
             and re.match(r'\s*(?:중|중에|중에서)\s*[\d,.]+\s*(?:억|천만|천|백만|백|만)?\s*원?\s*(?:만|정도|쯤|은|는|을|를)?\s*(?:만\s*)?'
                          r'(?:필요|빼|꺼내|인출|찾|쓰|써|해지|깨)', q[e:e + 30])
             and not re.search(r'월급|급여|소득|연봉|생활비|용돈|보너스|성과급|ISA|예금|적금', q[max(sent_a, s - 14):s], re.I)):
        # 'IRP … 53세고 5천 중에 1천만 필요한데 다 해지하면' — 'X 중에 Y만 필요·빼면'의 X는 가진 돈 전체다. 계좌 이름이 앞에 없어도
        # 같다(stab 2227: 5천을 못 읽어 질문에 있는 해지 금액을 되물었다). '2,000만 원 중 1,500만 원까지는·330만 원 세금'은 아니다
        return 'balance', None, None
    if re.match(r'\s*(?:\([^)]{0,8}\))?\s*(?:을|를|만|정도|쯤)?\s*(?:(?:55\s*(?:세|살)\s*(?:전|이전)에?|중간에|지금|올해)\s*)?' + _ADV
                # '한꺼번에 다 빼면' — 부사가 '한꺼번에' 뒤에 와도 같은 말이다(stab: 만 없는 '5천 한꺼번에 다 빼면'을 읽게 되자 쓰임을 몰라 되물었다)
                + r'(?:(?:한\s*번에|한꺼번에|일시에|목돈으로)\s*' + _ADV + r')?' + _OUT_VERB, q[e:e + 30]) or \
            re.match(r'\s*(?:을|를)?\s*(?:IRP|연금저축|연금계좌|계좌)\s*(?:에서|에서는)\s*' + _ADV + _OUT_VERB, q[e:e + 24], re.I):
        return 'withdraw', None, None
    # '중도해지 2,000만 원이면', '해지 금액 2,000만 원' — 인출 말이 금액 앞에 온 꼴(같은 뜻 다른 표현 시험).
    # 해지하는 것이 연금계좌가 아니거나(주택청약·적금·ISA) 무엇인지 모르는데 그 돈을 계좌에 넣는 말이면 연금 인출이 아니다
    # (10-14 검토: '주택청약 해지 금액 500만 원으로 IRP 넣으면 세액공제?'를 IRP 해지로 읽어 82만 5천 원)
    mw = re.search(r'(?:중도\s*)?(?:해지|인출|출금)(?:\s*(?:금액|액))?\s*(?:은|는|이|가)?\s*$', pre)
    if mw and not re.match(r'\s*(?:을|를)?\s*(?:넣|납입)', post):
        lead = re.split(r'[.?!\n,]', q[max(sent_a, s - 30):s - len(mw.group(0))])[-1]
        objs = _CANCEL_OBJ.findall(lead)
        own = bool(objs) and bool(re.match(r'연금저축|IRP|개인형|연금\s*계좌|계좌', objs[-1], re.I))
        into = re.match(r'\s*(?:을|를|으로|로)?\s*(?:연금\s*저축|개인형\s*IRP|IRP|연금\s*계좌)\s*(?:계좌)?\s*(?:에|에다|으로|로)?\s*'
                        r'(?:도|만|는)?\s*' + _ADV + r'(?:더\s*)?(?:' + _IN_VERB + r')', q[e:e + 30], re.I)
        if not (objs and not own) and not (into and not own):
            return 'withdraw', None, None
    # '내'는 납입('매달 30만 원씩 내고 있어요')일 때만 — '330만 원 내는 거죠'는 세금을 내는 말이다.
    # 금액과 동사 사이에 계좌 이름이 끼는 어순('월 50,000원씩 연금저축에 넣으면', '300만 원 IRP에 넣으면')도 납입이다 —
    # 10-14 외부 검토: 납입액을 못 읽어 계산값 없는 블록이 나가고 모델이 '월 5만 원 × 12 = 600만 원 → 99만 원'으로 채웠다
    if re.match(r'\s*(?:을|를|씩|정도|쯤|으로|로)?\s*(?:씩)?\s*' + _PERIOD_MID + _ACCT_MID + _PERIOD_MID + _ADV
                + r'(?:더\s*)?(?:' + _IN_VERB + r'|저축|내(?:고|요|서|며|왔|온|는\s*중))', q[e:e + 36]):
        return 'contrib', period, None
    # 동사 없는 나열 — '연금저축 매월 5만 원, 총급여 …', 'IRP 납입 900만 원이면', 'IRP900만원 세액공제 얼마'.
    # 계좌 이름 바로 뒤 금액이고 질문이 세액공제를 물을 때만 납입으로 본다(뒤에 받기·빼기 말이 오면 그쪽)
    # 'ISA 만기 2,000만 원을 연금저축과 IRP에 700만 원씩 나눠'의 700은 ISA 돈을 나눈 것이라 납입이 아니다(NO_ISA_BLOCK)
    # 10-14 검토: 이 규칙이 아래 나열 동사 규칙보다 먼저라 '연금저축 연 1,000만 원이랑 IRP 연 800만 원 받으면 … 세액공제 받은 돈이에요'의
    # 1,000을 납입으로 읽었다(합산 1,800만 원 → 297만 원이 800만 원 → 44만 원으로). 그래서 (1) 재원 설명('세액공제 받은 돈')은
    # 공제를 묻는 말로 보지 않고, (2) 같은 문장에서 금액 뒤 공제를 묻는 말 앞까지 처음 나오는 쓰임 동사가 받기·빼기면('… 받으면',
    # '일시금으로 받으면', '다음 달에 인출하면') 이 규칙을 쓰지 않는다 — 쓰임이 분명하지 않으면 납입으로 짐작하지 않는다.
    # 'IRP 900만 원이면 세액공제 받고 나중에 연금으로 받으면'의 뒤 '받으면'은 공제 말 뒤라 이 금액의 쓰임이 아니다
    if _DED_ASK.search(_FUND_DESC.sub(' ', q)) and _ACCT_LIST_PRE.search(pre):
        rest = _FUND_DESC.sub(' ', re.split(r'[.?!\n]', q[e:e + 60])[0])
        parts = re.split(r'(?:세액\s*)?공제|환급|돌려\s*받|연말\s*정산|혜택', rest, maxsplit=1)
        # '600만 원으로 받을 수 있는 세액공제'·'400만 원 기준 받을 수 있는 공제액' — 공제 말을 꾸미는 '받을 수 있는·받는'은 공제를
        # 받는 말이지 이 금액을 연금으로 받는 말이 아니다(10-14 2차 검토: 99만 원이던 답이 공제율만 내고 금액 쓰임을 되물었다).
        # 금액이 '받'의 목적어일 수 있으면(금액 바로 뒤 '받는') 사이 낱말은 세금 낱말만 — '받는 분들 연말정산'은 받는 금액이다(4차 303)
        bare = False
        if len(parts) > 1:
            rest = '' if _DED_RECV_LINKED.match(parts[0]) else _DED_RECV_TAIL.sub('', parts[0])
            bare = bool(_DED_RECV_BARE.match(parts[0]))
        else:
            rest = parts[0]
        ahead_use = re.search(r'(' + _IN_VERB + r')|(받|수령|나오|나와|' + _OUT_VERB + r'|일시금)', rest)
        if not (re.match(r'\s*씩', post) and re.search(r'ISA', sent, re.I)) and not (ahead_use and ahead_use.group(2)) and \
                not (re.match(r'\s*(?:을|를|씩|정도|쯤|이|가)?\s*(?:씩)?\s*' + _PERIOD_MID + _ADV + r'(?:받|수령|나오|나와|'
                              + _OUT_VERB + r'|있|들어|모았|쌓)', post) and not _DED_RECV_NEXT.match(q, e)):
            return 'contrib', period, ('recv' if bare else None)    # 'recv' — parse 가 소득·나이로 납입인지 받는 돈인지 가른다
    # '연금저축에 600만원, IRP에 300만원 넣어서' · '연금저축에서 연 1,000만원, IRP에서 연 800만원 받으면'
    # — 나열 뒤에 동사가 온다. 나열을 끝내는 동사가 쓰임을 정한다.
    # '즉시연금 연 1,000만 원이랑 연금저축 연 600만 원 받으면' — 보험 연금 수령액도 나열에 든다(출처는 보험이라 payout 이
    # 연금계좌 세금으로 계산하지 않고 규칙 블록으로 보낸다). 보험에 넣는 돈은 연금계좌 납입이 아니라 납입으로 읽지 않는다
    ins_pre = bool(re.search(r'변액\s*연금|즉시\s*연금|연금\s*보험', pre))
    # 계좌 별칭('A에 300, B에 400 넣었고')도 나열 항목이다 — 계좌 이름만 보아 단위를 붙여도 'A에 300만 원'을 버렸다(stab 2211)
    if (re.search(r'연금저축|IRP|개인형', pre, re.I) or ins_pre or re.search(_ALIAS + r'$', pre)) and \
            not re.match(r'\s*(?:까지|한도|이\s*한도|을\s*넘)', post):
        ahead = re.split(r'[.?!\n]', q[e:e + 45])[0]
        if re.match(r'\s*(?:씩)?\s*(?:,|와|과|하고|이랑|랑|\+|그리고|(?=(?:IRP|연금저축|개인형)))', ahead, re.I):
            # '연금저축 3,500만 원이랑 IRP 1,800만 원 둘 다 해지하면' — 나열을 끝내는 동사가 해지·인출이면 앞 금액도 인출액이다
            # (stab 2226: 앞 금액의 쓰임을 몰라 해지한다고 밝힌 금액을 되물었다). '… 있는데 해지하면'처럼 사이에 있다 말이 있으면 평가액이라 아니다
            # 둘 가운데 하나를 고르는 질문('… 중에 어느 걸 빼는 게', '… 중 하나만 해지하려면')은 두 금액을 다 꺼내는 말이 아니다 —
            # 해지 동사를 보지 않는다(전처럼). 앞 금액을 인출액으로 세워 다른 계좌 이름으로 세금을 냈다(10-15 검토)
            pick = _PICK_ONE.search(re.split(r'[.?!\n]', q[e:])[0])
            verb = re.search(r'(넣|납입|입금|불입|채웠)|(받|수령|나오|나와|나올)' + ('' if pick else r'|(' + _HAEJI + r'|해약|'
                             + _BREAK + r'|빼(?!고)|인출|꺼내)'), ahead)
            if verb and verb.group(1) and not ins_pre:
                return 'contrib', period, None
            if verb and verb.group(2):
                return 'payout', period, None
            if not pick and verb and verb.group(3) and not ins_pre and not re.search(r'있|들어|모였|쌓였', ahead[:verb.start()]):
                return 'withdraw', None, None
    # '매달 50,000원씩만 받고' — '씩만'도 같은 말이다(stab 2241: 받는 금액을 못 읽고 되물었다). '씩' 없는 '3천만 원만 받고'는
    # 아니다 — '퇴직금 중 3천만 원만 받고 나머지는 IRP로'를 연금 수령액으로 읽었다(10-15 검토)
    if re.match(r'\s*(?:을|를|씩|정도|쯤|이|가)?\s*(?:씩)?\s*(?:(?<=씩)만\s*)?' + _PERIOD_MID + _ADV
                + r'(?:받|수령|나오|나와|나올|나온|나옵|연금으로\s*받)', q[e:e + 24]):
        return 'payout', period, None
    # '1,200만 원을 연금저축에서 연금으로 받으면' — 금액과 동사 사이에 '계좌에서'가 낀 어순 /
    # '연금저축 연간 수령액이 1,200만 원이면', '연금저축 연금 연 1,200만 원이면' — 수령액을 이름으로 말한 꼴(같은 뜻 다른 표현 시험).
    # '연금'은 낱말 하나일 때만 — '연금저축 말고 변액연금 연 1,000만 원'의 '변액연금'·'즉시연금'은 연금계좌가 아니다
    # (10-14 검토: 보험 연금에 연금계좌 연금소득세 5.5%를 매겨 55만 원)
    if re.match(r'\s*(?:을|를|씩)?\s*' + _PERIOD_MID + r'(?:연금저축|IRP|개인형|연금계좌|계좌)(?:\s*계좌)?\s*에서\s*'
                + _PERIOD_MID + r'(?:연금으로\s*)?' + _ADV + r'(?:받|수령|나오|나와|나올)', q[e:e + 36], re.I) or \
            re.search(r'(?:수령액|(?<![가-힣])연금\s*(?:연간?|1년에?)?)\s*(?:이|은|는|이요)?\s*(?:연\s*|연간\s*)?$', pre) and \
            re.search(r'연금저축|IRP|개인형|연금계좌', q[max(0, s - 30):s], re.I):
        if period is None and re.search(r'연간|(?<![가-힣])연\s*$|수령액', pre):
            period = 'yearly'
        return 'payout', period, None
    return None, None, None


# 부득이한 사유(doc20·doc1). '이민 갑니다'·'해외로 이사'도 해외이주로 읽는다 — 못 읽으면 블록이 16.5% 로 틀을 짠다(Q-087 같은 질문).
# 영주권은 그 자체로는 사유가 아니지만(doc20: 단순 장기체류·영주권 취득만으로는 인정 안 됨) 그 말을 블록에 실어야 하므로 받는다.
_EMIGRATE = re.compile(r'해외\s*이주|이민|(?:해외|외국|국외)(?:로|으로)?\s*(?:이주|이사)|영주권')
_UNAVOIDABLE = re.compile(r'부득이|요양|사망|돌아가(?:시|셨|신)|별세|파산|개인\s*회생|회생\s*절차|천재지변|재난')
_EARLY_HARD = re.compile(r'중도\s*인출|중도\s*해지|55\s*세\s*(?:되기\s*)?전|55\s*세도\s*안')
# '해지'·'깨'는 연금계좌에서 돈을 빼는 말일 때만 55세 전·해지 인출로 본다.
# '주식형으로 바꾸고 싶으면 이거 해지하고 다시 사야' — 계좌 안에서 상품만 바꾸는 말이다(Q-021 같은 질문)
_SWITCH_PRE = re.compile(r'바꾸|바꿔|바꿀|갈아\s*타|교체|리밸런싱')
_SWITCH_POST = re.compile(r'\s*(?:하고|한\s*(?:뒤|후|다음)(?:에)?|해서)?\s*'
                          r'(?:다시\s*(?:사|매수|가입|담)|재매수|갈아\s*타|다른\s*(?:거|걸|것|펀드|상품))')
# 해지하는 대상 — 맨 뒤(가장 가까운) 말이 연금계좌가 아니면(ISA·예금·펀드…) 연금계좌 인출이 아니다
_CANCEL_OBJ = re.compile(r'연금저축(?:펀드|계좌|보험)?|IRP|개인형|연금\s*계좌|계좌|ISA|예금|적금|청약|(?<!연금저축)보험|펀드|ETF|TDF|상품',
                         re.I)


def _early(q):
    if _EARLY_HARD.search(q):
        return True
    for m in re.finditer(_HAEJI + r'|깨(?:면|서|고)', q):
        clause = re.split(r'[.?!\n,]', q[max(0, m.start() - 25):m.start()])[-1]
        if _SWITCH_PRE.search(clause) or _SWITCH_POST.match(q, m.end()):
            continue
        objs = _CANCEL_OBJ.findall(clause)
        if objs and not re.match(r'연금저축|IRP|개인형|연금\s*계좌|계좌', objs[-1], re.I):
            continue
        return True
    return False


# 영주권 취득·단순 장기체류만으로는 부득이한 사유(해외이주)가 아니다 — 「해외이주법」에 따른 해외이주신고확인서가 있어야 한다(doc20).
# 이민·해외이주라는 말 없이 이 말만 있으면 사유인지 모른다(9차 검토 908: 영주권을 해외이주로 단정했다). '해외로 이사'도
# 이주 신고 없는 장기체류일 수 있어 같다 — p['emigrate'] 로는 읽되(test_rules: 블록이 해외이주 규칙을 싣는다) 확인서를 먼저 묻는다
_EMIGRATE_WEAK = re.compile(r'영주권|장기\s*체류|(?:해외|외국|국외)(?:로|으로)?\s*이사')
_EMIGRATE_FIRM = re.compile(r'해외\s*이주|이민|(?:해외|외국|국외)(?:로|으로)?\s*이주')
# '55세 전'을 나이로 말한 것 — 이 말이 없고 고객 나이가 55세 이상이면 해지·중도인출 말이 있어도 55세 전 인출이 아니다(9차 검토 901)
_EARLY_AGE = re.compile(r'55\s*(?:세|살)\s*(?:가|이|를|도)?\s*(?:되기\s*)?(?:전|이전|미만)'
                        r'|55\s*(?:세|살)\s*(?:가|이|를|도|는)?\s*(?:아직\s*)?(?:안|못)\s*(?:넘|됐|되|돼|찼|채)|55\s*(?:세|살)도\s*안')
# 연금 개시 여부 — ontology._STARTED_NO_Q·_STARTED_YES_Q 와 같은 말(경로와 계산 블록이 같은 판정을 쓰게)
_STARTED_NO = re.compile(r'개시\s*(?:를|을)?\s*(?:안|않|하지\s*않|신청\s*(?:을\s*)?(?:안|않|전|하기\s*전))|개시\s*(?:신청\s*)?전|개시하기\s*전')
_STARTED_YES = re.compile(r'연금\s*(?:을|를)?\s*(?:받고\s*있|받는\s*중|수령\s*중)|개시\s*(?:를|을)?\s*(?:했|한\s*(?:뒤|후|다음))'
                          r'|개시\s*(?:이후|후)|지급\s*중|연금\s*(?:을\s*)?받은\s*지')
# 해지하지 않는다는 말 — '해지하지 말고 연금으로', '해지 없이'
_NOT_CANCEL = re.compile(r'해지\s*(?:는\s*)?(?:하지\s*)?(?:말고|않고|안\s*하고|없이)')
# 해지할 때 나이 — '65세에 연금저축 해지하면'의 65세는 고객 나이(_AGE 는 '○세에 연금'을 뺀다)가 아니라 해지하는 나이다
_CANCEL_AGE = re.compile(r'(?<![\d,.])(\d{2})\s*(?:살|세)\s*(?:에|때|쯤에?|되면|이\s*되면|가\s*되면|넘어서|넘으면)'
                         r'(?P<mid>[^.?!\n]{0,30}?)(?:' + _HAEJI + r'|' + _BREAK + r'|중도\s*인출|인출)')
# 나이와 해지 말 사이의 다른 술어 — 나이는 그 술어에 묶인다. '50세인데 65세에 받기로 한 연금저축을 지금 해지하면'의 65세는
# 받는 나이, '60세에 개시하려던'·'개시를 60세에 하려던'은 개시 나이다(10차 검토 1003: 9차가 30자 안의 아무 나이를 해지 나이로
# 읽어 고객 나이 50세보다 앞세워 '55세 이후 해지' 블록을 냈다 — 맞는 값은 55세 전 330만 원). '개시 전에·받기 전에 해지'는
# 해지 나이 그대로다
_CANCEL_AGE_OTHER = re.compile(r'받(?!기\s*전)|수령(?!\s*(?:전|하기\s*전))|개시(?!\s*(?:신청\s*)?(?:전|하기\s*전|안|않))|시작'
                               r'|(?<![가-힣])(?:타(?=려|기|고|는|던|면|게|서|다)|탈(?=\s|까|지)|탄(?=\s)|탔)|가입|들었|들어|(?<![가-힣])든(?=\s)'
                               r'|넣|납입|부었|붓|부은|모은|모아|퇴직|은퇴|퇴사|(?<![가-힣])하(?=려|기로|고\s|면|다가|는\s|던)')
# 그 술어가 해지보다 앞선 일 — 지난 일('62세에 개시한·받기 시작한·가입한·받고 있는')이거나 이어지는 일('60세에 퇴직하고·받다가').
# 그 나이 이후에 해지하므로 55세 이상이면 해지도 55세 이후다(9차 전에는 이 꼴도 해지 나이로 읽었다)
_CANCEL_AGE_DONE = re.compile(r'(?:받|수령|개시|시작|가입|넣|납입|퇴직|은퇴|퇴사)\s*(?:하)?(?:은|한|았|었|했|하였)|들었|부었'
                              r'|(?<![가-힣])(?:든|탄|탔|부은)(?![가-힣])|(?:받|수령|개시)\s*(?:하고\s*있|고\s*있|하는\s*중|는\s*중|\s*중)')
# 이어지는 일 — '퇴직하고·받다가·시작해서'. '받으려고 했던·받고자 한'은 하려던 일이라 아니다
_CANCEL_AGE_SEQ = re.compile(r'\S*?(?<!려)(?<!고자)(?:고|서|다가|면|며)(?=\s|$)(?!\s*(?:했던|한\s|하던|할\s|하는|했|하려|싶))')
# 해지가 지금이라는 말·다른 나이 — '65세에 받기 시작해서 지금 해지'처럼 앞선 일이면 그 나이 이상, 아니면 해지 나이가 아니다
_CANCEL_AGE_NOW = re.compile(r'지금|현재|당장')
# 하려다 만 해지 — '65세에 해지하려던 연금저축을 지금 깨면'의 65세는 지난 계획이다
_CANCEL_AGE_PAST = re.compile(r'\s*(?:하|해)?\s*(?:려던|려고\s*했던|기로\s*했던|[가-힣]?\s*(?:생각|예정|계획)이던)')
# 나이에 바로 묶인 첫 술어가 하려는 일이면('65세에 받으려고·개시할 생각으로·받고 싶어서·받기로 하고 가입한') 그 나이는 받는·개시하는
# 나이다. 10차는 해지에 가장 가까운 술어('가입한')만 보아 지난 일로 읽고 65세를 해지 나이로 썼다(stab 2200: 52세 고객에 '55세 이후
# 해지' 블록 — 맞는 값은 55세 전 495만 원). 나이는 뒤따르는 첫 술어에 묶인다
_CANCEL_AGE_INTENT = re.compile(r'려(?:고|는|던|면|\s*(?:하|해|한|했))|고\s*싶|싶어|고자|기로'
                                r'|[가-힣]\s*(?:생각|예정|계획)\s*(?:으로|이|인|이라|이던|이었)')


def _cancel_age(q):
    """해지·인출할 때 나이가 하나로 분명하면 그 나이 — 나이가 해지 말에 바로 묶일 때('65세에 연금저축 해지하면'), 또는 해지보다
    앞선 일에 묶여 해지가 그 나이 이후일 때('62세에 개시한 연금저축 해지·60세에 퇴직하고 해지'). 받기로 한·개시하려던 계좌를
    꾸미는 나이('65세에 받기로 한 연금저축')와 '지금' 해지는 해지 나이가 아니다 — 고객 나이(50세인데)를 쓴다."""
    ages = set()
    cust = customer_age(q or '')                # 지금 나이('50세인데') — 받는·개시 나이('65세에 받')는 빠진다
    for m in _CANCEL_AGE.finditer(q or ''):
        a, mid = int(m.group(1)), m.group('mid')
        if not 19 <= a <= 99 or re.search(r'\d{2}\s*(?:살|세)', mid) or _CANCEL_AGE_PAST.match(q, m.end()):
            continue
        now = bool(_CANCEL_AGE_NOW.search(mid))
        other = list(_CANCEL_AGE_OTHER.finditer(mid))
        if other:
            first = mid[other[0].start():other[1].start() if len(other) > 1 else len(mid)]
            if _CANCEL_AGE_INTENT.search(first):
                continue                    # '65세에 받으려고 가입한' — 나이는 하려는 일(받기)에 묶인다
            tail = mid[other[-1].start():]
            done = _CANCEL_AGE_DONE.match(tail)
            if not (done or _CANCEL_AGE_SEQ.match(tail)):
                continue                    # 계좌를 꾸미는 다른 술어('받기로 한·개시하려던·받을') — 그 술어의 나이
            # 지금 나이 — 고객 나이가 하나로 안 정해져도('52세인데 65세에 가입한'은 나이가 둘) 이 나이 말고 다른 나이가 하나면 그 나이
            now_age = cust if isinstance(cust, int) else None
            if now_age is None:
                rest = {int(x) for x in _AGE.findall(q) if 19 <= int(x) <= 99} - {a}
                now_age = rest.pop() if len(rest) == 1 else None
            if done and now_age is not None and a > now_age:
                continue                    # 지금 나이보다 뒤의 나이에 이미 한 일일 수 없다 — 그 나이는 해지 나이가 아니다
            if now and (a < 55 or isinstance(cust, int) and cust < 55):
                continue                    # 앞선 일 뒤 '지금' 해지 — 지금 나이로 본다(55세 이상이면 해지도 55세 이후)
        elif now:
            continue
        ages.add(a)
    return ages.pop() if len(ages) == 1 else None


def _started(q):
    """연금 개시 여부 → True(받는 중) / False(개시 신청 전) / None(모름)."""
    if _STARTED_NO.search(q or ''):
        return False
    if _STARTED_YES.search(q or ''):
        return True
    return None


def _late_cancel(p):
    """만 55세 이후의 해지·중도인출인가 — 고객 나이가 55세 이상으로 분명하고 '55세 전'을 말하지 않았다.
    '60세인데 연금저축 2000만 원 해지'를 '55세 전·해지 인출 세금' 블록으로 330만 원이라 냈다(9차 검토 901). 55세 이후 해지는
    개시 신청 전이면 연금외수령(doc5), 연금 지급 중이면 연금수령한도까지 연금소득세(doc1)로 갈린다."""
    a = p.get('cancel_age') or p['age']          # '65세에 해지하면' — 해지할 때 나이
    old = isinstance(a, int) and a >= 55 or isinstance(a, tuple) and a[1] >= 60
    return bool(old and p['early'] and not p.get('early_age'))


# 나중에 꺼낸다는 말 — '내년에', '3년 뒤쯤'. 지금 나이에 이 햇수를 더하면 55세에 닿으면 인출할 때 55세 전인지 모른다
_LATER = re.compile(r'(내년|후년)|(?<![\d,.])(\d{1,2})\s*년\s*(?:쯤|정도)?\s*(?:뒤|후|있다가|지나(?:서|면))')


def _age_cross(p, q):
    """지금은 55세 전이지만 '내년에·3년 뒤' 꺼내면 그때 55세가 될 수 있는가."""
    a = p['age']
    if not isinstance(a, int) or a >= 55:
        return False
    for m in _LATER.finditer(q or ''):
        n = (1 if m.group(1) == '내년' else 2) if m.group(1) else int(m.group(2))
        if a + n >= 55:
            return True
    return False


def _early_eff(p):
    """55세 전·해지 인출로 계산할지 — 55세 전 나이, 또는 해지·중도인출 말이 있고 55세 이후로 분명하지 않을 때."""
    a = p['age']
    if isinstance(a, int) and a < 55 and not p['future'] and not (p.get('cancel_age') or 0) >= 55:
        return True
    return bool(p['early']) and not _late_cancel(p)


def _old_q(q):
    """(구)개인연금저축 질문인가 — '(구)개인연금·구 개인연금', 또는 '개인연금'과 2000년 이전 해."""
    return bool(re.search(r'\(구\)\s*개인연금|구\s*개인연금', q)) or \
        bool(re.search(r'개인연금', q) and re.search(r'(?:19\d\d|2000)\s*년', q))


def _old_dest(wide):
    """금액 앞 마디에서 가장 가까운 계좌 이름이 (구)개인연금저축인가('(구)개인연금저축 300만 원 납입')."""
    ms = list(re.finditer(r'(?:\(구\)\s*|구\s*)?개인\s*연금(?:\s*저축)?|연금\s*저축|IRP|DC|퇴직\s*연금', wide, re.I))
    return bool(ms) and ms[-1].group(0).lstrip('(구) ').startswith('개인')


def _plan_kind(q):
    """연금계좌(연금저축·개인형 IRP)가 아닌 퇴직연금 제도만 말했으면 그 제도 — 'db' / 'dc' / 'irp_corp'(기업형 IRP) /
    'retire'(종류를 말하지 않은 퇴직연금) / None. 연금계좌 이름이 하나라도 있으면('DB형인데 IRP 해지') 그 계좌 얘기라 None.
    제도마다 인출 규칙이 달라(doc49: DB 는 중도인출 불가) 연금계좌 해지 세금(①②③ 재원·16.5%)으로 계산하면 안 된다(9차 검토 900)."""
    if re.search(r'연금\s*저축|(?<!기업형)(?<!기업형\s)IRP|개인형|연금\s*계좌', q, re.I):
        return None
    if re.search(r'기업형\s*IRP', q, re.I):
        return 'irp_corp'
    if re.search(r'(?<![A-Za-z])DB(?![A-Za-z])|확정\s*급여', q, re.I):
        return 'db'
    if re.search(r'(?<![A-Za-z])DC(?![A-Za-z])|확정\s*기여', q, re.I):
        return 'dc'
    if re.search(r'퇴직\s*연금', q):
        return 'retire'
    return None


# 단위 없는 금액 — 연금 질문에서는 만 원으로 읽는다. 대화 21개를 끝까지 돌려 보니 '1년에 2,000 받으려는데'·'연 1,800 받을 건데'를
# 못 읽어 계산 블록이 없었고, 모델이 67·68세에 4.4%를 적용했다(C02·C13). '어디에 600 넣는'·'연봉 4,500'도 같은 빈틈.
_BARE_N = r'(\d{1,3}(?:,\d{3})+|\d{2,5})'
# 계좌 별칭 — 'A에 300, B에 400 넣었고', '한 곳에서 연 900, 다른 데서 연 800 받으면'. 같은 꼴의 다음 항목과 쉼표로 이어진
# 나열이면 앞 금액도 그 나열의 금액이다(stab 2211: 'A에 300'을 버려 99만 원 — 맞는 값 132만 원, 2244: 연 900을 버림)
_ALIAS = (r'(?:(?<![가-힣A-Za-z])[A-Za-z]\s*(?:계좌)?\s*(?:에|에는|엔|은|는)'
          r'|(?<![가-힣])(?:한\s*곳|다른\s*(?:곳|하나)|하나)\s*(?:에서는|에서|에선|에|은|는)|(?<![가-힣])다른\s*데\s*(?:서는|서|에서|에))\s*'
          r'(?:(?:1년에|연간?|매년|매달|매월|한\s*달에?|월)\s*)?')
# 한도 인용의 꼬리 — '900까지', '9백 한도', '6백 넘으면', '600 이상은'
_LIMIT_TAIL = r'\s*(?:만\s*원?|백|천)?\s*(?:까지|한도|이\s*한도|(?:을|를|이|가)?\s*(?:넘|이상|초과|이하|미만))'
# 쉼표 뒤 나열의 다음 항목 — 계좌 이름·별칭(+ 기간 말) 바로 뒤 숫자('…, IRP 월 20', '…, B에 400'). 그 숫자가 한도 인용이면
# ('연 600, IRP는 연 900까지 공제된다던데') 나열 전체가 한도 인용이다
_LIST_NEXT = (r'\s*(?:(?:연금저축|IRP|개인형)(?:\s*계좌)?\s*(?:에서는|에서|에는|에|엔|은|는|도)?\s*'
              r'(?:(?:1년에|연간?|매년|매달|매월|한\s*달에?|월)\s*)?|' + _ALIAS + r')(?:약\s*)?'
              r'(?:\d{1,3}(?:,\d{3})+|\d+)(?!\d|,\d)(?!' + _LIMIT_TAIL + r')')
# 마침표는 뒤에 숫자가 올 때만(1.5) 숫자의 일부다. 쉼표는 뒤에 같은 꼴의 다음 항목이 올 때만 나열이다 — 나열의 쉼표
# ('연금저축 월 30, IRP 월 20')까지 막아 앞 금액을 버렸지만(stab 2217·2254), 쉼표를 다 받으면 '월 100, 1년에 1,200'(같은 돈을
# 두 번 말함)을 더해 396만 원, '연 600, IRP 합치면 900까지'(한도 인용)를 납입으로, '1,300, 저는 …'(남편 몫)을 내 수령액으로 읽었다
_BARE_STOP = (r'(?!\d|,(?!' + _LIST_NEXT + r')|\.\d'
              r'|\s*(?:만|원|%|세|살|년|개|억|천|백|대|호|좌|주|배|건|명|회|차|월|일|시|분|등급|기|위|번|p|P))')
_BARE_PERIOD = re.compile(r'(?:1년에|일년에|한\s*해에?|연간?|매년|매달|매월|한\s*달에?|(?<![\d개])월)\s*(?:약\s*|대략\s*)?' + _BARE_N + _BARE_STOP)
_BARE_VERB = re.compile(r'(?<![\w.,])' + _BARE_N + r'(?=\s*(?:을|를|씩|정도|쯤|이|가)?\s*(?:씩)?\s*' + _ADV
                        + r'(?:넣|납입|입금|불입|채우|채워|채운|채웠|받|수령|빼|인출|찾|꺼내|해지|옮기|옮겨|넘기|넘겨))')
_BARE_INCOME = re.compile(r'(?:연봉|총\s*급여|(?<!퇴직)(?<!퇴직\s)급여|' + _INCOME_BARE_WORD + r')\s*(?:(?:이|가|은|는)\s*)?(?:(?:약|대략)\s*)?'
                          r'(\d{1,2},\d{3}|\d{4})(?!\d|,\d|\s*(?:만|원|억|천|년))')
# 쓰임을 정하는 이름 바로 뒤 단위 없는 숫자 — '퇴직소득세는 600이었어요', '평가액 5,000이면'. 단위를 붙인 꼴('600만 원')은 _role 이
# 이 이름으로 쓰임을 정하는데, 맨 숫자는 읽는 길이 없어 준 값을 되물었다(stab 2260·2271)
_BARE_NOUN = re.compile(r'(?:퇴직\s*소득\s*세(?:액)?|평가\s*금액|평가액|잔액|잔고|적립금|퇴직금|퇴직\s*급여)\s*(?:(?:은|는|이|가)\s*)?'
                        r'(?:(?:약|대략)\s*)?' + _BARE_N + _BARE_STOP)
# 재원을 밝힌 단위 없는 금액 — 이름이 앞('공제 안 받고 넣은 게 400')이거나 뒤('나머지 900은 공제 안 받은 돈')인 꼴. 쓰임은 _role 이
# 같은 말로 정한다(stab 2222: '900'을 못 읽어 비과세 원금을 놓쳤다)
_BARE_FUND_PRE = re.compile(r'(?:' + _FREE_NAME + '|' + _CREDIT_NAME + r')(?:\s*(?:재원|부분|분))?\s*(?:이|가|은|는|이요|만|도)?\s*'
                            r'(?:(?:약|대략|한)\s*)?' + _BARE_N + _BARE_STOP)
_BARE_FUND_POST = re.compile(r'(?<![\w.,])' + _BARE_N + r'(?![\d,.])(?=' + _FUND_POST.pattern + ')')
# 만 없는 N천·N천M백·N백 — '평가액 6천인데', 'IRP 9백 넣으면', '연금저축 3백, IRP 2백'. 연금 질문에서 이 꼴은 만 원 단위다.
# 9차까지는 N천 뒤에 넣·받·빼 같은 말이 올 때만 읽고 N백은 아예 읽지 않아, 평가액·잔액·납입액을 버리고 준 값을 되묻거나
# 남은 금액만으로 틀린 공제액을 냈다(stab 2216·2219·2224·2230 …). 단위를 붙인 꼴과 똑같이 금액으로 읽고 쓰임은 _role 이 앞뒤 말로
# 가른다 — 쓰임을 모르면 역할 None 이라 숫자를 내지 않는다. 뒤에 명·개·년 같은 셈 말이 오면 금액이 아니다
# '1천오백만 원'처럼 한글 수가 이어지면 이 꼴이 아니다(1,000으로 읽지 않는다). '5천이에요'의 '이'는 조사라 뒤에 단위가 올 때만 수다
_BARE_KU = re.compile(r'(?<![\d가-힣.,])(?:(\d(?:\.\d)?)\s*천(?:\s*(\d)\s*백)?|(\d)\s*백)'
                      r'(?!\s*(?:만|원|억|천|백|십|\d|명|개|년|살|세(?![금액율제법])|번|회|건|배|대|위|등|호|주|평|%)'
                      r'|[일이삼사오육칠팔구]\s*(?:십|백|천|만))')
# 만 없는 N천·N백을 읽지 않는 자리 — 한도 인용('6백까지만 공제', 'IRP 9백 한도 중에'), 고객이 짐작한·들은 세금('세금 2백 나오나요',
# '결정세액이 1백인데'), 소득 자리('사업소득이 5천 정도인데 필요경비 빼면 3천' — 수입인지 소득금액인지 모름. 연봉·총급여·
# 종합소득(금액)은 _INCOME_BARE 가 먼저 읽는다). 9차까지처럼 읽지 않는다 — 읽으면 납입·수령액으로 계산했다
# 한도 인용은 쉼표로 이어진 다음 항목에 붙어도 같다('IRP는 9백, 연금저축은 6백까지 공제된다던데')
_KU_LIMIT_POST = re.compile(_LIMIT_TAIL + r'|\s*,[^.?!\n,\d]{0,20}\d[\d,.]*' + _LIMIT_TAIL)
# '세금'은 낱말 앞이 끊길 때만 — '전세금으로 2천 빼면'의 2천은 인출액이다
_KU_TAX_PRE = re.compile(r'(?:(?<![가-힣])세금|결정\s*세액|산출\s*세액)\s*(?:은|는|이|가|도|만|으로|로)?\s*(?:약|대략|한)?\s*$')
_KU_INCOME_PRE = re.compile(r'(?:연봉|(?<!퇴직)(?<!퇴직\s)급여|소득)\s*(?:\([^)]{0,8}\)\s*)?(?:은|는|이|가|도|이요)?\s*'
                            r'(?:약|대략|대충|한)?\s*$')
_BARE_ALIAS = re.compile(_ALIAS + _BARE_N + _BARE_STOP + r'(?=\s*,\s*' + _ALIAS + r'\d)')
_ALIAS_INTRO = re.compile(r'(연금저축|IRP|개인형)\s*(?:계좌)?\s*(?:가|이|는|은|도)?\s*(?:두|세|2|3)\s*(?:개|곳|군데)', re.I)


def _alias_intro(q, end):
    """별칭 계좌('A에', '한 곳에서')가 가리키는 계좌 종류 — 앞에서 '연금저축 계좌가 두 개예요'처럼 한 종류로 소개했을 때만
    '연금저축'·'IRP', 아니면 None(어느 계좌인지 모름)."""
    intro = {_acct_id(n) for n in _ALIAS_INTRO.findall(q[:end])}
    return None if len(intro) != 1 else '연금저축' if intro == {'연금저축'} else 'IRP'
_BARE_CTX = re.compile(r'연금|IRP|ISA|공제|세금|세율|떼|납입|수령', re.I)


def _product_words():
    """상품 이름에서 숫자 바로 앞에 오는 말 — '라이프사이클 7090'·'거북이 90'·'코스닥 150'."""
    words = {'라이프사이클', '거북이', '롱숏', 'KRX', 'KOSPI', '코스피', '코스닥', 'KOSDAQ', '나스닥', 'NASDAQ', 'S&P', '다우',
             '인덱스', '밸류', '국채', 'TDF', 'KODEX', 'TIGER', 'ACE', 'KBSTAR', 'SOL', 'ARIRANG', 'HANARO', 'KOSEF', '빈티지',
             '타겟데이트', '타깃데이트'}
    try:
        cards = json.load(open(os.path.join(ROOT, 'data', 'fund_cards.json'), encoding='utf-8'))
        for f in cards:
            for m in re.finditer(r'([가-힣A-Za-z&]{2,})\s*\d{2,4}', f.get('fund_name') or ''):
                w = m.group(1)
                words.add(w[-4:] if re.match(r'[가-힣]', w[-1]) else w[-5:])
    except Exception:
        pass
    return words


_PRODUCT_NUM = re.compile(r'(?:' + '|'.join(sorted((re.escape(w) for w in _product_words()), key=len, reverse=True))
                          + r')\s*\d{2,4}', re.I)


def product_spans(q):
    """상품 이름 속 숫자 자리 [(시작, 끝)] — 이 자리의 숫자는 금액이 아니다."""
    return [(m.start(), m.end()) for m in _PRODUCT_NUM.finditer(q or '')]


# 금액이 아니라 확인하려는 결과(세후 실수령·공제 결과)나 빼는 몫 — '세금 떼고 1,503 받는 거죠', '퇴직금 500 빼고 받으면',
# '세액공제 300 받을 수 있나요', '공제 한도 300 넘기나요'(검토: 이런 숫자를 입력으로 읽어 계산 블록을 깎거나 바꿨다)
_NOT_INPUT_PRE = re.compile(r'(?:떼고|세후|실수령(?:액)?|빼고|공제|한도)\s*(?:은|는|이|가|로|으로)?\s*(?:약|대략)?\s*$')
_NOT_INPUT_POST = re.compile(r'\s*(?:을|를|만)?\s*(?:빼고|제외하고)\s*(?:받|나머지|남은)')
# 연도에만 붙는 말 — 서류 이름(원천징수영수증·지급명세서·납입증명서·납입확인서 …, 앞에 소득 종류가 껴도), 귀속, 년·년도·연도.
# orchestrator._YEAR_CTX(단위 없는 숫자 그물)도 이 목록을 쓴다 — 두 곳이 따로 정해 '연금저축 2019 납입증명서'를 여기서는
# '납입'을 넣는 말로 보아 2,019만 원 납입으로, 그물은 연도로 보아 아무도 되묻지 않았다(10-14 7차 검토 611·612).
# '기준'·'원천징수되면'·'연말정산'은 금액에도 붙어 넣지 않는다(6차 검토 506~508)
_YEAR_WORD = (r'(?:(?:퇴직|근로|연금|이자|배당|사업|종합|기타)?\s*소득\s*)?'
              r'(?:원천\s*징수\s*(?:영수증|내역|명세서?)|지급\s*명세서?|납입\s*(?:증명서?|확인서)|영수증|명세서|증명서|귀속|년도?|연도)')
_YEAR_AFTER = re.compile(r'\s*' + _YEAR_WORD)
# 상품 목표 연도 뒤에 오는 이름 — '2040 TDF'·'2045 빈티지'·'2050 타겟데이트'(숫자가 이름 앞). 이름 뒤 숫자('TDF 2040')는 product_spans 가
# 막는다. orchestrator._BARE_AFTER_ACCT 도 이것을 써서 계좌 이름 바로 뒤 빈티지('연금저축 2030 TDF에')를 되묻지 않는다
_VINTAGE_WORD = r'(?:형|짜리)?\s*(?:TDF|빈티지|타[겟깃]\s*데이트)'
_VINTAGE_AFTER = re.compile(r'\s*' + _VINTAGE_WORD, re.I)


def _bare_amounts(q, taken, notes=None, years=None):
    """단위 없는 금액 → [(만원 값, 시작, 끝)]. 이미 읽은 금액과 겹치면 뺀다. 펀드 이름의 숫자(TDF 2045)·연도는 금액이 아니다.
    notes 를 주면 어떻게 읽었는지 적는다 — 답의 '가정'에 밝히고, 결과가 크게 갈리는 것은 시연 채널에서 되묻는다(사용자 결정 10-10).
    years 를 주면 연도·빈티지일 수 있어 읽지 않은 숫자 (글, 시작, 끝)를 담는다 — orchestrator 그물이 이것으로 단위를 되묻는다."""
    if not _BARE_CTX.search(q):
        return []
    import datetime
    yy = (datetime.date.today().year + 1) % 100     # 두 자리로 줄여 쓴 해의 끝(내년) — 아래 연도 판정
    out = []
    prod = product_spans(q)
    for rx in (_BARE_PERIOD, _BARE_VERB, _BARE_INCOME, _BARE_NOUN, _BARE_ALIAS, _BARE_FUND_PRE, _BARE_FUND_POST):
        for m in rx.finditer(q):
            raw = m.group(1)
            v = float(raw.replace(',', ''))
            s, e = m.start(1), m.end(1)
            if not 10 <= v <= 99999 or any(a <= s < b or s <= a < e for a, b in taken + prod):
                continue
            # 'TDF 2045'·'TDF2040'처럼 이름 바로 뒤 숫자만 막는다('IRP에서 연 1,800'의 IRP 는 이름이 아니다)
            if re.search(r'(?:[A-Za-z]|펀드|빈티지)\s*$', q[max(0, s - 8):s]):
                continue
            if _NOT_INPUT_PRE.search(q[max(0, s - 10):s]) or _NOT_INPUT_POST.match(q, e):
                continue
            # 쉼표 뒤 다음 항목이 같은 계좌면('연금저축 월 30, 연금저축 연 360') 다른 계좌의 나열이 아니라 같은 돈을 다시 말한 것일 수
            # 있다 — 앞 금액을 읽지 않는다(9차까지와 같게)
            nxt = re.match(r'\s*,\s*(연금저축|IRP|개인형)', q[e:], re.I)
            if nxt:
                own = re.findall(r'연금저축|IRP|개인형', re.split(r'[.?!\n,]', q[max(0, s - 20):s])[-1], re.I)
                if own and _acct_id(own[-1]) == _acct_id(nxt.group(1)):
                    continue
            # 연도 — 4자리 19xx·20xx 뒤에 연도에만 붙는 말이 오면 금액이 아니다(7차 검토 611·612). 서류에 찍힐 수 있는 해인지
            # (1990년~내년)는 여기서 가리지 않는다 — 금액으로 읽지 않고 years 에 담으면, 있을 수 없는 해는 orchestrator 그물이 되묻는다.
            # 연도 말이 없어도 2020~2079 는 읽지 않는다(빈티지·연도일 수 있어 그물이 되묻는다).
            # 기간 말(매달·월·연간·1년에·매년) 바로 뒤도 같다 — 8차는 '해가 기간 말 뒤에 오지 않는다'고 보아 이 판정을 기간 말 뒤에서
            # 통째로 꺼서, '매월 2040 TDF로 50만원'을 2,040만 원 월 납입으로 99만 원, '연간 2024 납입증명서'(한 해치 납입증명서일 수 있다)를
            # 2,024만 원으로 계산했다(9차 검토 801~807). 기간 말 뒤 해 꼴은 금액일 수도 해일 수도 있어 계산하지 않고, 그물이 늘 단위를 되묻는다.
            # 2020~2079 뒤에 TDF·빈티지·타겟데이트가 오면 상품 목표 연도라 되묻지도 않는다('2040 TDF'의 금액은 따로 있다).
            # 두 자리는 연도 말이 붙고 요즘 해(2010년~내년)를 줄여 쓴 꼴일 때만 해 꼴이다('24 납입증명서 보니' — 그물 _YEAR_CTX 와
            # 같게, 9차 검토 808). '50 납입확인서'·'매달 30 납입증명서'는 그런 해가 없어 금액이다 — 7차는 두 자리를 모두 해로 보아
            # '매달 50 납입확인서'의 금액을 지우고 계산도 되묻기도 없이 생성으로 갔다(8차 검토 709~711)
            if ',' not in raw and (re.fullmatch(r'(?:19|20)\d\d', raw) and (2020 <= v <= 2079 or _YEAR_AFTER.match(q, e))
                                   or len(raw) == 2 and v <= yy and _YEAR_AFTER.match(q, e)):
                # 기간 말 길에서 뺀 숫자를 넣는 말 길(_BARE_VERB)이 다시 볼 수 있어 한 번만 담는다
                if years is not None and not (2020 <= v <= 2079 and _VINTAGE_AFTER.match(q, e)) and (raw, s, e) not in years:
                    years.append((raw, s, e))
                continue
            if v >= 10000:
                # '월 50,000'·'80,000' — 다섯 자리는 원 단위로 쓴 금액이다(만 원으로 읽으면 5억·8억이 된다)
                if notes is not None:
                    notes.append({'raw': raw, 'text': f"'{raw}'을 {won(v / 10000)}(원 단위)으로 봄",
                                  'ask': f"말씀하신 '{raw}'은 {won(v / 10000)}인가요, {won(v)}인가요?"})
                v = v / 10000
            elif notes is not None:
                notes.append({'raw': raw, 'text': f"'{raw}'을 {won(v)}으로 봄", 'ask': '', 's': s})
            out.append((v, s, e))
            taken.append((s, e))
    for m in _BARE_KU.finditer(q):
        s, e = m.start(), m.end()
        # 소득 자리('연봉 6천')는 parse 가 _INCOME_BARE 로 따로 읽어 taken 에 넣어 둔다
        if any(a <= s < b or s <= a < e for a, b in taken + prod):
            continue
        if _NOT_INPUT_PRE.search(q[max(0, s - 10):s]) or _NOT_INPUT_POST.match(q, e):
            continue                        # '세후 3천'·'공제 한도 9백'·'퇴직금 5천 빼고 받으면' — 입력 금액이 아니다
        if _KU_LIMIT_POST.match(q, e) or _KU_TAX_PRE.search(q[max(0, s - 10):s]) or _KU_INCOME_PRE.search(q[max(0, s - 16):s]):
            continue
        v = float(m.group(1)) * 1000 + (int(m.group(2)) * 100 if m.group(2) else 0) if m.group(1) else int(m.group(3)) * 100
        if notes is not None:
            notes.append({'raw': m.group(0).strip(), 'text': f"'{m.group(0).strip()}'을 {won(v)}으로 봄", 'ask': '', 's': s})
        out.append((v, s, e))
        taken.append((s, e))
    return out


# 금액이 그 계좌의 금액임을 보이는 앞말 — '연금저축 600', 'IRP에 300'. '연금저축으로'·'IRP에서'는 옮기는 쪽·나오는 쪽이라 뺀다.
# '연금저축에 원래 600 넣었고'처럼 사이에 때·부사가 끼어도 같다 — 못 보아 600을 ISA 전환액으로 읽고 공제를 계산하지 않았다(stab 2214).
# '작년에'는 넣지 않는다 — 지난해 납입을 올해 납입으로 읽어 올해 공제를 계산했다(10-15 검토)
_ACCT_OWN = re.compile(r'(?:연금저축(?:펀드|계좌)?|IRP|개인형\s*IRP|연금\s*계좌)\s*(?:에|에는|은|는|이|가|도|만)?\s*'
                       r'(?:(?:원래|이미|벌써|올해|따로)\s*)?(?:약|대략)?\s*$', re.I)


def norm_ws(q):
    """공백 덩어리를 하나로 — 줄바꿈 덩어리는 줄바꿈 하나, 나머지 공백(NBSP·EM SPACE 포함)은 띄어쓰기 하나.
    정규식들이 \\s* 를 겹쳐 쓰므로 뜻은 같고, 긴 공백에서 역추적이 폭주하는 일을 막는다
    (검토: 줄바꿈 1,985개짜리 질문에 66초 — 정규식이 GIL 을 놓지 않아 그동안 서버 전체가 멈춘다)."""
    q = re.sub(r'[^\S\n]+', ' ', (q or '')[:2000])
    return re.sub(r'\s*\n\s*', '\n', q)


# 같은 뜻 다른 표기를 정규식이 읽는 꼴로 — 10-14 같은 뜻 다른 표현 144개 시험에서 같은 값이 51%뿐이었고, '아이알피에 900만 원'을
# 연금저축으로 읽어 79만 2천 원(맞는 값 118만 8천 원), '다달이 5만원'을 연 5만 원으로 읽는 등 틀린 계산까지 나왔다
_HNUM = {'일': 1, '이': 2, '삼': 3, '사': 4, '오': 5, '육': 6, '칠': 7, '팔': 8, '구': 9}
_HAN_AMOUNT = re.compile(r'(?<![가-힣\d.,])((?:[일이삼사오육칠팔구]?천)?(?:[일이삼사오육칠팔구]?백)?(?:[일이삼사오육칠팔구]?십)?[일이삼사오육칠팔구]?)'
                         r'\s*(만|억)(?=\s*원|\s*씩|\s*(?:을|를|이|가|은|는|에|으로|로|정도|쯤)|\s|[,.?!]|$)')
_ALIASES = [
    (re.compile(r'아이\s*알\s*피'), 'IRP'), (re.compile(r'(?<![A-Za-z])irp(?![A-Za-z])', re.I), 'IRP'),
    (re.compile(r'(?<![A-Za-z])isa(?![A-Za-z])', re.I), 'ISA'),
    (re.compile(r'연저(?=\s|에|가|는|도|만|를|랑|이랑|하고|만으로|\d|$)'), '연금저축'),
    (re.compile(r'연금\s+저축'), '연금저축'), (re.compile(r'연금\s+계좌'), '연금계좌'), (re.compile(r'총\s+급여'), '총급여'),
    (re.compile(r'세액\s+공제'), '세액공제'), (re.compile(r'(?<![가-힣])일\s*년'), '1년'), (re.compile(r'다달이|매\s*달마다'), '매달'),
    # '8백50만 원'·'4백2십만원' — 백 뒤에 십·자릿수가 더 붙은 꼴. 아래 'N백만' 규칙이 못 잡아 _MONEY 가 '50만'만 읽었다
    # (stab 2220: 연금저축 850만 원 납입을 50만 원으로 계산해 8만 2,500원 — 맞는 값 99만 원, 2259: 퇴직소득세 420만 원을 못 읽음)
    (re.compile(r'(?<![\d.,])(\d)\s*백\s*(\d)\s*십\s*만'), lambda m: f'{int(m.group(1)) * 100 + int(m.group(2)) * 10}만'),
    (re.compile(r'(?<![\d.,])(\d)\s*백\s*(\d{1,2})\s*만'), lambda m: f'{int(m.group(1)) * 100 + int(m.group(2))}만'),
    (re.compile(r'(?<![\d.,])(\d)\s*십\s*만'), lambda m: f'{int(m.group(1)) * 10}만'),
    (re.compile(r'(\d+)\s*백\s*만'), lambda m: f'{int(m.group(1)) * 100}만'),
    (re.compile(r'(\d+)\s*천\s*억'), lambda m: f'{int(m.group(1)) * 1000}억'),
]


def _han_num(s):
    v, cur = 0, 0
    for ch in s:
        if ch in _HNUM:
            cur = _HNUM[ch]
        else:
            v += (cur or 1) * {'십': 10, '백': 100, '천': 1000}[ch]
            cur = 0
    return v + cur


def normalize(q):
    """표기만 바꾼다(뜻은 그대로). parse·compute 가 먼저 부른다."""
    q = q or ''
    for rx, rep in _ALIASES:
        q = rx.sub(rep, q)

    def han(m):
        # '이만 하면'·'오만 가지'는 금액이 아니다 — 한 글자 수(이·오…)는 뒤에 '원·씩'이 올 때만 금액으로 본다
        if len(m.group(1)) == 1 and not re.match(r'\s*(?:원|씩)', q[m.end():]):
            return m.group(0)
        n = _han_num(m.group(1)) if m.group(1) else 0
        return f'{n}{m.group(2)}' if n else m.group(0)
    return _HAN_AMOUNT.sub(han, q)


def parse(q):
    q = normalize(q)
    """질문에서 계산에 쓸 입력을 뽑는다. 금액마다 쓰임·기간·출처를 단다."""
    q = norm_ws(q)
    spans = []
    found = money_spans(q)
    taken = [(s, e) for _, s, e in found]
    if re.search(r'넣|납입|입금|불입|공제|환급|돌려\s*받', q):
        for m in _BARE_ACCT.finditer(q):
            v = float(m.group(1))
            if 10 <= v <= 1800 and not any(s <= m.start(1) < e for s, e in taken):
                found.append((v, m.start(1), m.end(1)))
                taken.append((m.start(1), m.end(1)))
    # 소득 자리('연봉 6천'·'종합소득금액 3천')는 아래 _INCOME_BARE 가 소득으로만 읽는다 — 만 없는 N천 읽기가 겹쳐 읽지 않게 먼저 비워 둔다
    inc_bare = list(_INCOME_BARE.finditer(q))
    taken += [(m.start(), m.end()) for m in inc_bare]
    notes = []
    found += _bare_amounts(q, taken, notes)
    found.sort(key=lambda x: x[1])
    for v, s, e in found:
        role, period, kind = _role(q, s, e)
        spans.append({'v': v, 's': s, 'e': e, 'role': role, 'period': period, 'kind': kind, 'src': _source(q, s)})
        mm = re.search(r'(\d{1,2})\s*월\s*(?:에|에만)?\s*$', q[max(0, s - 7):s])
        if mm and role in ('contrib', 'payout', 'withdraw'):
            notes.append({'raw': q[s:e], 'text': f'{mm.group(1)}월에 {won(v)}은 그 달 한 번의 금액으로 봄(매달 아님)', 'ask': ''})
    # ISA 가 든 문장의 금액은 모두 ISA 전환액으로 읽힌다 — '연금저축 600, IRP 300 넣었고 ISA 만기 2천만원 옮기면'의
    # 600·300은 계좌별 납입이다. 전환액 후보가 둘 이상일 때만, 계좌 이름에 바로 붙은 금액(옮기는 말이 뒤따르지 않는)을 다시 읽는다
    isa_sp = [x for x in spans if x['role'] == 'isa']
    if len(isa_sp) >= 2:
        for x in isa_sp:
            sent_a = max(q.rfind(c, 0, x['s']) for c in '.?!\n') + 1
            ahead = re.split(r'[.?!\n,]', q[x['e']:x['e'] + 20])[0]
            own_verb = re.match(r'\s*(?:을|를|씩|은|는|도)?\s*' + _ADV + r'(?:더\s*)?(?:넣|납입|입금|불입|채웠|채우)', ahead)
            if _ACCT_OWN.search(q[sent_a:x['s']]) and (own_verb or not re.search(r'옮|이체|전환', ahead)):
                role, period, kind = _role(q, x['s'], x['e'], no_isa=True)
                if role:                    # 다시 읽어도 쓰임을 모르면('1,500만 원씩 나눠 넣으면') 그대로 둔다
                    x['role'], x['period'], x['kind'] = role, period, kind
    for m in inc_bare:
        v = int(m.group(1)) * 1000 + (int(m.group(2)) * 100 if m.group(2) else 0)
        kind = _income_kind(m.group(0))
        if not _OTHER_PERSON.search(q[max(0, m.start() - 10):m.start()]):
            # '종합소득 5천 넘는'·'연봉 5천 이하' — 소득은 그 값의 위·아래다. 공제율 기준(_INCOME_CUT)의 어느 쪽인지 그 말로 정해질 때만
            # 소득으로 쓰고, 갈리면 기준 인용처럼 뺀다(숫자 없음). 단위를 붙인 꼴은 _role 이 이런 말을 늘 기준 인용으로 뺀다
            side = _INCOME_SIDE.match(q, m.end())
            cut = _INCOME_CUT.get(kind)
            role = 'income' if not side or cut and (side.group(1) and v > cut or side.group(2) and v <= cut) else 'skip'
            spans.append({'v': v, 's': m.start(), 'e': m.end(), 'role': role, 'period': None,
                          'kind': kind if role == 'income' else None, 'src': 'earned'})
    # 별칭 계좌의 금액('연금저축이 두 개예요. 한 곳에서 월 70, 다른 곳에서 월 60')은 소개한 계좌의 금액이다 — 계좌 이름이 앞 문장에
    # 있어 출처를 몰라 '어느 계좌 것인지 분명하지 않음'으로 숫자를 뺐다
    for x in spans:
        if x['src'] is None and re.search(_ALIAS + r'$', q[max(0, x['s'] - 20):x['s']]) and _alias_intro(q, x['s']):
            x['src'] = 'private'
    # '금액 읽기' 메모는 계산에 쓰는 금액만 — 쓰임을 모르는 금액('지금 받는 월급이 5천인데')까지 '5,000만 원으로 봄'이라고 블록에
    # 적으면 계산에 쓴 것처럼 보인다. 단위를 되물을 메모(ask)는 그대로 둔다
    role_at = {x['s']: x['role'] for x in spans}
    notes = [n for n in notes if n.get('ask') or role_at.get(n.get('s'), 'x') not in (None, 'skip')]
    p = {'spans': spans, 'age': customer_age(q), 'amount_notes': notes}
    # 금액 바로 뒤 '받는 연말정산·받는 세액공제'(_DED_RECV_BARE)는 받는 금액일 수도 공제를 받는 납입액일 수도 있다. 근로·사업 소득을
    # 함께 말했으면 넣는 사람의 공제 질문('총급여 6천만 원, IRP 700만 원 받는 세액공제')으로 보고, 소득이 없거나 연금 받을 나이
    # (55세 이상)를 말했으면 받는 금액으로 둔다 — 확신이 없으면 납입으로 계산하지 않는다(10-14 5차 검토 409).
    # 소득이 있어도 금액에 기간 말이 붙으면('월 100만 원 받는', '연 1,200만 원 받는') 달마다·해마다 받는 연금일 수 있다 — 소득은
    # 넣는 사람이라는 근거가 못 된다(6차 505: '연금저축 월 100만 원 받는 연말정산? 총급여 5천'을 납입 99만 원으로, 'IRP 연 2,000만 원
    # 받는 연말정산? 연봉 4천'은 납입 한도 1,800만 원을 넘는 금액을 148만 5천 원으로 계산)
    age = p['age']
    old = isinstance(age, int) and age >= 55 or isinstance(age, tuple) and age[1] >= 60
    has_inc = any(x['role'] == 'income' for x in spans)
    for x in spans:
        if x['kind'] == 'recv':
            x['kind'] = None
            if x['role'] == 'contrib' and (old or not has_inc or x['period']):
                x['role'] = 'payout'
    # 55세는 보통 규칙 나이('55세부터 받을 수 있죠?')다. 지금 나이 이하도 받는 나이가 아니다.
    # '아버지가 70세에'처럼 같은 마디에 다른 사람이 있으면 그 사람 나이다
    fut, unsure = set(), False
    for m in _FUTURE_AGE.finditer(q):
        a = int(m.group(1))
        if not 56 <= a <= 99 or (isinstance(p['age'], int) and a <= p['age']):
            continue
        if _OTHER_PERSON.search(re.split(r'[.?!\n,]', q[max(0, m.start() - 12):m.start()])[-1]):
            continue
        if m.group(2):
            # '75세에 연금저축에서 연 1,000만 원 받으면' — 받는 금액이 '○세에'와 받는 말 사이에 있으면 그 금액을 받는 나이다.
            # 다른 데서 '지금 받는 ○○'(월급·임금·수당…)을 말해도 엇갈리지 않는다(10-14 3차 검토 205: 연금 아닌 낱말 목록에 없는
            # '월 급여·근로소득·임금'에 75세를 버려 5.5% 55만 원 — 맞는 값 4.4% 44만 원)
            v = _RECV_LATER_RX.search(q, m.end(), m.end() + 45)
            tied = bool(v) and any(x['role'] == 'payout' and m.end() <= x['s'] and x['e'] <= v.start() for x in spans)
            now = None if tied else _recv_now_kind(q)
            if now == 'unsure':
                unsure = True
                continue
            if now:
                continue
        fut.add(a)
    p['rate_age'] = fut.pop() if len(fut) == 1 and fut != {p['age']} else None
    p['rate_age_unsure'] = unsure and p['rate_age'] is None
    p['payout'] = [x for x in spans if x['role'] == 'payout']
    incomes = [x for x in spans if x['role'] == 'income']
    p['income'] = (incomes[0]['kind'], incomes[0]['v']) if len(incomes) == 1 and incomes[0]['kind'] else None
    p['income_unknown_kind'] = len(incomes) == 1 and not incomes[0]['kind']
    isas = [x for x in spans if x['role'] == 'isa']
    p['isa'] = isas[0]['v'] if len(isas) == 1 else None
    # 'ISA 3천만 원을 연금저축과 IRP에 반반(1,500만 원씩) 나눠 넣으면' — 나눠 옮기는 경우도 계산한다(C07 대화: 블록이 IRP 경우만 보여
    # 모델이 '연금저축 750 + IRP 1,050 → 296.99만 원'을 지어냈다)
    p['isa_split'] = bool(re.search(r'반반|반씩|절반|나눠|나누어', q) and '연금저축' in q and re.search(r'IRP|개인형', q, re.I))
    if p['isa'] is None and p['isa_split'] and len(isas) == 2:
        big, small = sorted((x['v'] for x in isas), reverse=True)
        if abs(big - 2 * small) < 1:
            p['isa'] = big                  # '3,000만 원을 1,500만 원씩' — 큰 쪽이 전환액
    bals = [x for x in spans if x['role'] == 'balance']
    p['balance'] = bals[0]['v'] if len(bals) == 1 else None
    wds = [x for x in spans if x['role'] == 'withdraw']
    p['withdraw'] = wds[0]['v'] if len(wds) == 1 else None
    p['contrib'] = []
    p['retire_dropped'] = []
    p['retire_unsure'] = []
    p['retire_db'] = []
    p['acct_unsure'] = []
    p['old_contrib'] = []
    old_q = _old_q(q)
    unsure_recs = []                        # 넣는 계좌를 모르는 금액과 그 앞 마디에 닫힌 계좌 이름
    for x in spans:
        if x['role'] != 'contrib':
            continue
        clause = re.split(r'[.?!\n,]', q[max(0, x['s'] - 20):x['s']])[-1]
        org = _retire_origin(q, x)
        if org == 'origin':
            p['retire_dropped'].append(x['v'])  # 퇴직금 쪽에서 온 돈 — 세액공제 블록이 왜 빠졌는지 밝힌다
            continue
        if org in ('unsure', 'db'):
            # 퇴직금 쪽인지 본인 돈인지 모름 — 숫자 없이 되묻는다(어느 쪽이라고 적지 않는다)
            p['retire_db' if org == 'db' else 'retire_unsure'].append(x['v'])
            continue
        # 마디의 '퇴직금'은 _retire_origin 이 이미 갈랐다(부정·본인 돈·받은 돈으로 넣는 말) — 여기서 다시 '퇴직금'만 보고 빼면
        # 갈린 판정과 어긋난다(4차는 이 검사에 주어 말 '제가'를 본인 돈으로 넣어 5차 400~406 이 났다)
        # '쌓인 돈 말고·지금까지 모은 거 말고 300만 원 더'처럼 부정된 말은 이 금액을 가리키지 않는다(5차 407)
        if any(not _negated(clause, m.end()) for m in _LUMP_CTX.finditer(clause)):
            continue                        # 쌓인 돈은 올해 납입액이 아니다
        v = x['v'] * 12 if x['period'] == 'monthly' else x['v']
        if v > 1800 and x['period'] is None:
            continue                        # 연 납입한도(1,800만)를 넘는 금액은 한 해 납입으로 보지 않는다
        # 금액 바로 앞에서 가장 가까운 계좌 이름 — 'IRP 300이랑 연금저축 900만'의 900은 연금저축이다
        # '확정기여형'도 DC다 — 이름 목록에 없어 연금저축(600만 원 한도)으로 셀 뻔했다. '○○ 말고'처럼 부정된 이름은 넣는 곳이 아니다.
        # 넣는 곳은 같은 마디에서 더 앞까지 본다 — 'DC에 회사가 넣어주는 거랑 별개로 제가 300만 원'의 DC가 20자 밖이라
        # 연금저축(기본값)으로 적었다(5차 407). '회사가 넣어준 돈 말고'의 DC는 출처로는 부정이지만 넣는 곳은 그대로 DC다
        wide = re.split(r'[.?!\n,]', q[max(0, x['s'] - 40):x['s']])[-1]
        names, dest_unsure, prior = _dest_parts(wide)
        # 'A에 300, B에 400' — 별칭 계좌는 앞에서 '연금저축 계좌가 두 개예요'처럼 소개한 계좌다. 소개가 한 종류로 분명하지 않으면
        # 어느 계좌인지 모른다(되묻기). 별칭이 다르면 같은 종류여도 다른 계좌라 조합 비교의 '같은 계좌가 다시 나옴'이 아니다(_combos)
        alias = re.search(_ALIAS + r'$', clause)
        if alias and not names and not dest_unsure:
            intro = _alias_intro(q, x['s'])
            if intro:
                names = [intro]
            else:
                dest_unsure = True
        # 금액 바로 뒤에 계좌 이름이 오면('300만 원 IRP에 넣으면') 그 계좌다
        after = _ACCT_AFTER.match(q[x['e']:x['e'] + 26])
        # '연금저축 600 IRP 300이랑'처럼 금액 바로 앞에 제 계좌 이름이 있으면 뒤의 계좌 이름은 다음 금액 것이다
        own = re.search(r'(?:연금저축|IRP|개인형|DC|퇴직연금)\s*(?:계좌)?\s*(?:에|에는|은|는|이|가|으로|로)?\s*'
                        r'(?:(?:월|매월|매달|연간|연|1년에|올해|한\s*달에?)\s*)?(?:납입(?:액|금)?\s*)?$', clause, re.I)
        if after and not own:
            names, dest_unsure = [re.sub(r'\s+', '', after.group(1))], False
        elif old_q and _old_dest(wide):
            # (구)개인연금저축(2000.12.31 전 개설)에 넣는 돈은 연금저축계좌 납입이 아니다(R-15, 소득공제 체계) — 이름 속 '연금저축'으로
            # 연금저축 납입으로 읽어 개체 인식에 '납입 = 연금저축 300만 원'이 보였다(9차 검토 907). 따로 담고 세액공제 납입에서 뺀다
            p['old_contrib'].append(x['v'])
            continue
        acct = 'savings' if not names or names[-1] in ('연금저축', '연금계좌') else 'irp'
        # 블록에 적을 계좌 이름 — DC·퇴직연금에 본인이 넣는 돈을 'IRP'로 적으면 질문과 다른 말이 된다(합산 900만 원 한도는 같다)
        name = None if not names else 'DC' if re.match(r'DC|확정', names[-1], re.I) else \
            '퇴직연금' if names[-1].startswith('퇴직') else None
        # 회사·배우자가 넣는 돈은 질문한 사람의 세액공제 납입이 아니다 — '회사에서 매달 30만 원 DC에 넣어 주는데',
        # '아내가 매달 50만 원 연금저축에 넣으면 제 세액공제는?'(10-14 검토: 본인 공제 59만 4천·99만 원으로 계산했다).
        # 같은 마디에서 납입하는 사람이 남이면 납입액으로 쓰지 않는다(금액 없이 공제 규칙만)
        # 'DC에 회사에서 쌓아준 돈 외에 본인 부담으로 300만 원'의 회사는 넣는 사람이 아니고(6차 504), '회사에서 성과금 대신 300만 원
        # 넣어 준대요'의 회사는 넣는 사람이다(7차 600~609) — _payer_other 가 가른다
        if _payer_other(q, x):
            continue
        # '연금저축에 300만 원 넣었고 300만 원 더 넣으면' — 이미 넣은 돈에 더하는 금액(조합 비교가 아니라 누적, 늘어나는 공제를 따로 계산)
        more = bool(re.match(r'\s*(?:을|를|씩)?\s*' + _PERIOD_MID + _ACCT_MID + _ADV + r'(?:더|추가)', q[x['e']:x['e'] + 30])) or \
            bool(re.search(r'(?:더|추가로?|추가\s*납입(?:액|금)?)\s*(?:은|는|이|가|으로|로)?\s*$', q[max(0, x['s'] - 10):x['s']]))
        rec = {'v': v, 'acct': acct, 'monthly': x['period'] == 'monthly', 'raw': x['v'],
               's': x['s'], 'e': x['e'], 'more': more, 'name': name,
               'alias': re.sub(r'\s+', '', alias.group(0)) if alias else None}
        if dest_unsure:
            # 어느 계좌에 넣는지 모름 — 연금저축(600만 원 한도)·IRP(합산 900만 원)로 공제액이 갈려 숫자 없이 되묻는다(7차 610)
            p['acct_unsure'].append(x['v'])
            unsure_recs.append((rec, prior))
            continue
        p['contrib'].append(rec)
    # 넣는 계좌를 모르는 금액이 하나뿐이고 계좌를 아는 납입이 한 계좌에만 있으면, 그 계좌에 더 넣든 다른 계좌에 넣든 공제 대상이
    # 같을 때만 그 계좌로 계산한다 — '연금저축에 300만 원 넣었고 IRP는 없는데 300만 원 더'는 어느 쪽이든 공제 대상 600만 원이다.
    # 갈리면('연금저축에 600만 원 채웠고 IRP는 없는데 300만 원 더' — 연금저축이면 600만 원, IRP면 900만 원) 되묻고, 계좌를 아는
    # 납입의 공제는 deduction 이 블록에 남긴다(8차 705·708). 앞 마디 계좌가 납입으로 읽지 않은 계좌(회사가 넣는 DC)면 기댈 계좌가 없다
    if len(unsure_recs) == 1 and p['contrib']:
        rec, prior = unsure_recs[0]
        accts = {c['acct'] for c in p['contrib']}
        if len(accts) == 1 and {'savings' if _acct_id(n) == '연금저축' else 'irp' for n in prior} <= accts:
            a = next(iter(accts))
            s0 = sum(c['v'] for c in p['contrib'] if c['acct'] == 'savings')
            i0 = sum(c['v'] for c in p['contrib'] if c['acct'] == 'irp')
            if min(min(s0 + rec['v'], 600) + i0, 900) == min(min(s0, 600) + i0 + rec['v'], 900):
                rec.update(acct=a, name=p['contrib'][-1]['name'], assumed=True)
                p['contrib'] = sorted(p['contrib'] + [rec], key=lambda c: c['s'])
                p['acct_unsure'] = []

    # '퇴직급여 600만 원을 IRP에 넣으면' — 퇴직금 재원으로 읽힌 금액을 계좌에 넣는 말도 세액공제 블록에 까닭을 싣는다
    # (까닭이 없으면 모델이 600만 원 × 16.5%를 스스로 계산할 수 있다)
    for x in spans:
        if x['role'] == 'fund' and x['kind'] == 'retire' and _ACCT_AFTER.match(q[x['e']:x['e'] + 26]) and \
                re.search(_IN_VERB, re.split(r'[.?!\n]', q[x['e']:x['e'] + 30])[0]):
            p['retire_dropped'].append(x['v'])
    # 재원 구성(재원별 인출 계산용). 같은 재원 금액이 둘이면 어느 것인지 모르므로 쓰지 않는다
    p['fund'] = {}
    for kind in ('free', 'retire', 'credit'):
        vs = [x['v'] for x in spans if x['role'] == 'fund' and x['kind'] == kind]
        if len(vs) == 1:
            p['fund'][kind] = vs[0]
    p['fund_mentioned'] = {k for k, rx in _MENTION if re.search(rx, q)} | set(p['fund'])
    if 'retire' not in p['fund'] and (_RETIRE_NONE.search(q) or _retire_apart(q)):
        p['fund_mentioned'].discard('retire')
    # 'DC형에 3,400만 원 있는데 이직하면서 IRP로 받아서 깨면' — DC·DB·퇴직연금에서 IRP·연금계좌로 옮긴 돈은 퇴직급여(이연퇴직소득)다
    # (doc51: DC 퇴직금은 IRP 의무이전, doc21: 과세이연퇴직금은 연금외 수령 때 퇴직소득세). '퇴직금' 낱말이 없어 세액공제 받은 돈으로
    # 보고 16.5% 561만 원을 냈다(stab 2261). 퇴직금 재원 얘기로 두면 퇴직소득세를 되묻는 규칙 블록이 된다
    # 옮긴 곳 말고 연금저축이 따로 나오면('DB형을 IRP로 이전했어요. 연금저축도 따로 1,000만 원 … 연금저축만 해지') 해지하는 돈은
    # 그 연금저축일 수 있다 — 퇴직금 재원으로 보면 연금저축 해지를 퇴직소득세 100%라고 했다(10-15 검토). 그때는 전처럼 둔다
    pm = _PLAN_MOVED.search(q)
    p['plan_moved'] = 'retire' not in p['fund_mentioned'] and bool(pm) and not _RETIRE_NONE.search(q) \
        and not _retire_apart(q) and not re.search(r'연금\s*저축', q[:pm.start()] + ' ' + q[pm.end():])
    if p['plan_moved']:
        p['fund_mentioned'].add('retire')
    # 평가액과 재원 구성을 밝힌 계좌에서 기간 없이 '1,800만 원을 수령한다면'은 올해 꺼내는 금액이다(해마다 받는 연금액이 아니다).
    # 대화 기억이 '올해 1,800만 원 빼면'을 이렇게 바꿔 쓰면 재원별 인출(57만 6천 원) 대신 규칙과 되묻기로 빠졌다(10-12 시연 점검)
    if p['withdraw'] is None and p['balance'] is not None and p['fund'] and len(p['payout']) == 1:
        x = p['payout'][0]
        if x['period'] is None and x['v'] <= p['balance'] and not re.match(r'\s*씩', q[x['e']:]):
            x['role'] = 'withdraw'
            p['withdraw'], p['payout'] = x['v'], []
    # '이직하면서 퇴직금 3,000만 원이 IRP로 들어왔어요. 이거 해지하면 세금은?' — 꺼낼 금액 없이 '해지'만 말하면 계좌 전부를 꺼내는
    # 것이다(12 문서 H·결정 D-6, 발표 8장 예시: 금액을 알려 줘도 '해지하려는 금액'을 다시 물었다). 평가액이 있으면 평가액,
    # 없으면 밝힌 재원 금액의 합을 인출액으로 본다. '일부'·'중도인출'·'만 빼면'은 전부 해지가 아니다
    p['cancel_all'] = False
    # '다 해지하면'처럼 전부라고 말했으면 다른 문장의 '일부'('IRP는 일부만 못 뺀다며?')는 이 해지를 가리키지 않는다(stab 2227)
    # 그 말이 부정·망설임이거나('전부 해지하지 말고·다 해지 안 하고·다 깨는 건 싫고·다 해지할지') 같은 문장에 '일부'가 있으면 전부가
    # 아니다 — 일부 인출을 묻는데 평가액 전부의 해지 세금을 냈다(10-15 검토)
    whole = None
    for m in re.finditer(r'(?:다|전부|모두|전액|몽땅|통째로)\s*(?:' + _HAEJI + r'|해약|' + _BREAK + r')', q):
        a = max(q.rfind(c, 0, m.start()) for c in '.?!\n') + 1
        b = min([i for i in (q.find(c, m.end()) for c in '.?!\n') if i >= 0] or [len(q)])
        if re.match(r'\s*(?:하|해|할|한)?\s*(?:지\s*(?:말|않|마|못)|안\s*하|않|[가-힣]?\s*(?:건|것은|거는|게)\s*(?:싫|손해|아깝)'
                    r'|(?:하면|하는\s*건|하는\s*게)\s*(?:손해|불리|아깝)|[할하]?\s*지(?=\s|$)|[할하]?\s*까)', q[m.end():]) or \
                re.search(r'일부|부분|중도\s*인출|만\s*(?:빼|꺼내|찾|인출)', q[a:b]):
            continue
        # 전부 해지하겠다는 꼴('하면·하려고·하고 싶·할게·한다면·할 경우·시')일 때만 — 부정·망설임은 꼴이 끝없어('할 생각은 없어요·하긴
        # 싫어요·하기엔 아깝네요·했어요') 낱말 목록으로는 못 막는다. 모르는 꼴은 전부가 아닌 쪽(숫자 없음)으로 둔다(stab 재검증 R3)
        if not re.match(r'\s*(?:하|해)?\s*(?:면|려|고\s*싶|할\s*게|할\s*래|겠|버리면|버리려|는\s*경우|한다면|할\s*경우|할\s*때|시(?![작간]))',
                        q[m.end():]):
            continue
        whole = m
        break
    if p['withdraw'] is None and not p['payout'] and re.search(_HAEJI + r'|해약|' + _BREAK, q) and \
            (whole or not re.search(r'일부|부분|중도\s*인출|만\s*(?:빼|꺼내|찾|인출)', q)):
        # 공제 안 받은 돈만 밝혔으면 계좌 전체가 아니다 — 그 돈의 운용수익(③)이 따로 있어 그 합을 해지 금액으로 보면 세금 0원이 된다
        total = p['balance'] if p['balance'] is not None else \
            (sum(p['fund'].values()) if p['fund'] and set(p['fund']) != {'free'} else None)
        if total:
            p['withdraw'], p['cancel_all'] = total, True
    rt = [x['v'] for x in spans if x['role'] == 'rtax']
    p['rtax'] = rt[0] if len(rt) == 1 else None
    m = _EFF.search(q)
    p['retire_eff'] = float(m.group(1) or m.group(2)) if m else None
    m = _ACTUAL.search(q)
    p['actual_n'] = int(m.group(1) or m.group(2)) if m else None
    q_y = _ACTUAL.sub(' ', q)               # '실제 수령 12년차'는 연금수령연차가 아니다(doc40)

    # 연금수령연차 — '가입 5년차'·'근무 3년차'는 수령연차가 아니다
    m = re.search(r'(?:연금\s*)?(?:수령|개시)\s*(\d{1,2})\s*년\s*차|연금수령연차\s*(?:가|는|이)?\s*(\d{1,2})', q_y)
    p['year_explicit'] = bool(m)            # 수령·개시 연차라고 밝혔는가 — 맨 'N년차'는 가입 연차일 수 있다
    if m:
        p['year_n'] = int(m.group(1) or m.group(2))
    else:
        m = re.search(r'(\d{1,2})\s*년\s*차', q_y)
        if m and not re.search(r'가입|근무|입사|재직|납입|직장|회사|일한', q_y[max(0, m.start() - 8):m.start()]):
            p['year_n'] = int(m.group(1))
        else:
            p['year_n'] = None
    p['year_assumed'] = False
    old_acct = re.search(r'(?:19\d\d|200\d|201[0-2])\s*년|2013년\s*3월\s*(?:1일\s*)?이전', q)
    if p['year_n'] is None and re.search(r'(?:올해|이번\s*해|금년)\s*(?:에\s*)?처음|처음으로\s*(?:연금|개시|받)|첫\s*해', q):
        a = p['age']
        if not old_acct and (a is None or a == 55):
            p['year_n'], p['year_assumed'] = 1, True      # 전제로 밝힌다(올해가 처음 개시 가능한 해라면)
    if p['year_n'] is None and not old_acct and \
            re.search(r'(?:올해|이번에|이번\s*달|지난\s*달|최근)\s*퇴직|퇴직(?:하면서|하고서?|해서)\s*(?:받은\s*)?퇴직금', q):
        # 올해 퇴직금을 새 IRP로 옮긴 경우 — 퇴직금이 있으면 가입기간 요건이 없어(doc39) 55세 이상이면 올해가 1년차
        p['year_n'], p['year_assumed'] = 1, True
    p['retire_payout'] = bool(re.search(
        r'퇴직금\s*(?:만|을|를|으로|이)?\s*(?:넣어?\s*둔|받아\s*둔|들어\s*있|들어간|이체|옮긴|넣고|넣었|입금)'
        r'|퇴직금(?:을|를)?\s*연금으로|퇴직연금(?:에서|으로|을)|(?<![A-Za-z])D[CB]\s*(?:형)?\s*(?:에서|으로)', q)
        and not _retire_apart(q)) or any(x['src'] == 'retire' for x in p['payout'])
    p['lifetime'] = '종신' in q
    p['emigrate'] = bool(_EMIGRATE.search(q))
    # 영주권·장기체류만 말했으면 해외이주로 인정받을지 모른다 — 블록이 해외이주신고확인서를 먼저 묻는다(doc20, 9차 검토 908)
    p['emigrate_proof'] = bool(_EMIGRATE_WEAK.search(q)) and not _EMIGRATE_FIRM.search(q)
    p['unavoidable'] = bool(_UNAVOIDABLE.search(q)) or p['emigrate']
    p['early'] = _early(q)
    p['early_age'] = bool(_EARLY_AGE.search(q))
    p['cancel_age'] = _cancel_age(q)
    p['plan'] = _plan_kind(q)
    p['no_credit'] = bool(re.search(r'세액\s*공제\s*(?:안|못)\s*받|공제\s*받지\s*않은|공제\s*안\s*받', q))
    p['future'] = bool(re.search(r'나중에|은퇴\s*(?:후|하면)|되면|부터|이후에', q))
    p['public'] = bool(re.search(r'국민연금|공무원연금|사학연금|군인연금|기초연금|공적연금', q))
    p['insure'] = bool(re.search(dict(_SRC)['insure'], q))
    p['old'] = old_q
    p['private'] = bool(re.search(r'연금저축|IRP|개인형|연금계좌|사적연금', q, re.I))
    m = re.search(r'ISA[^.?!]{0,40}?(연금저축(?:펀드|계좌)?|IRP|개인형\s*IRP|연금계좌)\s*(?:으로|로|에)', q, re.I)
    p['isa_dest'] = None if not m else ('irp' if re.search(r'IRP|개인형', m.group(1), re.I)
                                        else 'savings' if '연금저축' in m.group(1) else None)
    p['no_irp'] = bool(re.search(r'IRP\s*(?:는|은)?\s*(?:따로\s*)?(?:없|안\s*했|가입\s*안)', q, re.I))
    if p['isa_dest'] is None:
        # 문장이 나뉘어도('…받았어요. 그 돈을 연금저축펀드에 넣었는데요') 계좌가 하나만 나오면 그쪽으로 본다
        has_s = '연금저축' in q
        has_i = bool(re.search(r'IRP|개인형', q, re.I)) and not p['no_irp']
        p['isa_dest'] = 'savings' if has_s and not has_i else 'irp' if has_i and not has_s else None
    # 퇴직금이 섞인 IRP에서 '올해 1,800만 원 연금으로 받으면'은 '빼면'과 같은 한 해 인출이다(같은 뜻 다른 표현 시험) —
    # 재원 구성을 말했을 때만 인출로 본다(연금저축 '연 1,200만 원 받으면'은 연금 수령 세금 블록이 맡는다)
    # '연 1,200만 원씩 받으면'(해마다 받는 연금)은 한 해 인출이 아니다(10-10 검토 2)
    if p['withdraw'] is None and len(p['payout']) == 1 and (p['fund'] or 'retire' in p['fund_mentioned']) and \
            p['balance'] is not None and p['payout'][0]['period'] is None and \
            not re.match(r'\s*씩', q[p['payout'][0]['e']:]) and not re.search(r'매년|해마다|씩', q):
        p['withdraw'] = p['payout'][0]['v']
    return p


_TAX_Q = re.compile(r'세금|세율|떼|원천징수|과세|세액(?!\s*공제)|종합과세|분리과세|내야|낼|나가')
# 연금소득 1,500만 원 기준을 넘는지 묻는 말
_OVER1500_Q = re.compile(r'1[,.]?500\s*(?:만\s*원?)?\s*(?:을|를|이|가|은|는)?\s*(?:넘|초과)')
# '과학기술인공제회'·'공제회'의 공제는 세액공제가 아니다(Q-099 오발동)
_DED_Q = re.compile(r'세액\s*공제|연말\s*정산|돌려\s*받|환급|(?<!인)공제(?!회)')
# 돈을 설명하는 지난 일 — '작년에 600 넣고 공제받았는데', '연말정산 때 공제는 매년 받았고요', '공제받은 돈'. 공제를 묻는 말이 아니다
_DED_PAST = re.compile(r'(?:연말\s*정산\s*(?:때|에|에서|으로|로)?\s*)?(?:세액\s*)?공제\s*(?:는|를|도|까지)?\s*'
                       r'(?:(?:매년|해마다|다|모두|전부|이미|꼬박꼬박|꾸준히)\s*)?(?:안\s*|못\s*)?받(?:았|은|던|고(?!\s*싶))')


# ---------------------------------------------------------------------------
# 표기
# ---------------------------------------------------------------------------
def won(man):
    """만원 단위 값 → '297만 원', '82만 5천 원', '1,234만 5,600원'."""
    w = int(round(man * 10000))
    eok, rest = divmod(w, 100_000_000)
    m, r = divmod(rest, 10_000)
    parts = []
    if eok:
        parts.append(f'{eok:,}억')
    if m:
        parts.append(f'{m:,}만')
    if r:
        if r % 1000 == 0:
            parts.append(f'{r // 1000}천')
        else:
            return (' '.join(parts) + f' {r:,}원').strip()
    return (' '.join(parts) + ' 원').strip() if parts else '0원'


def pct(x):
    return f'{x:g}%'


# ---------------------------------------------------------------------------
# 계산
# ---------------------------------------------------------------------------
def _block(file, title, lines, keys, numbers=True, key_figure=None, yearly=None, needs=None, assume=None,
           figures=None, alts=None):
    """계산 블록. needs = 계산에 빠진 정보(되묻기용), assume = 대신 채운 값(답변의 '가정'),
    figures = 답에 나와야 할 계산값들(숫자 대조용), alts = 참고로 함께 실은 '고객 조건이 아닌' 값(다른 나이 구간 세액 —
    핵심 금액 없이 이 값만 쓴 답은 숫자 대조가 어긋남으로 본다)."""
    quotes = [rule(k) for k in keys]
    rids = rule_ids(keys)
    tag = f' {"·".join(rids)}' if rids else ''
    head = (f'[세금 계산(규칙{tag}) — 아래 문서 원문의 규칙으로 계산한 값]' if numbers
            else f'[세금 규칙{tag} — 조건이 갈려 금액은 계산하지 않음. 아래 문서 원문의 규칙]')
    body = list(lines)
    if needs:
        body.append('계산에 필요한데 질문에 없는 정보: ' + ' · '.join(needs))
    if assume:
        body.append('가정(질문에 없어 대신 채운 값): ' + ' · '.join(assume))
    text = head + '\n' + '\n'.join(f'- {x}' for x in body) + '\n[원문]\n' + '\n'.join(quotes)
    return {'file': file, 'topic': title, 'text': text, 'rules': keys, 'rids': rids, 'numbers': numbers,
            'key_figure': key_figure, 'yearly': yearly, 'needs': list(needs or []), 'assume': list(assume or []),
            'figures': list(figures or ([key_figure] if key_figure else [])), 'alt_figures': list(alts or [])}


# '16.5%가 무조건 이득이냐'처럼 분리과세·종합과세 선택을 묻는 말 — 이때는 '늘 유리하지 않다'(doc38) 규칙도 싣는다
_CHOICE_Q = re.compile(r'이득|유리|불리|무조건|나아|나을|낫|손해|선택|고르')
_NOT_ALWAYS = ('16.5% 분리과세가 늘 유리한 것은 아니다 — 다른 소득과 합쳐 계산한 종합과세 세율이 16.5%를 넘지 않으면 '
               '16.5% 분리과세가 오히려 불리할 수 있다')
_OVER_1500 = ('세액공제 받은 납입금·운용수익을 연 1,500만 원 넘게 연금수령하면 초과분이 아니라 전액이 종합과세'
              '(다른 소득과 합산해 6.6~49.5% 누진세율) 또는 16.5% 분리과세 대상')


def _payout_rule_only(p, why, extra_keys=(), q='', needs=None):
    lines = [why, '연금소득세(나이별, 지방소득세 포함): 55세 이상 70세 미만 5.5%, 70세 이상 80세 미만 4.4%, 80세 이상 3.3%',
             _OVER_1500,
             '1,500만 원 판단은 전 금융기관 연금계좌 합산이고, 세액공제 안 받은 돈과 퇴직금은 들어가지 않는다']
    keys = ['rate_table', 'over_1500', 'whole_amount', 'progressive', 'excluded', 'all_accounts'] + list(extra_keys)
    if _CHOICE_Q.search(q):
        lines.append(_NOT_ALWAYS)
        keys.append('not_always')
    return _block('doc38.txt', '연금 수령 세금(규칙)', lines, keys, numbers=False, needs=needs or [])


# 계좌에 돈이 있다는 말 — 쓰임을 못 읽은 금액이 이 말로 끝나는 문장에 있으면 평가액일 수 있다
_HAVE_TAIL = re.compile(r'있(?:어|고|는데|으며|습니다|음|다)|들어\s*있|모였|쌓였')


def _limit_unsure(p, q, yearly):
    """연 수령액이 연금수령한도 안이라는 전제를 세울 수 없으면 True. 평가액 얘기가 없으면 늘 쓰던 전제(한도 안에서 받는 경우)를 둔다.
    평가액을 하나로 읽었으면 연차로 계산한 한도(연차를 모르면 가장 작은 1년차 한도 = 평가액 × 12%) 안일 때만 전제가 선다.
    stab 2274: '제 IRP에 … 4천, 아내 연금저축에 2천5백 있어요. 각자 1년에 1,800씩'에 '한도 안' 전제로 297만 원을 냈다 — 2,500만 원
    계좌는 58세에 어느 연차로도 한도가 1,800만 원에 못 미친다(doc39 한도 = 평가액 ÷ (11 − 연차) × 120%)."""
    n = p['year_n']
    if n and n >= 11:
        return False                    # 11년차부터 한도 없음
    bals = [x for x in p['spans'] if x['role'] == 'balance']
    loose = [x for x in p['spans'] if x['role'] is None and x['src'] in ('private', 'person', None)
             and _HAVE_TAIL.search(re.split(r'[.?!\n]', q[x['e']:])[0])]
    if not bals and not loose:
        return False
    if len(bals) == 1 and not loose and bals[0]['src'] != 'person':
        lim = bals[0]['v'] / (11 - n) * 1.2 if n else bals[0]['v'] * 0.12
        return yearly > lim + 1e-6
    return True                         # 평가액이 여럿·남의 계좌·못 읽음 — 한도 안인지 모른다


_PERIOD_NUM = re.compile(r'(?:연간?|(?<![\d개])월|매달|매월|1년에|한\s*달에?|매년)\s*(?:약\s*)?(\d[\d,]*)'
                         r'(?![\d,.]*\s*(?:%|회|번|년|개월|세|살|일|시))')


def _period_num_unread(p, q):
    """기간 말(연·월·매달…) 바로 뒤 숫자 가운데 금액으로 읽지 못한 것이 있는가. 남의 수령액('남편은 IRP에서 1년에 1,300')과
    같은 돈을 달리 말한 것('월 100, 1년에 1,200')은 일부러 읽지 않으므로 빼고 본다."""
    taken = [(x['s'], x['e']) for x in p['spans']]
    pays = [x['v'] for x in p['payout']]
    for m in _PERIOD_NUM.finditer(q or ''):
        s = m.start(1)
        if any(a <= s < b for a, b in taken):
            continue
        if _OTHER_PERSON.search(re.split(r'[.?!\n,]', q[max(0, s - 20):s])[-1]):
            continue
        v = float(m.group(1).replace(',', ''))
        if any(abs(v - y) < 1e-6 or abs(v - y * 12) < 1e-6 or abs(v * 12 - y) < 1e-6 for y in pays):
            continue
        return True
    return False


# 두 사람(본인과 배우자 등) 각자의 몫을 묻는 말 — 계산기는 한 사람 몫만 낸다. 본인도 주어로 나와야 한다
# ('저희 아버지가 연금저축이랑 IRP에서 각각 받으시는데'의 각각은 계좌 둘이다)
_SELF = re.compile(r'(?<![가-힣])(?:저는|제가|저도|저랑|저하고|저와|나는|내가|나도)(?![가-힣])|(?<![가-힣])저\s+둘'
                   r'|(?:저희|우리)\s*(?:둘|부부|맞벌이)|부부')
# '각각'은 계좌 둘을 가리키기 쉽다('연금저축이랑 IRP에 각각 300씩', '남편은 연금저축 각각 하나씩') — 세금·공제를 묻는 말에 붙을 때만
_EACH_Q = re.compile(r'각자|따로따로|두\s*사람|(?:세금|공제|세액)\s*(?:은|는|이|가|도)?\s*각각|각각\s*(?:의\s*)?(?:얼마|세금|공제|세액)')


def _each_two(p, q):
    return bool(_EACH_Q.search(q) and _OTHER_PERSON.search(q) and _SELF.search(q))


# 퇴직금을 '그 1,500만 원에 들어가나요?'처럼 따로 묻는 말 — 수령액이 퇴직금에서 나온다는 말이 아니다(Q-013 같은 질문)
_RETIRE_ASK = re.compile(r'퇴직\s*(?:금|급여)[^.?!\n]{0,20}?(?:도|은|는|까지)\s*[^.?!\n]{0,25}?'
                         r'(?:1[,.]?500|포함|들어가|들어\s*가|합산|해당|빠지|빠져|제외)')
# 퇴직금이 계좌에 있다는 말 — '퇴직금도 IRP에 있는데', '퇴직금 1억 IRP로 받았고'
_RETIRE_HELD = re.compile(r'퇴직\s*(?:금|급여)[^.?!\n]{0,15}?(?:IRP|개인형|연금\s*계좌|계좌|연금저축)\s*(?:에|로|으로|에서|에는)', re.I)
# '퇴직금 아니고 내가 넣은 돈이야' — 퇴직금이 아니라 본인 돈이라는 말(stab 2223: 이 말을 놓쳐 잔액 3천을 퇴직금 재원으로 적었다).
# 본인 돈이라는 말이 뒤따를 때만 — '퇴직금이 아니라 회사 DC에서 옮긴 돈'은 퇴직급여(이연퇴직소득)이고, '퇴직금이 없는 줄 알았는데
# 2천만 원 들어 있더라고요'는 퇴직금이 있다는 말이다('이'를 받자 둘 다 퇴직금 없음으로 읽어 16.5%로 계산했다)
_RETIRE_NONE = re.compile(r'퇴직금\s*(?:은|는)?\s*(?:없|안\s*받|일시금으로\s*받았|다\s*썼)'
                          r'|퇴직금\s*(?:은|는|이)?\s*아니(?:고|라|에요|예요|야)?\s*,?\s*'
                          r'(?:(?:제가|내가|본인이?|직접|개인적으로)\s*(?:[가-힣]+\s*){0,2}?(?:넣은|부은|납입한|모은)'
                          r'|(?<![가-힣])(?:제|내)\s*돈)')
# 퇴직금이 묻는 계좌(연금저축·IRP)가 아니라 회사 DC·퇴직연금에 따로 있다는 말 — 이 계좌의 재원이 아니다
# (10-14 검토: '퇴직금은 회사 DC에 따로 있어요. 연금저축에서 1,200만 원 받으면'에 '퇴직금 1억 원'·'가입기간 요건 없음'을 지어냈다).
# 그 퇴직금을 IRP·연금저축으로 옮긴다는 말이 있으면 쓰지 않는다
_RETIRE_APART = re.compile(r'퇴직\s*(?:금|급여)\s*(?:은|는)\s*(?:아직\s*)?(?:회사\s*)?(?:DC|DB|퇴직\s*연금|회사)(?:\s*(?:형|계좌))?'
                           r'\s*(?:에|에서)\s*(?:는\s*)?(?:따로\s*|별도로?\s*|그대로\s*|아직\s*)?(?:있|남아|두|넣어|쌓|운용)', re.I)
_RETIRE_MOVE = re.compile(r'(?:IRP|개인형|연금\s*저축|연금\s*계좌)\s*(?:으로|로)\s*(?:옮|이전|이체|받)', re.I)


def _retire_apart(q):
    return bool(_RETIRE_APART.search(q)) and not _RETIRE_MOVE.search(q)


def _payout_retire(p, q):
    """퇴직금이 수령액의 재원일 수 있는 연금 수령 — 금액 없이 퇴직금 규칙과 ③ 재원(1,500만 원) 규칙을 함께."""
    lines = ['퇴직금 재원을 한도 안에서 연금으로 받으면 원래 퇴직소득세의 70%(실제 수령 10년차 이하)·60%(11~20년차)·'
             '50%(21년차~)만 낸다. 한도를 넘긴 퇴직금은 퇴직소득세 100%',
             '퇴직금 재원은 1,500만 원 판단에 들어가지 않는다 — 세액이 퇴직소득세액에 달려 있어 여기서 금액을 계산하지 않음',
             '계좌에 세액공제 받은 돈·수익도 있으면 퇴직금이 먼저 빠지고(인출 순서) 그 뒤 ③ 재원은 나이별 연금소득세 '
             '5.5%(55세 이상 70세 미만)·4.4%(70세 이상 80세 미만)·3.3%(80세 이상)',
             '③ 재원(세액공제 받은 납입금·운용수익) 수령액이 연 1,500만 원을 넘으면 초과분이 아니라 전액이 종합과세'
             '(6.6~49.5% 누진세율) 또는 16.5% 분리과세 대상 — 1,500만 원은 전 금융기관 연금계좌를 합산해 판단']
    keys = ['retire_rate', 'excluded', 'rate_table', 'order', 'over_1500', 'whole_amount', 'progressive', 'all_accounts']
    if _CHOICE_Q.search(q):
        lines.append(_NOT_ALWAYS)
        keys.append('not_always')
    # 빠진 정보는 질문에 없는 것만 — 고정 목록이라 이미 말한 퇴직소득세·퇴직금·연차를 다시 물었다(stab 2247·2256·2262·2270)
    needs = []
    if p.get('rtax') is None and p.get('retire_eff') is None:
        needs.append('퇴직소득세(원천징수영수증의 퇴직소득세 또는 실효세율)')
    # '퇴직금 3억 받아서 IRP로', '퇴직금 7천만원 받으셨어요' — 기간 없는 퇴직 쪽 수령액은 받은 퇴직금 금액이다
    retire_amt = (p.get('fund') or {}).get('retire') or any(x['src'] == 'retire' and x['period'] is None for x in p['payout'])
    if p.get('balance') is None and not retire_amt:
        needs.append('연금계좌 평가액과 그중 퇴직금 금액')
    if not p.get('year_n'):
        needs.append('연금수령연차')
    return _block('doc38.txt', '퇴직금 재원 연금 세금(규칙)', lines, keys, numbers=False, needs=needs)


_BANDS = [(5.5, '55세 이상 70세 미만'), (4.4, '70세 이상 80세 미만'), (3.3, '80세 이상')]
# 수령액 여럿이 합산이 아니라 고를 방식들이라는 말
_ALT_Q = re.compile(r'거랑|것과|이랑\s*.{0,12}(?:중|차이|비교)|아니면|vs|VS|비교|차이|중\s*(?:뭐|어느|어떤)|어느\s*(?:쪽|게|것)')
# 1,500만 원 판단은 전 금융기관 연금계좌 합산이다(doc38) — '합쳐서'·'같이 받으면'은 비교가 아니라 합산
_SUM_Q = re.compile(r'합쳐|합치|합산|같이|함께|둘\s*다|동시에|더하면|각각\s*받')
# 계좌가 둘(연금저축·IRP)이면 둘 다 받는 게 보통이다 — '거랑'·'차이'만으로는 비교로 보지 않는다
_ALT_STRONG = re.compile(r'아니면|vs|VS|중\s*(?:에\s*)?(?:뭐|어느|어떤)|어느\s*(?:쪽|게|것)|비교')


def _yearly(x):
    return x['v'] * 12 if x['period'] == 'monthly' else x['v']


def _age_unclear(p):
    """세율 구간을 정하지 못한 까닭 — 받는 나이가 지금인지 '○세에'인지 엇갈리면 그렇게 밝힌다(답이 고객 나이로 하나를 고르지 않게)."""
    if p.get('rate_age_unsure'):
        return '받는 나이(지금인지, 질문에 나온 나이인지)가 분명하지 않아'
    return '나이가 질문에 분명하지 않아'


def _payout_alternatives(p, q, mine):
    """고를 수령액 여럿을 각각 계산 — 합산하지 않는다. 연 표시는 하나만 있어도 모두 연으로 본다('연 1,500씩 … 2,000씩')."""
    ra = rate_age(p)
    band = rate_for_age(ra)
    lines, figs, keys = [], [], ['rate_table', 'over_1500', 'whole_amount', 'progressive', 'excluded', 'all_accounts']
    if band:
        # 세율을 정한 나이(받는 나이를 따로 말했으면 그 나이)를 적는다 — 고객 나이를 적으면 '60세 → 4.4%'처럼 어긋난다
        age_txt = f'{ra[1]}대' if isinstance(ra, tuple) else f'{ra}세'
        lines.append(f'나이 {age_txt} → 연금소득세율 {pct(band[0])} ({band[1]}, 지방소득세 포함)')
    else:
        lines.append(f'{_age_unclear(p)} 세율 구간을 정하지 않음 (55~69세 5.5%, 70~79세 4.4%, 80세 이상 3.3%)')
    for x, lab in dict.fromkeys((_yearly(x), (f'월 {won(x["v"])}(연 {won(_yearly(x))})' if x['period'] == 'monthly'
                                             else f'연 {won(x["v"])}')) for x in mine):
        if x > 1500:
            t = won(x * 0.165)
            figs.append(t)
            lines.append(f'{lab} 받으면: 1,500만 원 초과 → 초과분이 아니라 전액({won(x)})이 대상 — 16.5% 분리과세를 고르면 '
                         f'{won(x)} × 16.5% = {t}, 종합과세를 고르면 다른 소득과 합산해 6.6~49.5%')
        elif band:
            t = won(x * band[0] / 100)
            figs.append(t)
            lines.append(f'{lab} 받으면: 1,500만 원 이하 → 전액 {pct(band[0])} 분리과세 {won(x)} × {pct(band[0])} = {t}')
        else:
            alt = [won(x * r / 100) for r, _ in _BANDS]
            figs += alt
            lines.append(f'{lab} 받으면: 1,500만 원 이하 → 나이별 분리과세 '
                         + ' · '.join(f'{name} {pct(r)} → {a}' for (r, name), a in zip(_BANDS, alt)))
    if any(_yearly(x) > 1500 for x in mine):
        lines.append(_NOT_ALWAYS)
        keys.append('not_always')
    lines.append('1,500만 원 판단은 전 금융기관 연금계좌 합산이고, 세액공제 안 받은 돈과 퇴직금은 들어가지 않는다. '
                 '전제: 세액공제 받은 납입금·운용수익 재원을 55세 이후 연금수령한도 안에서 받는 경우')
    return _block('doc38.txt', '연금 수령 세금(방식 비교)', lines, keys, figures=list(dict.fromkeys(figs)))


def payout(p, q):
    """연금 수령 세금. 입력이 하나로 분명할 때만 숫자, 아니면 규칙만, 계좌 종류가 없으면 None."""
    pays = p['payout']
    if not pays or not p['private']:
        return None                                  # 계좌 종류가 없으면 국민연금일 수도 있다
    # 보험 연금(변액연금·즉시연금·연금보험)은 연금계좌 연금소득세로 계산하지 않는다. 다만 보험 연금 수령액과 연금저축·IRP 수령액을
    # 함께 말했으면 아래 '다른 연금이 함께 있음' 규칙 블록으로 간다 — 10-14 2차 검토: '변액연금 연 1,000만 원 받는데 연금저축도
    # 연 600만 원 받아요'에 블록이 없어져 이미 말한 두 금액을 다시 물었다(HEAD·고치기 전에는 규칙 블록)
    if p['insure'] and not (any(x['src'] == 'insure' for x in pays) and any(x['src'] == 'private' for x in pays)):
        return None
    if _late_cancel(p) and not _NOT_CANCEL.search(q):
        return late_cancel_rule(p, q)                # 55세 이후 해지 — 개시 여부·한도로 갈린다(9차 검토 901)
    if _early_eff(p):
        lines = ['55세 전 인출이나 해지는 연금수령이 아니라 연금외수령이다 — 세액공제 받은 납입금·운용수익은 16.5% 기타소득세'
                 '(1,500만 원 판단·종합과세 선택이 없다), 세액공제 안 받은 납입금은 비과세',
                 '부득이한 사유(사망·해외이주·요양 등)면 예외가 있다']
        return _block('doc39.txt', '55세 전·해지 인출 세금(규칙)', lines,
                      ['pension_req', 'over_limit'], numbers=False)
    retire_word = bool(re.search(r'퇴직금|퇴직\s*급여', q)) and not _RETIRE_NONE.search(q) and not _retire_apart(q)
    # 퇴직금을 따로 묻기만 하는 말(수령액이 퇴직금에서 나온다는 말이 아님) — 수령 세금은 계산하고 퇴직금 규칙을 함께 싣는다
    retire_side = retire_word and not p['retire_payout'] and bool(_RETIRE_ASK.search(q)) and not _RETIRE_HELD.search(q)
    if p['retire_payout'] or (retire_word and not retire_side):
        # '퇴직금을 IRP에 넣어 뒀는데 연 1,800만 원' — 퇴직금이 나오면 그 수령액을 ③ 재원으로 계산하면 안 된다
        # (검토: 297만·330만 원을 세액공제 재원 기준으로 잘못 냈다). 퇴직소득세를 알아야 금액이 나온다.
        return _payout_retire(p, q)
    if p['lifetime']:
        # 종신형 세율은 문서(doc38 표: 모든 나이 3.3%)와 다른 안내(4.4%, 80세 이상 3.3%)가 엇갈린다 — 숫자를 정하지 않는다
        return _payout_rule_only(p, '종신연금형 세율은 확인이 필요하다 — 받은 문서(doc38) 표는 종신연금 수령 시 3.3%로 적지만 '
                                    '다른 안내와 엇갈려 여기서 정하지 않는다. 가입한 상품의 약관·상담으로 확인할 것', q=q)
    if p['no_credit']:
        return _payout_rule_only(p, '세액공제를 받지 않은 납입금은 인출할 때 과세되지 않고 1,500만 원 판단에도 들어가지 않는다', q=q)
    others = [x for x in pays if x['src'] in ('public', 'earned', 'insure', 'retire')]
    person = [x for x in pays if x['src'] == 'person']
    mine = [x for x in pays if x not in others and x not in person]
    if person and not mine and not others:
        mine, person = person, []       # '81세 아버지가 연금저축에서 연 1,000만원' — 질문 전체가 그 사람 얘기다
    if others or person or p['public']:
        return _payout_rule_only(p, '질문에 연금저축·IRP 외의 연금이나 소득이 함께 있어 금액을 계산하지 않음 '
                                    '(공적연금은 1,500만 원 판단에서 빠진다)', q=q)
    periods = [x['period'] for x in mine]
    two_accts = bool(re.search(r'연금저축', q)) and bool(re.search(r'IRP|개인형', q, re.I))
    # 더하는 말은 수령액들을 묶는 자리일 때만 — '연금저축이랑 IRP 둘 다 있어요. …받는 거랑 …받는 거 중 어느 쪽'의 '둘 다'는 가진 계좌다
    # (10-14 4차 검토 302와 같은 원인: 고르는 두 수령액을 더해 462만 원 — 맞는 값은 안마다 55만·297만 원)
    alt = False if _sum_binds(_SUM_Q, q, mine) else bool(_ALT_STRONG.search(q)) if two_accts else bool(_ALT_Q.search(q))
    if len(mine) >= 2 and alt and any(periods) and not ('monthly' in periods and None in periods):
        if None in periods:              # '연 1,500씩 … 2,000씩' — 연 표시가 하나만 있어도 모두 연으로 본다
            mine = [dict(x, period=x['period'] or 'yearly') for x in mine]
        # '연 1,500씩 받는 거랑 2,000씩 받는 거' — 합산이 아니라 두 방식의 비교다(C16 대화). 각각 따로 계산한다
        return _payout_alternatives(p, q, mine)
    if any(x['period'] is None for x in mine):
        return _payout_rule_only(p, '질문에 연/월 표시가 없어 연간 수령액인지 알 수 없음 — 한 번에 인출하는 경우라면 '
                                    '연금수령한도를 넘는 부분은 연금외수령(16.5% 기타소득세)', q=q)
    if len(mine) > 1 and not all(x['src'] == 'private' for x in mine):
        return _payout_rule_only(p, '수령액이 여럿이라 어느 계좌 것인지 분명하지 않아 금액을 계산하지 않음', q=q)
    yearly = sum(x['v'] * (12 if x['period'] == 'monthly' else 1) for x in mine)
    if _period_num_unread(p, q):
        # '연금저축이랑 IRP에서 연 1,000, 연 700 받으면' — 기간 말 뒤 수령액 하나를 못 읽었으면 합계(1,500만 원 판단)가 틀린다.
        # 읽은 700만으로 '1,500만 원 이하 → 5.5%'라고 단정했다 — 숫자 없이 규칙만
        return _payout_rule_only(p, '질문의 수령액 가운데 읽지 못한 금액이 있어 연간 합계를 정하지 않음 — 금액을 계산하지 않음', q=q,
                                 needs=['연금계좌별 연간 수령액(전 금융기관 합산)'])
    if _limit_unsure(p, q, yearly):
        # 평가액을 말했는데 한도 안인지 모르면 '한도 안' 전제를 붙여 숫자를 내지 않는다 — 한도를 넘는 몫은 16.5%라 결과가 갈린다
        return _payout_rule_only(p, f'연 {won(yearly)}이 연금수령한도 안인지 질문만으로는 알 수 없어 금액을 계산하지 않음 — '
                                    '연금수령한도 = 평가액 ÷ (11 − 연금수령연차) × 120%(11년차부터 한도 없음), 한도를 넘는 금액은 '
                                    '연금외수령이라 세액공제 받은 돈·수익은 기타소득세 16.5%',
                                 ['limit_formula', 'over_limit'], q=q,
                                 needs=['계좌별 평가액(올해 1월 1일 또는 개시일 기준)과 연금수령연차 — 연금수령한도 계산에 필요'])
    lines = []
    if len(mine) > 1:
        lines.append('입력: ' + ' + '.join((f'월 {won(x["v"])} × 12' if x['period'] == 'monthly' else f'연 {won(x["v"])}')
                                          for x in mine) + f' = 연 {won(yearly)} (연금계좌 합산)')
    elif mine[0]['period'] == 'monthly':
        lines.append(f'입력: 월 {won(mine[0]["v"])} × 12 = 연 {won(yearly)}')
    else:
        lines.append(f'입력: 연금 수령액 연 {won(yearly)}')
    band = rate_for_age(rate_age(p))
    r = band[0] if band else None
    others_b = [(x, name) for x, name in _BANDS if not band or name != band[1]]
    if band:
        ra = rate_age(p)
        age_txt = f'{ra[1]}대' if isinstance(ra, tuple) else f'{ra}세'
        lines.append(f'나이 {age_txt} → 연금소득세율 {pct(r)} ({band[1]}, 지방소득세 포함)'
                     + (f' — 지금 {p["age"]}세지만 받는 나이({ra}세) 기준(연금소득세율은 연금수령일 현재 나이로 정함)'
                        if p.get('rate_age') and p.get('age') and p['age'] != ra else ''))
        # 고객 구간 하나만 보이면 답이 좁아진다 — 다른 나이 구간도 싣는다(세율은 연금수령일 현재 나이 기준)
        # '고객은 해당 없음'을 밝힌다 — 67세 질문에 답이 '70세 이상 80세 미만(고객 해당) 4.4%'로 옮겨 적은 일이 있다(C02 대화)
        lines.append(f'다른 나이 구간(고객 {age_txt}는 해당 없음): ' + ' · '.join(f'{name} {pct(x)}' for x, name in others_b)
                     + ' (연금수령일 현재 나이 기준 — 나이가 들수록 세율이 낮아진다)')
    elif yearly > 1500:
        lines.append(f'{_age_unclear(p)} 세율 구간을 정하지 않음 (55~69세 5.5%, 70~79세 4.4%, 80세 이상 3.3%)')
    key = None
    figs, alts = [], []
    if yearly > 1500:
        key = won(yearly * 0.165)
        figs.append(key)
        lines.append(f'연 {won(yearly)}은 1,500만 원 초과 → **초과분이 아니라 전액({won(yearly)})**이 대상이다')
        lines.append(f'  ① 16.5% 분리과세를 고르면 {won(yearly)} × 16.5% = {key}')
        lines.append('  ② 종합과세를 고르면 다른 종합소득과 합산해 6.6~49.5% 누진세율 (세액은 다른 소득에 따라 달라 여기서 계산하지 않음)')
        lines.append('  ' + _NOT_ALWAYS)
        lines.append('  틀린 계산 예: "1,500만 원까지 저율, 초과분만 16.5%" — 문서는 전체금액에 16.5%라고 적고 있다')
        if r:
            lines.append(f'  참고: 연 1,500만 원 이하로 받으면 전액 {pct(r)} 분리과세 (1,500만 원이면 {won(1500 * r / 100)})')
    elif r:
        key = won(yearly * r / 100)
        figs.append(key)
        lines.append(f'연 {won(yearly)}은 1,500만 원 이하 → 전액 {pct(r)} 분리과세(다른 소득과 합산하지 않음): '
                     f'{won(yearly)} × {pct(r)} = {key}')
        alt = [won(yearly * x / 100) for x, _ in others_b]
        alts += alt
        lines.append(f'같은 연 {won(yearly)}을 다른 나이 구간에 받으면: '
                     + ' · '.join(f'{name} {pct(x)} → {a}' for (x, name), a in zip(others_b, alt)))
    else:
        alt = [won(yearly * x / 100) for x, _ in _BANDS]
        figs += alt
        lines.append(f'연 {won(yearly)}은 1,500만 원 이하 → 나이별 연금소득세율로 분리과세(다른 소득과 합산하지 않음). '
                     f'{_age_unclear(p)} 구간별로: '
                     + ' · '.join(f'{name} {pct(x)} → {a}' for (x, name), a in zip(_BANDS, alt)))
    lines.append('전제: 세액공제 받은 납입금·운용수익 재원을 55세 이후 연금수령한도 안에서 받는 경우, 전 금융기관 연금계좌 합산 기준. '
                 '세액공제 안 받은 납입금과 퇴직금 재원은 1,500만 원 판단에 들어가지 않는다(재원이 다르면 결과가 달라짐)')
    keys = ['rate_table', 'over_1500', 'whole_amount', 'progressive', 'excluded', 'all_accounts']
    if retire_side:
        # '그리고 퇴직금 받은 것도 그 1,500만 원에 들어가나요?' — 두 번째 하위 질문의 규칙도 함께 싣는다
        lines.append(f'퇴직금(이연퇴직소득)은 1,500만 원 판단에 들어가지 않는다 — 수령액 연 {won(yearly)}에 퇴직금 재원이 섞여 있으면 '
                     '그 부분은 빼고 판단하고, 퇴직금 재원은 퇴직소득세의 70%(실제 수령 10년차 이하)·60%(11~20년차)·'
                     f'50%(21년차~)로 따로 과세된다. 위 계산은 연 {won(yearly)} 전부가 세액공제 받은 납입금·운용수익일 때다')
        keys.append('retire_rate')
    elif re.search(r'퇴직금|퇴직급여', q):
        lines.append('질문에 퇴직금이 나온다 — 퇴직금 재원은 1,500만 원 판단에서 빠지고 이연퇴직소득세 기준으로 따로 과세된다')
    if _each_two(p, q):
        # '남편은 … 1,300, 저는 … 900 … 각자 세금' — 계산기는 한 사람 몫만 낸다. 누구 몫인지 밝히지 않으면 두 사람 답처럼 읽힌다(stab 2274)
        lines.append(f'질문이 두 사람 각자의 세금을 묻는다 — 위 계산은 연 {won(yearly)}을 받는 한 사람 몫이고, 다른 사람 몫은 그 사람의 '
                     '수령액·나이로 따로 계산해야 한다')
    if yearly > 1500:
        keys.append('not_always')
    return _block('doc38.txt', '연금 수령 세금', lines, keys, key_figure=key, yearly=yearly, figures=figs, alts=alts)


# 어느 쪽이 나은지 묻는 말 — 이때는 계산 블록이 어느 쪽이든 '비교만 하고 권하지 마라'를 붙인다(calc_policy)
_COMPARE_Q = re.compile(r'나아|나을|낫|좋아요|좋을까|좋은가|좋은지|유리|불리|어디에|어디로|어느\s*(?:쪽|게|것|계좌)|뭐가\s*좋|최적|추천')


def _acct_choice(p, q):
    """한 금액을 연금저축과 IRP 중 어디에 넣을지 묻는 질문인가."""
    return (len(p['contrib']) == 1 and '연금저축' in q and bool(re.search(r'IRP|개인형', q, re.I))
            and bool(re.search(r'어디에|어느\s*(?:쪽|계좌|게)|중에?\s*(?:뭐|어디|어느)|나아|나을|좋아|유리', q)))


# 고르는 이음말 — 두 금액(두 넣는 일) 사이에 오면 하나를 고르는 안이다. '아니면·또는·vs·대신'에 더해 '넣거나·넣든지·넣을지'
# 같은 고르는 어미도(10-14 3차 검토 204: 이음말을 몇 개로만 열거해 '넣거나·넣을지·넣든지'를 둘 다 넣는 것으로 더했다)
_RIEUL = ''.join(chr(0xAC00 + i) for i in range(11172) if i % 28 == 8)        # 받침 ㄹ 글자(넣을·할·갈 …) — '-ㄹ지'
_ALT_JOIN = re.compile(r'아니면|또는|혹은|(?<![A-Za-z])vs(?![A-Za-z])|대신|거나|든지|든가|[' + _RIEUL + r']지(?:\s|$)', re.I)
_ALT_BETWEEN = _ALT_JOIN
_ALT_AFTER = re.compile(r'\s*(?:을|를)?\s*(?:넣는\s*(?:것|거|게)\s*)?(?:둘\s*)?중(?:에서|에)?(?![가-힣])')
# 조합 비교를 켜는 말. '중에'는 금액·계좌·'거' 바로 뒤일 때만 — '올해 중에'는 고르는 말이 아니다(10-14 검토)
_COMBO_Q = re.compile(r'비교|vs|VS|아니면|각각|이랑\s*.{0,20}(?:중|어느)|중\s*(?:뭐|어느|어떤)|(?:원|\d|IRP|저축|거|것|둘)\s*중(?:에서|에)?(?![가-힣])'
                      r'|것과|거랑|거하고|두\s*(?:경우|개|가지)|어느\s*쪽|어떤\s*게\s*(?:더|나)|뭐가\s*(?:더|나)|차이')
# 더하는 말 — '둘 다 하면', '합치면', '모두', '같이 하면'. 이 말이 있으면 넣는 안을 고르는 안으로 나누지 않는다
# (10-14 3차 검토 201·202: '…거랑 …거 둘 다 하면 … 차이', '…거랑 …거 합치면 … 비교'를 안마다 따로 계산했다)
# '다 넣는'은 넣지 않는다 — '연금저축에 900만 원 다 넣는 거랑'은 한 안을 말한다(평가셋 조합 비교 질문)
_ADD_SUM_Q = re.compile(r'합쳐|합치|합산|(?<![와과])(?<![와과]\s)같이|함께|둘\s*다|모두|동시에|더하면')
# 더하는 말 뒤가 못 한다는 말('둘 다는 못 해요'·'둘 다 넣을 여유는 없어요'·'둘 다 넣기엔 돈이 부족해요'), 가진 계좌를 말하는 말
# ('둘 다 있어요'·'모두 가입했어요'), 안마다 알려 달라는 말('둘 다 계산해 주세요'·'모두 비교해 주세요')이면 금액을 묶는 말이 아니다
_SUM_NOT_BIND = re.compile(r'\s*(?:는|은|도|를|을|이|가)?\s*(?:[가-힣]{1,4}\s*)?(?:(?:여유|돈|형편|수)\s*(?:는|은|가|이|도)?\s*)?'
                           r'(?:못|없|않|어렵|어려|힘들|무리|불가|부족|모자라|모자|빠듯|벅차|버거|안\s*(?:돼|되))'
                           r'|\s*(?:는|은|도)?\s*(?:가입|있|보유|갖고|가지고|개설|만들었|들었|들어\s*있|하고\s*있|해\s*놨|쓰고\s*있)'
                           r'|\s*(?:를|을|다)?\s*(?:계산|알려|비교|보여|설명|확인|따져|구해)')


def _sum_binds(rx, q, amts):
    """더하는 말(rx)이 금액들(amts)을 묶는 자리에 있는가 — 첫 금액부터 마지막 금액이 든 문장 끝까지에서, 못 함·가진 계좌를 말하지 않을 때.
    10-14 4차 검토 302: '연금저축이랑 IRP 둘 다 있어요. … 300만 원 더 넣는 거랑 … 더 넣는 거 중에 뭐가 나아요?'의 '둘 다'(가진 계좌),
    '둘 다 넣을 여유는 없어요'(못 함)를 질문 어디서나 더하는 말로 보아 고르는 두 안을 더했다(148만 5천 원 — 맞는 값은 안마다 49만 5천 원)."""
    if not amts:
        return False
    a = min(x['s'] for x in amts)
    last = max(x['e'] for x in amts)
    ends = [i for i in (q.find(c, last) for c in '.?!\n') if i >= 0]
    for m in rx.finditer(q, a, min(ends) if ends else len(q)):
        if not _SUM_NOT_BIND.match(q, m.end()):
            return True
    return False


# 둘 다 넣는 이음말 — '…더 넣고 …더 넣으면'
_AND_JOIN = re.compile(r'(?:' + _IN_VERB + r'|납입하|입금하|불입하)고(?:\s|,|$)|그리고|\+|에다(?:가)?\s')
# 넣는 일을 하나씩 묶어 잇는 말 — '…넣는 거랑', '…넣는 것과', '…넣는 경우와'. 고르는 말이 함께 있어야 고르는 안이다
_COORD = re.compile(r'(?:거|것|게|경우|더)\s*(?:이랑|랑|하고|과|와)(?:\s|$)')


# 고르는 말 — '…더 넣는 거랑 …더 넣는 거 중에 뭐가 나아요'. _PICK_STRONG 은 그것만으로 고르는 말, '차이·나아'는 묶는 말과 함께일 때만
_PICK_STRONG = re.compile(r'중(?:에서|에)?\s*(?:뭐|어느|어떤|어디)|(?:거|것|둘)\s*중(?:에서|에)?(?![가-힣])|어느\s*(?:쪽|게|것)'
                          r'|뭐가\s*(?:더\s*)?(?:나|좋|유리)|어떤\s*게|비교|(?<![A-Za-z])vs(?![A-Za-z])', re.I)
_PICK_Q = re.compile(_PICK_STRONG.pattern + r'|나아|나을|유리|차이', re.I)
# 둘 중 하나를 고르라는 말 — '넣고 … 넣으면'(둘 다)과 함께 오면 엇갈린다
_PICK_CHOOSE = re.compile(r'중(?:에서|에)?\s*(?:뭐|어느|어떤|어디)|(?:거|것|둘)\s*중(?:에서|에)?(?![가-힣])|어느\s*(?:쪽|게|것)'
                          r'|뭐가\s*(?:더\s*)?(?:나|좋|유리)|어떤\s*게|(?<![A-Za-z])vs(?![A-Za-z])|아니면', re.I)


def _added_mode(added, q):
    """더 넣는 금액 둘 이상을 어떻게 볼지 → 'sum'(모두 넣음) / 'alt'(하나를 고름) / 'unclear'(규칙만, 숫자 없음).
    더하는 말('둘 다·합치면·모두·같이')이 있으면 고르는 안으로 나누지 않는다. 고르는 안은 고르는 말이 분명할 때만 — 두 금액 사이의
    고르는 이음말('아니면·또는·거나·든지·-ㄹ지·대신·vs'), '거랑·것과·경우와'로 묶고 고르는 말('중에·어느 쪽·비교·차이'), 이음말 없이
    '중에·어느 쪽·비교'. '넣고 … 넣으면'·동사 하나로 묶은 나열은 더한다. 묶었는데 고르는 말이 없거나('…넣는 거랑 …넣는 거 세액공제
    얼마예요?'), 더하는 말과 고르는 말이 함께 있으면 어느 쪽인지 모른다 — 대안도 합계도 내지 않는다(10-14 3차 검토 201·202·204).
    더하는 말은 더 넣는 금액들을 묶는 자리에 있을 때만 본다 — 사정 설명('둘 다 있어요'·'모두 가입했어요'·'둘 다 넣을 여유는 없어요')은
    아니다(10-14 4차 검토 302)."""
    if len(added) < 2 or not all('s' in c for c in added):
        return 'sum'
    if _sum_binds(_ADD_SUM_Q, q, added):
        # 더하는 말과 고르는 이음말이 함께면('…더 넣거나 …더 넣거나, 둘 다 하면') 어느 쪽인지 모른다 — 고르는 안으로는 나누지 않는다
        if any(_ALT_JOIN.search(q[a['e']:b['s']]) for a, b in zip(added, added[1:])):
            return 'unclear'
        return 'sum'
    kinds = set()
    for a, b in zip(added, added[1:]):
        between = q[a['e']:b['s']]
        if _ALT_JOIN.search(between):
            kinds.add('alt')
        elif _AND_JOIN.search(between):
            kinds.add('sum')
        elif _COORD.search(between):
            kinds.add('alt' if _PICK_Q.search(q) else 'unclear')
        elif _PICK_STRONG.search(q):
            kinds.add('alt')            # '연금저축 300만 원 더 / IRP 300만 원 더 중 어느 쪽', '…넣으면 어떻고 …넣으면 어때요? 어느 쪽'
        else:
            # '연금저축에 100만 원 더, IRP에 200만 원 더 넣으면 (세액공제 차이는)' — 동사 하나로 묶은 나열은 모두 넣는 말이다.
            # '차이'만으로는 고르는 말이 아니다(안 넣을 때와의 차이)
            kinds.add('sum')
    if len(kinds) != 1:
        return 'unclear'
    k = kinds.pop()
    if k == 'sum' and _PICK_CHOOSE.search(q):
        return 'unclear'
    return k


def _cname(c):
    """블록에 적을 납입 계좌 이름 — DC·퇴직연금에 넣는 돈은 질문의 이름 그대로(공제 한도는 IRP 와 같은 합산 900만 원)."""
    return c.get('name') or ('IRP' if c['acct'] == 'irp' else '연금저축')


def _irp_name(cs):
    """IRP 쪽(합산 900만 원) 납입 이름 — 'IRP', 'DC', 둘이 섞이면 'IRP·DC'."""
    return '·'.join(dict.fromkeys(_cname(c) for c in cs if c['acct'] == 'irp')) or 'IRP'


def _added_unclear_block(lines, base, added):
    """더 넣는 금액들을 모두 넣는지 하나를 고르는지 모를 때 — 금액 없이 한도 규칙과 되물을 것만."""
    s0 = sum(c['v'] for c in base if c['acct'] == 'savings')
    i0 = sum(c['v'] for c in base if c['acct'] == 'irp')
    if base:
        lines.append('이미 넣은 돈: ' + ', '.join(([f'연금저축 {won(s0)}'] if s0 else [])
                                              + ([f'{_irp_name(base)} {won(i0)}'] if i0 else [])))
    what = ', '.join(_cname(c) + ' '
                     + (f'월 {won(c["raw"])}(연 {won(c["v"])})' if c['monthly'] else won(c['v'])) for c in added)
    lines.append(f'더 넣는 금액: {what} — 모두 넣는 것인지 둘 중 하나를 고르는 것인지 질문에서 분명하지 않아 세액공제를 계산하지 않음')
    lines.append('세액공제 대상은 연금저축 연 600만 원, IRP 포함 합산 연 900만 원까지')
    lines.append('주의: 납부할 세금(결정세액)이 공제액보다 적으면 그만큼만 공제된다. 종합소득이 있어야 공제받는다')
    return _block('doc41.txt', '세액공제', lines, ['ded_limits', 'ded_rates', 'ded_cap_tax', 'ded_need_income'], numbers=False,
                  needs=['더 넣는 금액을 모두 넣는지, 둘 중 하나만 넣는지'])


def _added_alt_block(lines, rate, base, added):
    """이미 넣은 돈(base)에 더 넣는 안(added)을 하나씩 더했을 때 늘어나는 세액공제 — 안마다 따로(더하지 않는다)."""
    s0 = sum(c['v'] for c in base if c['acct'] == 'savings')
    i0 = sum(c['v'] for c in base if c['acct'] == 'irp')
    elig0 = min(min(s0, 600) + i0, 900)
    figs, incs = [], []
    if base:
        line = ('이미 넣은 돈: ' + ', '.join(([f'연금저축 {won(s0)}'] if s0 else [])
                                          + ([f'{_irp_name(base)} {won(i0)}'] if i0 else []))
                + f' → 공제 대상 {won(elig0)}')
        if rate:
            line += f' → 세액공제 {won(elig0)} × {pct(rate)} = {won(elig0 * rate / 100)}'
        lines.append(line)
    for k, c in enumerate(added):
        s1 = s0 + (c['v'] if c['acct'] == 'savings' else 0)
        i1 = i0 + (c['v'] if c['acct'] == 'irp' else 0)
        el = min(min(s1, 600) + i1, 900)
        what = _cname(c) + ' ' + \
            (f'월 {won(c["raw"])}(연 {won(c["v"])})' if c['monthly'] else won(c['v']))
        # 이미 넣은 돈이 없으면 '0원 → 300만 원' 대신 그 안의 공제 대상만
        line = f'안 {"ABCDE"[k]}: {what} 더 → 공제 대상 ' + (f'{won(elig0)} → {won(el)}' if base else won(el))
        if el <= elig0:
            line += ' — 공제 한도(연금저축 600만 원, 합산 900만 원)를 넘는 금액이라 세액공제는 늘지 않는다'
            incs.append(None)
        elif rate:
            inc = won((el - elig0) * rate / 100)
            figs.append(inc)
            incs.append(inc)
            line += (f' → 늘어나는 세액공제 {won(el - elig0)} × {pct(rate)} = {inc} (합계 {won(el * rate / 100)})' if base
                     else f' → 세액공제 {won(el)} × {pct(rate)} = {inc}')
        else:
            a, b = won((el - elig0) * 0.165), won((el - elig0) * 0.132)
            figs += [a, b]
            incs.append(None)
            line += f' → {"늘어나는 " if base else ""}세액공제: 16.5%면 {a}, 13.2%면 {b}'
        if 0 < c['v'] - (el - elig0) < c['v']:
            line += f' · 한도를 넘는 {won(c["v"] - (el - elig0))}은 공제 못 받음'
        lines.append(line)
    if rate and incs[0] and len(set(incs)) == 1:
        lines.append(f'{"늘어나는 " if base else ""}세액공제는 안마다 같다({incs[0]})')
    if len({c['acct'] for c in added}) > 1:
        lines.append('중도인출 조건도 다르다 — 연금저축은 사유 없이 꺼낼 수 있고, IRP는 법정 사유가 있어야 꺼낼 수 있다')
    lines.append('주의: 납부할 세금(결정세액)이 공제액보다 적으면 그만큼만 공제된다. 종합소득이 있어야 공제받는다')
    # 공제율을 모르면 두 공제율 값이 나란히라 핵심 금액을 하나로 정하지 않는다(일반 세액공제 블록과 같다)
    return _block('doc41.txt', '세액공제(조합 비교)', lines, ['ded_limits', 'ded_rates', 'ded_cap_tax', 'ded_need_income'],
                  numbers=bool(figs), key_figure=figs[0] if figs and rate else None, figures=figs)


def _combos(contrib, q=''):
    """납입 나열을 조합으로 나눈다 → [(연금저축 합, IRP 합)].
    같은 계좌가 다시 나오면 새 조합이고, 두 금액이 고르는 말로 이어지면('연금저축 600만 원과 IRP 900만 원 중에', 'A 아니면 B')
    따로 조합이다 — 10-14 검토: 이 둘을 한 조합으로 더하거나 900만 원을 평가액으로 읽었다."""
    out, cur = [], {'savings': 0.0, 'irp': 0.0}
    seen = set()
    for k, c in enumerate(contrib):
        alt = False
        if k and q and 's' in c:
            between = q[contrib[k - 1]['e']:c['s']]
            alt = bool(_ALT_BETWEEN.search(between)) or (
                k == len(contrib) - 1 and bool(_ALT_AFTER.match(q, c['e']))
                and bool(re.search(r'(?:와|과|이랑|랑|하고)\s', between)) and '+' not in between)
        # 별칭이 다른 계좌('A에 300, B에 400')는 같은 종류여도 다른 계좌다 — 다시 나온 계좌로 보지 않는다(stab 2211)
        key = (c['acct'], c.get('alias'))
        if key in seen or alt:
            out.append((cur['savings'], cur['irp']))
            cur, seen = {'savings': 0.0, 'irp': 0.0}, set()
        cur[c['acct']] += c['v']
        seen.add(key)
    out.append((cur['savings'], cur['irp']))
    return out if len(out) >= 2 else []


# ISA 만기 돈을 옮겨 늘어나는 공제를 묻는 말 — 'ISA 돈 옮기면 공제 얼마나 늘어요'
_ISA_MORE_Q = re.compile(r'ISA[^.?!\n]{0,40}?(?:옮기|옮겨|옮길|전환|이체|넣)[^.?!\n]{0,30}?'
                         r'(?:늘|얼마\s*(?:나\s*)?더|더\s*(?:받|돌려|나와|나오|생기|되|돼|됩|될)|추가)', re.I)
# 고객이 밝힌 결정세액(낼 세금) — '결정세액이 30만 원밖에', '결정세액이 1백인데', '낼 세금이 1백밖에', '세금이 30만 원밖에 안 나와서'
# 뒤에 %가 오면 세율이다 — '나중에 내는 세금이 16.5%라던데'를 결정세액 16만 5천 원으로 읽고 공제액을 지웠다(stab 재검증 R8)
_TAX_AMT = r'(\d+(?:,\d{3})*(?:\.\d+)?)(?![\d.,])\s*(만|백|천)?(?!\s*(?:%|퍼센트|퍼|프로|[~∼]|-\s*\d))'
_TAX_CAP = re.compile(r'(?:결정\s*세액|산출\s*세액|(?:낼|내는|내야\s*할|내야\s*하는|납부할|납부하는)\s*세금)'
                      r'\s*(?:은|는|이|가|도)?\s*(?:약|대략|한)?\s*' + _TAX_AMT)
_TAX_ONLY = re.compile(r'(?<![가-힣])세금\s*(?:은|는|이|가|도)?\s*(?:약|대략|한)?\s*' + _TAX_AMT + r'\s*(?:원\s*)?밖에')


def _tax_cap(q):
    """질문의 결정세액(만 원) 또는 None."""
    m = _TAX_CAP.search(q or '') or _TAX_ONLY.search(q or '')
    if not m:
        return None
    v = float(m.group(1).replace(',', ''))
    unit = m.group(2)
    if unit == '백':
        return v * 100
    if unit == '천':
        return v * 1000
    return v if unit == '만' or v < 10000 else v / 10000


def deduction(p, q):
    """세액공제. 소득을 알면 공제율을 정하고, 납입액을 알면 공제액까지."""
    lines = []
    rate = None
    if p['income']:
        kind, v = p['income']
        cut = 5500 if kind == '총급여' else 4500
        rate = 16.5 if v <= cut else 13.2
        word = '연봉' if re.search(r'연봉', q) and kind == '총급여' else kind
        lines.append(f'입력: {word} {won(v)}' + (' (총급여로 봄)' if word == '연봉' else '')
                     + f' → 기준 {won(cut)} {"이하" if v <= cut else "초과"} → 세액공제율 {pct(rate)}')
    else:
        lines.append('공제율을 정할 소득이 질문에 분명하지 않음 (직장인 총급여 5,500만 원, 종합소득자 종합소득금액 4,500만 원 '
                     '이하면 16.5%, 초과면 13.2%)')
    for v in dict.fromkeys(p.get('retire_dropped') or []):
        # 블록에 까닭이 없으면 모델이 질문의 금액으로 공제액을 스스로 계산할 수 있다(3차 검토 200) — 문서(doc38)의 재원 구분을 싣는다
        lines.append(f'{won(v)}은 퇴직금(퇴직급여·DC·퇴직연금) 쪽에서 온 돈 — 연금계좌 안에서 퇴직금은 세액공제 받은 돈과 따로 '
                     '구분되는 재원이라 세액공제 납입액으로 계산하지 않음')
    unsure = list(dict.fromkeys(p.get('retire_unsure') or []))
    for v in unsure:
        # 어느 쪽인지 모르면 한쪽으로 단정하지 않고 두 경우의 규칙만 — 숫자는 내지 않는다(10-14 4차 검토 300)
        lines.append(f'{won(v)}이 본인이 넣는 돈인지 퇴직금 쪽(퇴직급여·회사가 낸 부담금) 돈인지 질문에서 분명하지 않아 세액공제를 '
                     '계산하지 않음 — 본인이 넣는 돈(DC에 본인 부담으로 넣는 가입자부담금 포함)은 세액공제 대상, '
                     '퇴직금은 세액공제 받은 돈과 따로 구분되는 재원이라 세액공제 납입이 아님')
    for v in dict.fromkeys(p.get('retire_db') or []):
        lines.append(f'{won(v)}은 DB(확정급여형)에 넣는 돈 — DB에 본인이 넣는 돈의 세액공제 규칙은 받은 문서에 없어 계산하지 않음 '
                     '(세액공제는 연금저축·IRP와 DC 가입자부담금 납입액이 대상)')
    acct_unsure = list(dict.fromkeys(p.get('acct_unsure') or []))
    if acct_unsure:
        # 넣는 계좌를 모르면 공제 대상(연금저축 600만 원 / 합산 900만 원)이 갈린다 — 이 금액의 공제는 계산하지 않고 되묻는다(7차 610).
        # 계좌를 아는 다른 납입('연금저축에 600만 원 넣었어요. IRP는 아직 없는데 300만 원 더')의 공제는 모르는 금액이 어느 계좌로
        # 가든 줄지 않으니 그 몫만 계산해 남긴다 — 7차는 이것까지 지워 알고 있는 99만 원도 내지 않았다(8차 708)
        figs, key = [], None
        known = p['contrib']
        if known:
            for c in known:
                if c['monthly']:
                    lines.append(f'입력: {_cname(c)} 월 {won(c["raw"])} × 12 = 연 {won(c["v"])}')
            ks = sum(c['v'] for c in known if c['acct'] == 'savings')
            ki = sum(c['v'] for c in known if c['acct'] == 'irp')
            el = min(min(ks, 600) + ki, 900)
            lines.append('계좌를 아는 납입: ' + ', '.join(([f'연금저축 {won(ks)}'] if ks else [])
                                                     + ([f'{_irp_name(known)} {won(ki)}'] if ki else []))
                         + f' → 공제 대상 {won(el)} (연금저축 한도 600만 원, IRP 포함 합산 900만 원)')
            if any(c.get('name') for c in known):
                lines.append('DC·퇴직연금에 본인이 추가로 넣는 가입자부담금은 연 900만 원까지 세액공제 대상 — IRP 납입과 같은 합산 한도로 계산')
            if rate:
                key = won(el * rate / 100)
                figs.append(key)
                lines.append(f'이 납입의 세액공제액 = {won(el)} × {pct(rate)} = {key}')
            else:
                a, b = won(el * 0.165), won(el * 0.132)
                figs += [a, b]
                lines.append(f'이 납입의 세액공제액(공제율에 따라): 16.5%면 {won(el)} × 16.5% = {a}, 13.2%면 {won(el)} × 13.2% = {b}')
        for v in acct_unsure:
            lines.append(f'{won(v)}을 연금저축과 IRP 중 어느 계좌에 넣는지 질문에서 분명하지 않아 '
                         + ('이 금액으로 늘어나는 세액공제는 계산하지 않음' if known else '세액공제를 계산하지 않음'))
        lines.append('세액공제 대상은 연금저축 연 600만 원, IRP 포함 합산 연 900만 원까지')
        lines.append('주의: 납부할 세금(결정세액)이 공제액보다 적으면 그만큼만 공제된다. 종합소득이 있어야 공제받는다')
        keys = ['ded_limits', 'ded_rates', 'ded_cap_tax', 'ded_need_income'] + \
            (['three_funds', 'dc_own'] if unsure else ['dc_own'] if any(c.get('name') for c in known) else [])
        return [_block('doc41.txt', '세액공제', lines, keys, numbers=bool(figs), key_figure=key, figures=figs,
                       needs=[f'{won(v)}을 넣을 계좌(연금저축인지 IRP인지)' for v in acct_unsure]
                       + [f'{won(v)}이 본인이 넣는 돈인지, 퇴직금 쪽 돈(퇴직급여·회사가 낸 부담금)인지' for v in unsure])]
    s = sum(c['v'] for c in p['contrib'] if c['acct'] == 'savings')
    i = sum(c['v'] for c in p['contrib'] if c['acct'] == 'irp')
    has_s = any(c['acct'] == 'savings' for c in p['contrib'])
    has_i = any(c['acct'] == 'irp' for c in p['contrib'])
    keys0 = ['ded_limits', 'ded_rates', 'ded_cap_tax', 'ded_need_income']
    if p['contrib'] and not p['isa'] and _ISA_MORE_Q.search(q):
        # 'ISA 돈 옮기면 공제 얼마나 늘어요?'인데 전환액을 못 읽었다('만기 금액이 3천') — 지금 납입의 공제액(33만 원)은 물은 값이 아니다.
        # 핵심 숫자로 내면 늘어나는 값처럼 쓰여 맞는 답(전환분 49만 5천 원)을 이 값으로 바꿨다. 규칙만 싣는다
        lines.append('ISA 만기 전환 금액을 질문에서 분명히 읽지 못해 전환으로 늘어나는 세액공제는 계산하지 않음 — 전환 연도에는 '
                     '전환 금액의 10%(최대 300만 원)가 공제 대상 한도에 더해진다(R-03)')
        lines.append('세액공제 대상은 연금저축 연 600만 원, IRP 포함 합산 연 900만 원까지')
        return [_block('doc41.txt', '세액공제', lines, keys0 + ['isa_extra', 'isa_formula'], numbers=False)]
    cap = _tax_cap(q)
    if p['contrib'] and cap is not None and min(min(s, 600) + i, 900) * (rate or 16.5) / 100 > cap:
        # '결정세액이 1백인데 IRP 9백 넣으면' — 고객이 밝힌 결정세액보다 큰 공제액은 그대로 받지 못한다(doc41: 납부할 세금이 작으면
        # 세액공제액도 그만큼 줄어든다). 공제액(148만 5천 원)을 핵심 숫자로 내면 맞는 답('100만 원까지만')을 이 값으로 바꿨다. 숫자 없이 규칙만
        elig = min(min(s, 600) + i, 900)
        for c in p['contrib']:
            if c['monthly']:
                lines.append(f'입력: {_cname(c)} 월 {won(c["raw"])} × 12 = 연 {won(c["v"])}')
        lines.append('납입: ' + ', '.join(([f'연금저축 {won(s)}'] if has_s else []) + ([f'{_irp_name(p["contrib"])} {won(i)}'] if has_i else []))
                     + f' → 공제 대상 {won(elig)} (연금저축 한도 600만 원, IRP 포함 합산 900만 원)')
        # 상한을 문장으로 밝힌다 — '그만큼만 공제된다'만으로는 '148만 5천 원 다 돌려받아요?'에 '아니다'가 블록에 없다(stab 2213)
        lines.append(f'질문의 결정세액 {won(cap)}이 공제 대상에 공제율을 곱한 값보다 적다 — 납부할 세금(결정세액)이 공제액보다 적으면 '
                     '그만큼만 공제된다. 종합소득이 있어야 공제받는다')
        lines.append(f'그래서 세액공제로 줄어드는 세금은 결정세액 {won(cap)}을 넘지 못한다 — 공제 대상에 공제율을 곱한 금액을 '
                     '다 받지는 못한다')
        return [_block('doc41.txt', '세액공제', lines, keys0, numbers=False)]
    for c in p['contrib']:
        if c.get('assumed'):
            # parse 가 넣는 계좌를 모르는 금액을 이미 넣은 계좌로 계산했다 — 어느 계좌든 공제 대상이 같을 때만이라 그렇게 밝힌다
            lines.append(f'{"월 " + won(c["raw"]) if c["monthly"] else won(c["v"])}을 넣을 계좌는 질문에서 분명하지 않지만 '
                         '연금저축·IRP 어느 쪽에 넣어도 공제 대상이 같아 '
                         f'{_cname(c)}에 넣는 것으로 계산')
    # '연금저축에 300만 원 넣었고 300만 원 더 넣으면 … 차이' — 이미 넣은 돈에 더하는 금액이 있으면 누적이지 조합 비교가 아니다
    # (10-14 검토: 같은 계좌가 다시 나와 조합 A·B 둘 다 49만 5천 원으로 나눠 보였다 — 맞는 값은 합계 600만 원 → 99만 원)
    added = [c for c in p['contrib'] if c.get('more')]
    base = [c for c in p['contrib'] if not c.get('more')]
    mode = _added_mode(added, q)
    if mode == 'alt':
        # '이미 300만 원 넣었는데 연금저축에 300만 원 더 넣는 거랑 IRP에 300만 원 더 넣는 거 중에' — 더 넣는 금액이 서로 고르는 안이면
        # 안마다 이미 넣은 돈에 그 금액만 더해 늘어나는 공제를 따로 보인다(10-14 2차 검토: 셋을 다 더해 '늘어나는 세액공제 99만 원'을
        # 냈다. 그 전에는 같은 계좌가 다시 나온 데서 조합을 끊어 49만 5천·99만 원 — 맞는 값은 안마다 49만 5천 원)
        return [_added_alt_block(lines, rate, base, added)]
    if mode == 'unclear':
        return [_added_unclear_block(lines, base, added)]
    combos = _combos(p['contrib'], q) if _COMBO_Q.search(q) and not added else []
    if not combos and _acct_choice(p, q):
        # '연금저축이랑 IRP 중에 어디에 600 넣는 게 나아요?' — 한 금액을 두 계좌에 넣는 경우를 나란히(C18 대화: 블록 없이 '연금저축이 유리'라고 권했다)
        v = p['contrib'][0]['v']
        combos = [(v, 0.0), (0.0, v)]
    if len(combos) >= 2:
        # '연금저축 600 + IRP 300이랑 연금저축 900 비교' — 같은 계좌가 다시 나오면 다른 조합이다(DIY 설계 7쪽)
        figs = []
        for k, (cs, ci) in enumerate(combos):
            el = min(min(cs, 600) + ci, 900)
            name = '조합 ' + 'ABCDE'[k]
            parts = ([f'연금저축 {won(cs)}'] if cs else []) + ([f'IRP {won(ci)}'] if ci else [])
            line = f'{name}: ' + ' + '.join(parts) + f' → 공제 대상 {won(el)}'
            if rate:
                line += f' → 세액공제 {won(el)} × {pct(rate)} = {won(el * rate / 100)}'
                figs.append(won(el * rate / 100))
            over = cs + ci - el
            if over > 0:
                line += f' · 공제 못 받는 {won(over)}은 나중에 꺼낼 때 원금만 세금 없음(과세제외)'
            lines.append(line)
        # 고객에게 그대로 나가는 줄이라 내부 지시('비교만 보여 준다 — … 고객이 고른다')를 쓰지 않는다(10-14 m.Talk 비교 M05)
        lines.append('중도인출 조건도 다르다 — 연금저축은 사유 없이 꺼낼 수 있고, IRP는 법정 사유가 있어야 꺼낼 수 있다')
        lines.append('주의: 납부할 세금(결정세액)이 공제액보다 적으면 그만큼만 공제된다. 종합소득이 있어야 공제받는다')
        blocks = [_block('doc41.txt', '세액공제(조합 비교)', lines, ['ded_limits', 'ded_rates', 'ded_cap_tax', 'ded_need_income'],
                         numbers=bool(figs), key_figure=figs[0] if figs else None, figures=figs)]
        return blocks
    figs, key, asked = [], None, None

    def both(x):
        """공제율을 모를 때 두 공제율로 — 공제 대상만 보이면 '얼마 돌려받나'에 닿지 못한다."""
        a, b = won(x * 0.165), won(x * 0.132)
        figs.extend([a, b])
        return f'16.5%면 {won(x)} × 16.5% = {a}, 13.2%면 {won(x)} × 13.2% = {b}'
    if p['contrib']:
        for c in p['contrib']:
            if c['monthly']:
                lines.append(f'입력: {_cname(c)} 월 {won(c["raw"])} × 12 = 연 {won(c["v"])}')
        elig = min(min(s, 600) + i, 900)
        lines.append('납입: ' + ', '.join(([f'연금저축 {won(s)}'] if has_s else [])
                                          + ([f'{_irp_name(p["contrib"])} {won(i)}'] if has_i else []))
                     + f' → 공제 대상 {won(elig)} (연금저축 한도 600만 원, IRP 포함 합산 900만 원)')
        if any(c.get('name') for c in p['contrib']):
            # DC 에 본인이 넣는 돈을 계산했으면 그 근거(doc55 가입자부담금)를 함께 싣는다 — doc41 원문은 연금저축·IRP 만 적는다
            lines.append('DC·퇴직연금에 본인이 추가로 넣는 가입자부담금은 연 900만 원까지 세액공제 대상 — IRP 납입과 같은 합산 한도로 계산')
        if rate:
            key = won(elig * rate / 100)
            figs.append(key)
            lines.append(f'세액공제액 = {won(elig)} × {pct(rate)} = {key}')
        else:
            lines.append('세액공제액(공제율에 따라): ' + both(elig))
        if added and base:
            # '연금저축 600만 원 넣었고 IRP에 100만 원 더 넣으면 얼마나 늘어요' — 물은 값은 그 금액으로 늘어나는 공제액이다
            # (10-14 검토: '남은 한도를 다 채우면 33만 원 더'를 첫 줄에 넣어 맞는 답 16만 5천 원 위에 다른 숫자가 나갔다)
            s0 = sum(c['v'] for c in base if c['acct'] == 'savings')
            elig0 = min(min(s0, 600) + sum(c['v'] for c in base if c['acct'] == 'irp'), 900)
            what = ' + '.join(_cname(c) + ' '
                              + (f'월 {won(c["raw"])}(연 {won(c["v"])})' if c['monthly'] else won(c['v'])) for c in added)
            line = f'더 넣는 {what}: 공제 대상 {won(elig0)} → {won(elig)}'
            if elig <= elig0:
                lines.append(line + ' — 공제 한도(연금저축 600만 원, 합산 900만 원)를 넘는 금액이라 세액공제는 늘지 않는다')
            elif rate:
                inc = won((elig - elig0) * rate / 100)
                figs.append(inc)
                lines.append(line + f' → 늘어나는 세액공제 = {won(elig - elig0)} × {pct(rate)} = {inc} '
                             f'(합계 {won(elig0 * rate / 100)} → {key})')
                # 늘어나는 값을 물었을 때만 첫 줄 — '400만 원 넣고 IRP에 500만 원 더 넣으면 공제 얼마예요?'는 합계를 묻는다
                if re.search(r'늘|얼마\s*더|얼마나\s*더|더\s*(?:받|돌려|나와|나오|생기|되)|차이|증가|추가분|추가로\s*(?:얼마|받|돌려)', q):
                    asked = (inc, f'{what}을 더 넣으면 세액공제가 **{inc}** 늘어요(합계 {key}).')
            else:
                lines.append(line + ' → 늘어나는 세액공제(공제율에 따라): ' + both(elig - elig0))
        room = 900 - elig
        if room > 0 and re.search(r'더|추가|남은|남았|채우|채울|마저', q):
            # '연금저축에 600만 원 넣었는데 IRP에 더 넣으면' — 남은 공제 한도와 다 채울 때 더 받는 세액공제(장면 4)
            via = 'IRP로' if min(s, 600) >= 600 else '연금저축 600만 원까지 또는 IRP로'
            line = f'{"더 넣은 뒤에도 남는" if added else "남은"} 공제 한도: 900만 원 − {won(elig)} = {won(room)} ({via} 채울 수 있음)'
            if rate:
                line += f' → 다 채우면 {won(room)} × {pct(rate)} = {won(room * rate / 100)} 더 공제'
                figs.append(won(room * rate / 100))
                # 질문이 '더 넣으면 얼마'라 답의 첫 숫자는 늘어나는 공제액이어야 한다 — 10-14 m.Talk 비교 M01·시연 실측(3회 중 1회)에서
                # 모델 답이 합계 148만 5천 원만 쓰고 49만 5천 원을 빠뜨렸다. answer.ensure_asked 가 없으면 첫 줄에 넣는다.
                # 질문에 더 넣을 금액이 있으면('IRP에 100만 원 더') 물은 값은 그 금액의 공제라 이 문장을 쓰지 않는다(10-14 검토),
                # '세액공제 더 받는 건 어디'의 '더'처럼 채우는 말이 아니면 쓰지 않는다
                if not added and re.search(r'더\s*(?:넣|납입|내|붓|부으|채우|하면)|추가(?:로)?\s*(?:넣|납입|입금|하면|해서)|추가\s*납입'
                                           r'|남은|남았|채우|채울|마저', q):
                    asked = (won(room * rate / 100), f'남은 공제 한도 {won(room)}을 다 채우면 세액공제가 **{won(room * rate / 100)}** '
                                                     f'더 늘어요(합계 {won(900 * rate / 100)}).')
            else:
                line += ' → 다 채우면 더 받는 세액공제: ' + both(room)
            lines.append(line)
            if rate:
                lines.append(f'다 채운 뒤 세액공제 합계 = 900만 원 × {pct(rate)} = {won(900 * rate / 100)}')
                figs.append(won(900 * rate / 100))
            else:
                lines.append('다 채운 뒤 세액공제 합계: ' + both(900))
            lines.append('그해 12월 31일까지 납입한 금액이 그해 공제 대상이다')
    elif re.search(r'최대|얼마까지|얼마나\s*넣|한도|(?:다|꽉|가득|모두)\s*채[우워울]|만\s*원?\s*(?:을|를)?\s*채[우워울]', q):
        # '900만 원을 다 채우면 세액공제는 총 얼마' — 한도를 다 채우는 질문도 최대 공제를 보인다(C18 대화)
        if rate:
            lines.append(f'최대: 연금저축만이면 600만 원 × {pct(rate)} = {won(600 * rate / 100)}, '
                         f'IRP와 합쳐 900만 원 × {pct(rate)} = {won(900 * rate / 100)}')
            figs += [won(600 * rate / 100), won(900 * rate / 100)]
        else:
            lines.append('최대: 연금저축 단독 600만 원, IRP 포함 합산 900만 원까지 공제 대상')
    if figs and _each_two(p, q):
        # '저는 총급여 6천5백, 와이프는 4천 … 각자 세액공제' — 남의 소득은 읽지 않아 한 사람 몫만 계산한다. 밝히지 않으면 두 사람 다
        # 같은 금액으로 읽힌다(stab 2215)
        who = f'{p["income"][0]} {won(p["income"][1])}인 ' if p['income'] else ''
        lines.append(f'질문이 두 사람 각자의 공제를 묻는다 — 위 계산은 {who}한 사람 몫이고, 다른 사람 몫은 그 사람의 소득·납입액으로 '
                     '따로 계산해야 한다')
    lines.append('주의: 납부할 세금(결정세액)이 공제액보다 적으면 그만큼만 공제된다. 종합소득이 있어야 공제받는다')
    keys = ['ded_limits', 'ded_rates', 'ded_cap_tax', 'ded_need_income'] + \
        (['three_funds'] if p.get('retire_dropped') or unsure else []) + \
        (['dc_own'] if unsure or p.get('retire_db') or any(c.get('name') for c in p['contrib']) else [])
    # 계산값이 없는 블록(공제율 규칙만)은 numbers=False — '새로 계산하지 마라'·초안 1개가 걸리지 않게
    blocks = [_block('doc41.txt', '세액공제', lines, keys, numbers=bool(figs), key_figure=key, figures=figs,
                     needs=[f'{won(v)}이 본인이 넣는 돈인지, 퇴직금 쪽 돈(퇴직급여·회사가 낸 부담금)인지' for v in unsure])]
    if asked and not p['isa']:
        # ISA 전환을 물으면 늘어나는 값은 ISA 블록이 정한다 — '남은 한도를 다 채우면'은 물은 값이 아니다
        blocks[0]['asked'] = asked
    if p['isa']:
        blocks.append(isa_block(p, rate, s, i, q))
    return blocks


def isa_block(p, rate, s, i, q=''):
    """ISA 만기 전환 연도의 공제 대상(doc4 업무매뉴얼 산식).
    일반 한도분 = min(전환액 + 일반 납입, 600만[연금저축] / 900만[IRP 포함]),
    추가분 = min(전환액 × 10%, 300만), 합계는 실제 납입액(전환액 + 일반 납입)을 넘지 않는다."""
    isa = p['isa']
    extra = min(isa * 0.1, 300)
    lines = [f'입력: ISA 만기 전환 {won(isa)}' + (f', 올해 연금저축 납입 {won(s)}' if s else '')
             + (f', IRP 납입 {won(i)}' if i else '')]

    def total(dest):
        to_s = isa if dest == 'savings' else isa / 2 if dest == 'split' else 0
        gs = min(s + to_s, 600)
        g = min(gs + i + (isa - to_s), 900)
        return g, min(g + extra, isa + s + i)

    # 60일은 계산의 전제다(doc4: 만기일부터 60일이 지나면 전환 불가) — 블록 끝 줄에 두었더니 총 공제액 줄을 더한 뒤 답에서 빠졌다
    lines.append(f'추가 공제 대상 = min(전환액 × 10%, 300만 원) = {won(extra)} (전제: ISA 만기일부터 60일 안에 연금계좌로 옮긴 경우 — '
                 '60일이 지나면 전환 불가. 전환액은 연 1,800만 원 납입한도와 별도)')
    dests = ['savings', 'irp', 'split'] if p.get('isa_split') else [p['isa_dest']] if p['isa_dest'] else ['savings', 'irp']
    figs = [won(extra)] + ([won(extra * rate / 100)] if rate else [])
    totals = {}
    asked = None
    for d in dests:
        g, t = total(d)
        name = ('연금저축계좌로 옮기면' if d == 'savings' else 'IRP로 옮기면' if d == 'irp'
                else f'나눠 옮기면(연금저축 {won(isa / 2)} + IRP {won(isa / 2)})')
        totals[name] = t
        line = f'{name}: 일반 한도분 {won(g)} + 추가분 {won(extra)}'
        line += f' = 공제 대상 {won(t)}' if t == g + extra else f' → 실제 납입액 상한으로 공제 대상 {won(t)}'
        if rate:
            line += f' → 세액공제 {won(t)} × {pct(rate)} = {won(t * rate / 100)}'
            figs.append(won(t * rate / 100))
            base = min(min(s, 600) + i, 900)
            if base:
                # 이미 넣은 납입분의 공제보다 얼마나 늘어나는지 — 고객이 실제로 궁금한 값(옮기면 더 받는 금액)
                line += f' (옮기지 않을 때 {won(base * rate / 100)}보다 {won((t - base) * rate / 100)} 더)'
                if len(dests) == 1 and t > base and re.search(r'더|추가', q):
                    # '옮기면 얼마 더' — 물은 값은 옮겨서 늘어나는 공제액(세액공제 블록의 '남은 한도를 다 채우면'이 아니다)
                    asked = (won((t - base) * rate / 100), f'ISA 만기 {won(isa)}을 {name} 세액공제가 '
                                                           f'**{won((t - base) * rate / 100)}** 더 늘어요(합계 {won(t * rate / 100)}).')
        lines.append(line)
    if not rate:
        lines.append(f'추가분 {won(extra)}의 세액공제액: 공제율 16.5%면 {won(extra * 0.165)}, 13.2%면 {won(extra * 0.132)}')
        # 추가분만 보이면 답이 좁아진다 — 옮긴 해의 총 공제액도 싣는다
        for t in dict.fromkeys(totals.values()):
            who = [n for n, v in totals.items() if v == t]
            head = '' if len(set(totals.values())) == 1 else ' / '.join(who) + ' — '
            lines.append(f'{head}옮긴 해 공제 대상 {won(t)} 전체의 세액공제액: 공제율 16.5%면 {won(t * 0.165)}, '
                         f'13.2%면 {won(t * 0.132)}')
            figs += [won(t * 0.165), won(t * 0.132)]
    if (p['isa_dest'] == 'savings' or p['no_irp']) and not i:
        lines.append('IRP 납입이 없으면 일반 한도분의 상한이 연금저축 600만 원이다(IRP 포함 시 900만 원)')
    b = _block('doc4.txt', 'ISA 전환 세액공제', lines, ['isa_to_savings', 'isa_to_irp', 'isa_formula'],
               figures=list(dict.fromkeys(figs)))
    if asked:
        b['asked'] = asked
    return b


# 한도만 묻는 말 — '올해 한도 얼마예요', '한도 안에서 최대 얼마까지 빼도 돼요'. '최대 얼마'만으로는 아니다('세금 최대 얼마 나와요')
_LIMIT_ASK = re.compile(r'한도\s*(?:가|는|이)?\s*(?:얼마|몇)|얼마\s*까지\s*(?:빼|꺼내|받|찾|인출|수령)'
                        r'|한도\s*(?:안|내|이내)에서\s*(?:최대\s*)?(?:얼마|몇)')
# 연금수령한도가 아닌 한도 — 납입 한도·세액공제 한도·더 넣을 수 있는 한도
_LIMIT_NOT_PAY = re.compile(r'납입|불입|넣|채우|채울|공제|환급|연말\s*정산')
# 받는 쪽 말 — 'N년차'만으로는 가입 연차인지 수령 연차인지 몰라 어느 한도인지 모른다
_LIMIT_PAY_CTX = re.compile(r'수령|개시|인출|빼|꺼내|찾|연금\s*(?:을|으로)?\s*받')


def _limit_ask(q):
    """연금수령한도를 묻는가. 그 말이 든 문장에 넣는 말·공제 말이 없고 질문에 받는 쪽 말이 있을 때만 — 'N년차'를 연금수령연차로 읽는
    버릇과 맞물려 '납입 한도·세액공제 한도 얼마예요'에 연금수령한도를 핵심 숫자로 냈다(10-15 검토)."""
    for m in _LIMIT_ASK.finditer(q):
        a = max(q.rfind(c, 0, m.start()) for c in '.?!\n') + 1
        b = min([i for i in (q.find(c, m.end()) for c in '.?!\n') if i >= 0] or [len(q)])
        if _LIMIT_NOT_PAY.search(q[a:b]):
            continue
        # 묻는 말 자체의 동사('한도 내에서 최대 얼마 받을 수', '얼마까지 빼도')도 받는 쪽 말이다
        if _LIMIT_PAY_CTX.search(q) or re.search(r'받|빼|꺼내|찾|인출|수령', q[m.start():min(m.end() + 8, b)]):
            return True
    return False


def _limit_only(p, q):
    """평가액·연차로 연금수령한도만 — 인출액 없이 한도를 묻는 질문(stab 2240·2268: 값을 다 읽고도 인출액이 없다고 블록을 내지
    않았다). 세금은 꺼낼 금액에 달려 계산하지 않는다."""
    if p['payout'] or not _limit_ask(q):
        return None
    # 인출액 없이 한도만 묻는 길은 연차가 연금수령연차일 때만 숫자를 낸다 — 맨 'N년차'는 가입 연차일 수 있고('연금저축 10년차고
    # 평가액 2억, 55세 되면 개시하려는데 한도' → 2억 4,000만 원), 중도인출 한도는 연금수령한도가 아니다('IRP 3년차 주택 구입으로
    # 중도인출하면 한도' → 450만 원)(stab 재검증 R2). 이미 받고 있다는 말이 있으면 맨 'N년차'도 수령 연차로 본다
    if re.search(r'중도\s*인출', q) or re.search(r'개시\s*(?:하려|할|하면|하기|전|예정|계획)|(?:나중에|내년에?|앞으로)[^.?!\n]{0,12}(?:개시|받)', q):
        return None
    receiving = re.search(r'받고\s*있|받는\s*중|수령\s*중|받은\s*지|개시(?:했|한|된|하고)', q) or \
        (re.search(r'한도\s*(?:안|내|이내)에서', q) and isinstance(p['age'], int) and p['age'] >= 55)   # '64세, 한도 내에서 최대 얼마 받을 수'
    if not p.get('year_explicit') and not receiving:
        return None
    n, B = p['year_n'], p['balance']
    lines = [f'입력: 평가액 {won(B)}, 연금수령연차 {n}년차']
    keys = ['limit_formula', 'limit_year1', 'over_limit', 'limit_rates']
    if n >= 11:
        lines.append('연금수령연차 11년차부터는 연금수령한도가 적용되지 않는다')
        key, figs = None, []
    else:
        lim = B / (11 - n) * 1.2
        key = won(lim)
        figs = [key]
        lines.append(f'연금수령한도 = {won(B)} ÷ (11 − {n}) × 120% = {key}')
    lines.append('한도 안에서 받으면 연금수령 — 세액공제 받은 돈·수익은 연금소득세(55~69세 5.5%, 70~79세 4.4%, 80세 이상 3.3%), '
                 '한도를 넘는 금액은 연금외수령으로 기타소득세 16.5%')
    lines.append('세액공제 받은 돈·수익을 연 1,500만 원 넘게 연금수령하면 초과분이 아니라 전액이 종합과세 또는 16.5% 분리과세 대상')
    return _block('doc39.txt', '연금수령한도', lines, keys + ['over_1500', 'whole_amount'], key_figure=key, figures=figs,
                  numbers=bool(figs))


def withdraw_limit(p, q):
    """연금수령한도와 인출 과세. 평가액·인출액·연차가 모두 분명할 때만. 인출액 없이 한도만 물으면 한도만."""
    if p['balance'] is None or not p['year_n']:
        return None
    if isinstance(p['age'], int) and p['age'] < 55:
        return None                       # 55세 전에는 연금수령이 아니다 → payout 의 규칙만 블록으로
    if p['withdraw'] is None:
        return _limit_only(p, q)
    n = p['year_n']
    lines = [f'입력: 평가액 {won(p["balance"])}, 연금수령연차 {n}년차, 인출 {won(p["withdraw"])}']
    keys = ['limit_formula', 'limit_year1', 'over_limit', 'limit_rates']
    if p['year_assumed']:
        lines.append('연차: 올해가 처음 연금개시가 가능한 해라면 1년차 (연금수령연차는 실제 수령 여부와 무관하게 개시 가능한 해부터 센다. '
                     '2013년 3월 1일 이전 가입 계좌는 6년차부터)')
        keys += ['year_count', 'year6']
    if n >= 11:
        lines.append('연금수령연차 11년차부터는 연금수령한도가 적용되지 않는다')
        lim = None
    else:
        lim = p['balance'] / (11 - n) * 1.2
        lines.append(f'연금수령한도 = {won(p["balance"])} ÷ (11 − {n}) × 120% = {won(lim)}')
    w = p['withdraw']
    inside = w if lim is None else min(w, lim)
    over = 0 if lim is None else max(0.0, w - lim)
    band = rate_for_age(rate_age(p))
    figs = [won(lim)] if lim is not None else []
    t_over = over * 0.165
    if over:
        lines.append(f'인출 {won(w)} 중 한도 안 {won(inside)}은 연금수령, 한도 초과 {won(over)}은 연금외수령')
        lines.append(f'한도 초과분이 세액공제 받은 납입금·운용수익이면 16.5% 기타소득세: {won(over)} × 16.5% = {won(t_over)}')
        figs.append(won(t_over))
    else:
        lines.append(f'인출 {won(w)}은 한도 안 → 연금수령')
    t_in = None
    if inside > 1500:
        t_in = inside * 0.165
        lines.append(f'연금수령분 {won(inside)}도 연 1,500만 원 초과 → 초과분이 아니라 전액이 종합과세 또는 16.5% 분리과세 대상: '
                     f'{won(inside)} × 16.5% = {won(t_in)}')
        keys += ['over_1500', 'whole_amount']
    elif band:
        t_in = inside * band[0] / 100
        lines.append(f'연금수령분 {won(inside)}: {won(inside)} × {pct(band[0])} = {won(t_in)} (나이 기준)')
    else:
        # 나이를 모르면 구간별로 — 고객 구간 하나만 정하지 않고 세 구간을 모두 싣는다(나눠 더한 합계도)
        alt = [inside * x / 100 for x, _ in _BANDS]
        figs += [won(a) for a in alt]
        lines.append(f'연금수령분 {won(inside)}: 나이가 질문에 없어 구간별로 '
                     + ' · '.join(f'{name} {pct(x)} → {won(a)}' for (x, name), a in zip(_BANDS, alt)))
        if over:
            figs += [won(t_over + a) for a in alt]
            lines.append('나이 구간별 올해 세금 합계: '
                         + ' · '.join(f'{name} {won(t_over)} + {won(a)} = {won(t_over + a)}'
                                      for (x, name), a in zip(_BANDS, alt)))
    key = None
    if t_in is not None:
        figs.append(won(t_in))
        key = won(t_over + t_in)
        if over:
            lines.append(f'올해 예상 세금 합계 = {won(t_over)} + {won(t_in)} = {key}'
                         + (' (연금수령분을 16.5% 분리과세로 고를 때)' if inside > 1500 else ''))
            figs.append(key)
    elif over:
        key = won(t_over)              # 나이를 몰라도 한도 초과분 세금은 정해진다 — 숫자 대조가 '2,970만 원' 같은 오산을 잡게
    lines.append('전제: 세액공제 받은 납입금·운용수익 재원 기준. 세액공제 안 받은 납입금 → 퇴직금 → 세액공제 받은 납입금·운용수익 '
                 '순으로 인출되므로 재원 구성에 따라 과세가 달라진다 — 재원 구성은 질문에 없다')
    return _block('doc39.txt', '연금수령한도', lines, keys, key_figure=key, figures=list(dict.fromkeys(figs)))


# ---------------------------------------------------------------------------
# 재원별 인출 — 퇴직금이 섞인 계좌, 55세 전 해지 (R-04·R-05·R-06·R-09·R-10)
# ---------------------------------------------------------------------------
FUND_NAME = {'free': '① 세액공제 안 받은 돈', 'retire': '② 퇴직금(이연퇴직소득)', 'credit': '③ 세액공제 받은 돈·운용수익'}


def _reduction(m):
    """연금실제수령연차 → (퇴직소득세에 곱할 비율, 설명). doc39 표."""
    if m <= 10:
        return 0.7, '30% 감면 — 연금실제수령연차 1~10년차'
    if m <= 20:
        return 0.6, '40% 감면 — 연금실제수령연차 11~20년차'
    return 0.5, '50% 감면 — 연금실제수령연차 21년차~'


def _alloc(sources, w, lim):
    """인출 w 를 법정 순서(①→②→③)로 재원에 나누고 연금수령한도 lim(None=제한 없음) 안/밖을 가른다.
    과세제외금액도 한도 안에서 먼저 빠지는 것으로 센다. → ([(재원, 인출, 한도 안, 한도 밖)], 잔액 부족분)"""
    rows, rem, room = [], w, (float('inf') if lim is None else lim)
    for kind, amt in sources:
        take = min(rem, amt)
        if take <= 0:
            continue
        inside = min(take, max(0.0, room))
        rows.append((kind, take, inside, take - inside))
        room -= inside
        rem -= take
    return rows, max(0.0, rem)


def _row_tax(kind, inside, over, eff, red, rate, lines, early):
    """재원 한 줄의 세금. 금액을 못 정하면 None 을 돌려준다(설명 줄은 그래도 쓴다)."""
    name = FUND_NAME[kind]
    if kind == 'free':
        lines.append(f'{name} {won(inside + over)}: 비과세(한도를 넘어도 과세 없음)')
        return 0.0
    if kind == 'retire':
        tax, parts = 0.0, []
        if inside:
            if eff is not None:
                t = inside * eff / 100 * red[0]
                # '퇴직소득세의 70%(30% 감면(…))'를 '70% 감면'으로 옮겨 쓴 답이 있었다 — '…%만 냄'으로 분명히
                parts.append(f'한도 안 {won(inside)} = 연금수령 → 퇴직소득세의 {round(red[0] * 100)}%만 냄({red[1]}): '
                             f'{won(inside)} × {eff:g}% × {round(red[0] * 100)}% = {won(t)}')
                tax += t
            else:
                parts.append(f'한도 안 {won(inside)} = 연금수령 → 원래 퇴직소득세의 {round(red[0] * 100)}%만 냄({red[1]})')
                tax = None
        if over:
            what = '55세 전·해지 인출이라 연금외수령' if early else '한도 초과분 = 연금외수령'
            if eff is not None:
                t = over * eff / 100
                parts.append(f'{what} {won(over)} → 퇴직소득세 100%(감면 없음): {won(over)} × {eff:g}% = {won(t)}')
                if tax is not None:
                    tax += t
            else:
                parts.append(f'{what} {won(over)} → 퇴직소득세 100%(감면 없음)')
                tax = None
        lines.append(f'{name} {won(inside + over)}: ' + ' / '.join(parts))
        return tax
    # credit
    tax, parts = 0.0, []
    if inside:
        if inside > 1500:
            t = inside * 0.165
            parts.append(f'한도 안 {won(inside)} = 연금수령이지만 연 1,500만 원 초과 → 전액 16.5% 분리과세(또는 종합과세) '
                         f'{won(inside)} × 16.5% = {won(t)}')
            tax += t
        elif rate:
            t = inside * rate[0] / 100
            parts.append(f'한도 안 {won(inside)} = 연금수령 → 연금소득세 {pct(rate[0])}({rate[1]}): {won(t)}')
            tax += t
        else:
            parts.append(f'한도 안 {won(inside)} = 연금수령 → 연금소득세 5.5~3.3%(나이에 따라)')
            tax = None
    if over:
        t = over * 0.165
        what = '55세 전·해지 인출이라 연금외수령' if early else '한도 초과분 = 연금외수령'
        parts.append(f'{what} {won(over)} → 기타소득세 16.5%: {won(over)} × 16.5% = {won(t)}')
        if tax is not None:
            tax += t
    lines.append(f'{name} {won(inside + over)}: ' + ' / '.join(parts))
    return tax


def _year_tax(sources, w, lim, eff, m, age, early):
    """한 해 인출의 재원별 세금 → (줄들, 합계 또는 None, 배분)."""
    lines = []
    rows, short = _alloc(sources, w, None if early is False and lim is None else (0.0 if early else lim))
    total = 0.0
    red = _reduction(m or 1)
    rate = rate_for_age(age)
    for kind, take, inside, over in rows:
        t = _row_tax(kind, inside, over, eff, red, rate, lines, early)
        total = None if t is None or total is None else total + t
    return lines, total, rows, short


def _irp_early(q, acct):
    """55세 전 인출 금액을 계산할 때 함께 싣는 규칙 → (줄들, 원문 키들).
    부득이한 사유(세법, 요양 3개월)는 늘 — 없으면 답이 근퇴법 표의 '6개월 이상 요양'을 부득이한 사유로 옮겨 적었다(C10 대화 실측).
    IRP 면 인출 요건(doc20)과, 주택·전세 말이 있으면 '부득이한 사유가 아니라 세금 그대로'(doc20)."""
    lines = ['세법상 부득이한 사유(가입자의 사망·해외이주·천재지변·가입자 또는 부양가족의 3개월 이상 요양·파산 또는 개인회생 등)로 '
             '인출하면 기타소득세 대신 연금소득세 5.5~3.3% — 사유가 확인된 날부터 6개월 안에 서류를 내야 한다']
    keys = ['unavoidable', 'unavoidable_care', 'unavoidable_doc']
    if acct != 'IRP':
        return lines, keys
    lines.insert(0, 'IRP는 근퇴법상 중도인출 사유(무주택자 주택 구입·전세보증금 등 법으로 정한 사유)가 있어야 55세 전에 '
                    '인출할 수 있다 — 사유가 없으면 중도인출이 안 된다(연금저축은 사유 없이 인출 가능)')
    keys += ['irp_reason_req', 'irp_reasons', 'savings_withdraw']
    if re.search(r'주택|전세|집\s*(?:사|구입|마련)', q):
        lines.append('주택 구입·전세보증금은 IRP 중도인출 사유지만 세법상 부득이한 사유는 아니어서 세금은 그대로다 — '
                     '세액공제 받은 돈·수익은 기타소득세 16.5%')
        keys.append('house_not_unavoidable')
    return lines, keys


_CANCEL = re.compile(_HAEJI + r'|해약|' + _BREAK)


def _cancel_check(q, acct):
    """해지 질문이면 '해지 신청 전 확인' 줄 → (줄들, 원문 키들).
    연금저축은 해지를 신청할 때 과세재원이 확정되고 신청 뒤에는 바꿀 수 없다(doc5) — 공제 안 받은 돈은 신청 전에 확인해야 한다.
    IRP 는 재원확정(doc19)으로 공제 안 받은 돈을 과세제외한다. doc19 의 '재원확정: 내점만 가능'은 MAPS 개시/해지 화면의
    공제확인서 발급번호 입력칸·FAQ 와 어긋날 수 있어 싣지 않는다(본선_작업정리/12 D-4)."""
    if not _CANCEL.search(q or ''):
        return [], []
    if acct == 'IRP':
        return (['해지 신청 전 확인: IRP는 재원확정으로 금융회사의 과세대상금액을 국세청 소득·세액공제합계액과 맞춰 '
                 '세액공제 안 받은 돈을 과세에서 뺀다 — 필요 서류는 연금보험료등 소득·세액공제확인서(국세청 자료)'],
                ['irp_fix', 'irp_fix_doc'])
    return (['해지 신청 전 확인: 연금저축은 해지를 신청할 때 과세재원이 확정돼 국세청에 통보되고, 신청 뒤에는 과세재원을 '
             '바꾸거나 그에 따라 환급받을 수 없다(해지 뒤 전년도 납입금을 공제받지 않았음을 증빙하면 예외) — '
             '세액공제 안 받은 납입금이 있으면 해지 신청 전에 확인해 둔다'],
            ['cancel_fix', 'cancel_fix_exc'])


def by_source(p, q):
    """재원별 인출 세금. 퇴직금이 섞였거나(재원 언급), 55세 전·해지 인출일 때.
    필요한 값이 빠지면 금액 대신 규칙과 '빠진 정보'(되묻기용)를 담은 블록을 낸다."""
    w = p['withdraw']
    if w is None:
        return None
    age = p['age'] if isinstance(p['age'], int) else None
    band_age = p['age'] if isinstance(p['age'], tuple) and p['age'][1] >= 60 else age   # '60대'는 55세 이상 구간에 온전히 든다
    early = _early_eff(p)
    mentioned = p['fund_mentioned']
    if p['unavoidable'] and (early or _late_cancel(p) or 'retire' in mentioned or p['fund']):
        return unavoidable_rule(p, q, early)
    if _late_cancel(p) and not (_started(q) is True and p['balance'] is not None and p['year_n']):
        # 55세 이후 해지·중도인출 — 개시 여부·연금수령한도를 모르면 '55세 전·해지'로 계산하지 않고 규칙과 되묻기(9차 검토 901).
        # 연금을 받는 중이고 평가액·연차를 알면 아래(퇴직금 재원) 또는 withdraw_limit(③ 재원)이 한도로 계산한다(doc1 해지 규칙과 같은 식)
        return late_cancel_rule(p, q)
    if not early and 'retire' not in mentioned and not p['fund']:
        return None                       # 퇴직금 얘기가 없는 55세 이후 인출은 withdraw_limit(③ 재원 기준)이 맡는다
    if early and not p['early'] and not p.get('early_age') and _age_cross(p, q):
        # '54살인데 내년에 빼려고요', '52살 … 3년 뒤쯤 5천 꺼내야' — 꺼낼 때 55세 전인지 후인지 모른다. 지금 나이로 55세 전 연금외수령
        # (퇴직소득세 100%)이라고 단정해 150만 원을 냈다(만 없는 금액을 읽게 되자 드러남). 두 경우의 규칙만 싣고 숫자는 내지 않는다
        acct = 'IRP' if re.search(r'IRP|개인형', q, re.I) else '연금저축' if '연금저축' in q else '연금계좌'
        lines = [f'입력: {acct} 인출 {won(w)}, 지금 나이 {age}세 — 나중에 꺼내는 돈이라 그때 만 55세 전인지 후인지 질문만으로는 알 수 없음',
                 '꺼낼 때 만 55세 전이면 연금외수령(R-04): 재원별로 ① 세액공제 안 받은 돈 비과세 ② 퇴직금 퇴직소득세 100% '
                 '③ 세액공제 받은 돈·수익 기타소득세 16.5%',
                 '만 55세 이후 연금수령한도 안에서 받으면 연금수령: 한도 안에서 받은 퇴직금은 원래 퇴직소득세의 70%(실제수령 10년차 이하, '
                 '11~20년차 60%, 21년차~ 50%), 한도를 넘긴 퇴직금은 퇴직소득세 100%, 한도를 넘긴 ③ 재원은 기타소득세 16.5%(R-09·R-10)',
                 '인출 순서(R-06): ① 세액공제 안 받은 돈 → ② 퇴직금 → ③ 세액공제 받은 돈·수익 — 고객이 고를 수 없다']
        return _block('doc39.txt', '재원별 인출 세금(규칙)', lines,
                      ['pension_req', 'order', 'early_credit', 'early_retire', 'limit_formula', 'retire_in', 'retire_over', 'over_limit'],
                      numbers=False, needs=['꺼낼 때 나이(만 55세가 지났는지 — 55세 전이면 연금외수령)'])

    f = dict(p['fund'])
    B = p['balance']
    keys = ['order', 'free'] if 'free' in mentioned or f.get('free') else ['order']
    needs, assume = [], []
    if p.get('cancel_all'):
        assume.append(f"'해지'를 계좌 전부를 꺼내는 것으로 봄 — 인출 {won(w)}")
    acct = 'IRP' if re.search(r'IRP|개인형', q, re.I) else '연금저축' if '연금저축' in q else '연금계좌'
    # 재원 구성 채우기 — 평가액과 두 재원을 알면 나머지 하나는 뺄셈으로
    if B is None and len(f) >= 2 and all(k in f for k in mentioned):
        B = sum(f.values())
        assume.append(f'평가액 = 재원 합계 {won(B)}')
    elif B is None and set(f) == {'retire'} and mentioned == {'retire'} and not any(x['role'] is None for x in p['spans']):
        # 'IRP에 퇴직금 1억 원 들어 있어요' — 다른 재원 얘기가 없으면 평가액 = 퇴직금.
        # 쓰임을 모르는 금액이 따로 있으면 다른 재원일 수 있다 — '퇴직금 2억이랑 위로금 1억 … 위로금은 연금저축에'의 계좌 돈은
        # 위로금이다(stab 2271: 만 없는 '5천'을 읽게 되자 2억을 평가액으로 보아 150만 원을 냈다 — 맞는 값은 위로금 기준)
        B = f['retire']
        f['credit'] = 0.0
        assume.append(f'평가액 = 퇴직금 {won(B)}(다른 재원 없음)')
    if B is not None:
        known = sum(f.values())
        missing = [k for k in ('retire', 'credit') if k in mentioned and k not in f]
        if len(missing) == 1 and B - known >= 0:
            f[missing[0]] = B - known
            if missing[0] == 'credit' and known:
                assume.append(f'{FUND_NAME["credit"]} = 평가액 − 나머지 재원 = {won(B - known)}')
        gap = B - sum(v for v in f.values() if v)
        if gap > 0 and f.get('credit') and 'free' not in f and 'free' not in mentioned and 'retire' not in mentioned \
                and w > f['credit']:
            # '2,000만 원 있고 1,200만 원은 공제받았어요' — 나머지 800만 원이 공제 안 받은 돈인지 운용수익(③)인지 질문에 없다.
            # 공제 안 받은 돈이 없다고 보면 인출이 재원 합계를 넘어 '잔액보다 많음'으로 계산했다 — 숫자 없이 되묻는다
            needs.append(f'나머지 {won(gap)} 중 세액공제 안 받은 납입금(비과세 원금) 금액 — 인출 순서상 가장 먼저 빠져 세금이 달라짐')
            f['free'] = None
    elif f.get('credit') and 'free' not in f and 'free' not in mentioned and 'retire' not in mentioned and w > f['credit']:
        # 평가액 없이 '1,000만 원 빼는데 700만 원은 공제받은 거고' — 나머지가 공제 안 받은 돈인지 수익(③)인지 모른다. 공제받은 금액을
        # 계좌 전체로 보면 나머지에 세금을 매기지 않아 115만 5천 원을 냈다(10-15 검토 — 수익이면 165만 원). 55세 전이면 재원을
        # 모를 때처럼 전부 ③으로 본 최대 세금과 되묻기, 55세 이후면 규칙만
        if early:
            del f['credit']
        else:
            needs.append(f'나머지 {won(w - f["credit"])} 중 세액공제 안 받은 납입금(비과세 원금) 금액 — 인출 순서상 가장 먼저 빠져 '
                         '세금이 달라짐')
            f['free'] = None
    free_known = 'free' in f
    if early and free_known and 'retire' not in mentioned and 'credit' not in f:
        # '공제 안 받은 돈이 500만 원 있어요, 2,000만 원 해지하면' — 나머지는 ③ 재원으로 본다
        f['credit'] = max(0.0, (B if B is not None else w) - f['free'])
        assume.append(f'나머지 {won(f["credit"])}은 세액공제 받은 돈·운용수익으로 봄')
    elif not early and f.get('free') and 'credit' not in f and 'credit' not in mentioned and \
            w > f['free'] + (f.get('retire') or 0):
        # 55세 이후 '평가액 8천, 그중 공제 안 받은 돈 1천, 2년차, 2천만 원 빼면' — ③ 금액을 몰라 숫자 없이 규칙만 내는데 빠진 정보가
        # 비어 있었다. 온톨로지 경로(③ 금액 되묻기)와 같게 ③ 금액을 묻는다(숫자는 짐작하지 않는다)
        needs.append('세액공제 받은 돈·수익 금액 — 인출이 세액공제 안 받은 돈보다 많아 그다음 재원 금액이 필요')
    if 'free' in mentioned and 'free' not in f and not early:
        needs.append('세액공제 안 받은 돈(비과세 원금) 금액 — 인출 순서상 가장 먼저 빠져 세금 계산이 달라짐')
        f['free'] = None                  # 금액을 모르면 배분 순서를 정할 수 없다 → 규칙만
    if 'free' not in f:
        f['free'] = 0.0
        if 'free' not in mentioned and (f.get('retire') or f.get('credit')):
            assume.append('세액공제 안 받은 돈은 없다고 봄')
    if 'retire' not in f and 'retire' not in mentioned and (free_known or f.get('credit')):
        f['retire'] = 0.0                 # 퇴직금 얘기가 없는 연금저축 해지
    if not early and 'credit' not in f and f.get('retire') is not None and B is None and w <= f['retire'] + (f['free'] or 0):
        f['credit'] = 0.0                 # 인출이 퇴직금 안에서 끝나면 ③ 금액은 몰라도 된다
    if early and not free_known and not f.get('retire') and not f.get('credit'):
        irp_l, irp_k = _irp_early(q, acct)
        if p.get('emigrate_proof'):
            irp_l, irp_k = irp_l + [_STAY_LINE], irp_k + ['emigrate_proof', 'emigrate_doc']   # 장기체류는 해외이주가 아니다(908)
        cl, ck = _cancel_check(q, acct)
        irp_l, irp_k = irp_l + cl, irp_k + ck
        if 'retire' in mentioned:
            # 퇴직금이 섞였으면 퇴직소득세가 개인마다 달라 '최대'도 말할 수 없다
            lines = [f'입력: {acct} {won(w)} 해지·인출' + (f', 나이 {age}세' if age else ''),
                     '55세 전 인출·해지는 연금외수령(R-04) — ① 세액공제 안 받은 돈 비과세, ② 퇴직금 퇴직소득세 100%, '
                     '③ 세액공제 받은 돈·수익 기타소득세 16.5% (인출 순서대로 빠짐)']
            pk = []
            if p.get('plan_moved'):
                # 'DC형에 … IRP로 받아서 깨면' — 옮긴 돈이 퇴직급여라는 것을 밝힌다(16.5%로 읽은 답을 막게, stab 2261)
                lines.append('DC·DB 같은 퇴직연금에서 IRP로 옮긴 퇴직급여는 계좌 안에서 ② 퇴직금(이연퇴직소득) 재원이다 — 55세 전에 '
                             '해지·인출하면 퇴직소득세 100%(감면 없음)이고 기타소득세 16.5%가 아니다. 세액은 퇴직소득세(퇴직소득 '
                             '원천징수영수증)에 달려 여기서 계산하지 않음')
                pk = ['dc_irp_route']
                if _DC.search(q):
                    lines.append('DC에 본인이 추가로 넣은 돈(가입자부담금)이 있으면 그 몫이 IRP로 옮겨질 때 어느 재원으로 나뉘는지는 '
                                 '받은 문서에 없어 상담에서 확인해야 한다')
            lines += irp_l
            return _block('doc39.txt', '55세 전·해지 인출 세금(규칙)', lines,
                          ['pension_req', 'order', 'free', 'early_credit', 'early_retire'] + pk + irp_k, numbers=False,
                          needs=['재원별 금액(세액공제 안 받은 돈·퇴직금·세액공제 받은 돈과 수익)',
                                 '퇴직소득세(원천징수영수증의 퇴직소득세 또는 실효세율)'])
        # '연금저축 2,000만 원 해지' — 재원 구성을 모르면 전부 ③으로 본 값이 최대 세금이다
        upper = w * 0.165
        lines = [f'입력: {acct} {won(w)} 해지·인출' + (f', 나이 {age}세' if age else ''),
                 # '넣은 돈 전부가 아니라'를 '일부에만 16.5%'로 옮겨 쓴 답이 3회 모두였다 — 모두 공제받았으면 전부 과세된다
                 '55세 전 인출·해지는 연금수령이 아니라 연금외수령이다(R-04). 세금은 재원별로 정해진다(R-06·R-10) — '
                 '비과세는 세액공제 안 받은 원금뿐이고, 운용수익은 세액공제를 받았는지와 상관없이 기타소득세 16.5%',
                 f'{FUND_NAME["free"]}: 비과세 / {FUND_NAME["credit"]}: 기타소득세 16.5% / {FUND_NAME["retire"]}: 퇴직소득세 100%',
                 f'넣은 돈을 모두 세액공제 받았다면 {won(w)} 전부가 16.5% 대상(최대): {won(w)} × 16.5% = {won(upper)}',
                 f'세액공제 안 받은 돈이 X원 있으면 세금 = ({won(w)} − X) × 16.5% — 예: 500만 원이면 '
                 f'{won(w - 500)} × 16.5% = {won((w - 500) * 0.165)}' if w > 500 else
                 '세액공제 안 받은 돈이 있으면 그만큼은 세금이 없다'] + irp_l
        needs.insert(0, '세액공제 안 받은 납입금(비과세 원금) 금액 — 연말정산 때 공제받지 않은 납입액')
        return _block('doc39.txt', '55세 전·해지 인출 세금', lines,
                      ['pension_req', 'order', 'free', 'early_credit', 'early_retire', 'early_out'] + irp_k,
                      key_figure=won(upper), needs=needs, figures=[won(upper)])
    # 연금수령한도
    n = p['year_n']
    lim = None
    # 인출이 공제 안 받은 돈 안에서 끝나면 한도·연차와 상관없이 비과세다(doc39: 한도를 넘어도 과세 없음) — 연차를 되물을 까닭이 없다
    # (stab 2231: '57살 … 1,800은 공제 안 받은 돈 … 1,000만 원만 빼면'에 블록 없이 모델이 16.5%를 지어낼 수 있었다)
    all_free = bool(f.get('free')) and w <= f['free']
    if not early and not all_free:
        if n is None:
            needs.append('연금수령연차(연금 개시가 가능해진 해부터 몇 년째인지) — 한도 계산에 필요')
            if B is None:
                needs.append('연금계좌 평가액(올해 1월 1일 또는 개시일 기준) — 한도 계산에 필요')
        elif n <= 10:
            if B is None:
                needs.append('연금계좌 평가액(올해 1월 1일 또는 개시일 기준) — 한도 계산에 필요')
            else:
                lim = B / (11 - n) * 1.2
        keys += ['pension_req', 'no_period_req', 'limit_formula']
        if p['year_assumed']:
            keys += ['limit_year1', 'year_count']
    eff = p['retire_eff']
    # 퇴직소득세 ÷ 퇴직금 — 퇴직 쪽 말 옆에 쓰임을 모르는 금액이 따로 있으면 그 퇴직소득세가 어느 돈의 것인지 모른다('퇴직금 2억이랑
    # 위로금 1억 … 위로금 퇴직소득세는 600' — 600 ÷ 2억 = 3%로 150만 원을 냈다, stab 2271). 실효세율을 짐작하지 않고 되묻는다
    # '제가 넣은 돈 1천'처럼 본인 돈이라고 밝힌 금액은 퇴직 쪽 돈이 아니다
    own = re.compile(r'(?:제가|내가|본인이|직접)\s*(?:[가-힣]+\s*){0,3}?(?:넣은|부은|납입한)\s*(?:돈|금액)\s*(?:이|은|는|도)?\s*$'
                     r'|(?:본인|개인|가입자)\s*(?:부담금?|납입금?|돈)\s*(?:이|은|는|도)?\s*$|(?<![가-힣])(?:제|내)\s*돈\s*(?:이|은|는|도)?\s*$')
    if eff is None and p['rtax'] is not None and f.get('retire') and \
            not any(x['role'] is None and x['src'] == 'retire' and not own.search(q[max(0, x['s'] - 24):x['s']]) for x in p['spans']):
        eff = p['rtax'] / f['retire'] * 100
    if f.get('retire') is None and 'retire' in mentioned:
        needs.append('퇴직금(이연퇴직소득) 금액')
    if 'credit' in mentioned and f.get('credit') is None and not (f.get('retire') is not None and w <= f['retire'] + (f['free'] or 0)):
        needs.append('세액공제 받은 돈·수익 금액')
    retire_used = f.get('retire') and w > (f.get('free') or 0)
    if eff is None and ('retire' in mentioned or f.get('retire')) and (retire_used or f.get('retire') is None):
        needs.append('퇴직소득세(원천징수영수증의 퇴직소득세 또는 실효세율)')
    m = p['actual_n']
    if f.get('retire') and not early:
        keys += ['retire_years', 'retire_over'] + (['actual_year'] if m else [])
        if m is None:
            m = 1 if p['year_assumed'] or n == 1 else None
            if m is None:
                m = 1
                assume.append('연금 실제 수령 10년차 이하(퇴직소득세 30% 감면)')
    if early:
        keys += ['pension_req', 'early_credit', 'early_retire']
    elif f.get('credit') or 'credit' in mentioned:
        keys += ['limit_rates', 'over_limit']
    head = [f'입력: {acct} 인출 {won(w)}' + (f', 나이 {age}세' if age else '')
            + (f', 평가액 {won(B)}' if B is not None else '')
            + ''.join(f', {FUND_NAME[k].split(" ", 1)[1]} {won(f[k])}' for k in ('free', 'retire', 'credit')
                      if f.get(k)) + (f', 퇴직소득세 실효세율 {eff:g}%' if eff is not None else '')]
    if p.get('plan_moved') and f.get('retire') is not None:
        # 'DC형에 3,400만 원 … IRP로 받아서 깨면' — 평가액을 퇴직금 재원으로 본 까닭을 밝힌다(stab 2261: 16.5% 561만 원으로 답했다)
        head.append('DC·DB 같은 퇴직연금에서 IRP로 옮긴 퇴직급여는 계좌 안에서 ② 퇴직금(이연퇴직소득) 재원이다 — 연금외수령이면 '
                    '퇴직소득세 100%이고 기타소득세 16.5%가 아니다')
        keys.append('dc_irp_route')
        if _DC.search(q):
            head.append('DC에 본인이 추가로 넣은 돈(가입자부담금)이 있으면 그 몫이 IRP로 옮겨질 때 어느 재원으로 나뉘는지는 '
                        '받은 문서에 없어 상담에서 확인해야 한다')
    if early:
        head.append('55세 전 인출·해지 → 전액 연금외수령(R-04): 재원별로 ① 비과세 ② 퇴직소득세 100% ③ 기타소득세 16.5%')
    else:
        req = '만 55세 이상' + (' ✓' if band_age is not None and (isinstance(band_age, tuple) or band_age >= 55)
                               else '(나이 확인 필요)')
        if band_age is None and not p['future'] and not all_free:
            needs.append('나이(만 55세 이상인지 — 연금수령 요건)')
        req += ' · 퇴직금이 있어 가입기간 5년 요건 없음' if f.get('retire') or 'retire' in mentioned else ' · 가입 5년 이상'
        head.append(f'연금수령 요건(R-04): {req}')
        if n is not None and n >= 11:
            head.append('연금수령연차 11년차부터는 연금수령한도가 없다')
        elif lim is not None:
            head.append(f'연금수령한도(R-05) = {won(B)} ÷ (11 − {n}) × 120% = {won(lim)}'
                        + (' (올해가 연금 개시 가능한 첫해 = 1년차라고 봄)' if p['year_assumed'] else ''))
            if p['year_assumed']:
                assume.append('올해가 연금수령연차 1년차(2013.3.1 이후 가입, 올해 처음 수령 요건 충족)')
    # 배분 순서가 모두 정해져야 금액을 낸다
    order_known = all(f.get(k) is not None for k in ('free', 'retire')) and \
        (f.get('credit') is not None or w <= (f.get('free') or 0) + (f.get('retire') or 0))
    if not order_known or (not early and lim is None and not (n is not None and n >= 11) and not all_free):
        lines = head + ['인출 순서(R-06): ① 세액공제 안 받은 돈 → ② 퇴직금 → ③ 세액공제 받은 돈·수익 — 고객이 고를 수 없다',
                        '한도 안에서 받은 퇴직금은 원래 퇴직소득세의 70%(실제수령 10년차 이하, 11~20년차 60%, 21년차~ 50%), '
                        '한도를 넘긴 퇴직금은 퇴직소득세 100%, 한도를 넘긴 ③ 재원은 기타소득세 16.5%(R-09·R-10)']
        if f.get('retire') is None and 'retire' in mentioned:
            lines.append(f'인출 {won(w)}이 퇴직금보다 적으면 전부 퇴직금에서 나간다(공제 안 받은 돈이 없을 때)')
        if early:
            cl, ck = _cancel_check(q, acct)
            lines, keys = lines + cl, keys + ck
        return _block('doc39.txt', '재원별 인출 세금(규칙)', lines,
                      list(dict.fromkeys(keys + ['retire_in', 'retire_over', 'over_limit'])), numbers=False,
                      needs=needs, assume=assume)
    srcs = [('free', f.get('free') or 0.0), ('retire', f.get('retire') or 0.0), ('credit', f.get('credit') or 0.0)]
    if band_age is None and not early:
        assume.append('만 55세 이상으로 봄(연금수령 요건)')
    lines, total, rows, short = _year_tax(srcs, w, lim, eff, m, band_age, early)
    lines = head + [
        '인출 순서(R-06): ' + ' → '.join(f'{FUND_NAME[k]} {won(t)}' for k, t, _, _ in rows)
        + (f' (계좌 잔액보다 {won(short)} 많음)' if short else '')] + lines
    figures = []
    key = None
    if total is not None:
        key = won(total)
        figures.append(key)
        lines.append(f'올해 예상 세금 합계 = {key}')
    # 나눠 받기 비교 — 한도를 넘는 인출이면 '올해 한도까지 + 내년 나머지'를 나란히(고르지 않고 비교만).
    # 한도를 넘는 몫이 비과세 원금뿐이면 나눠도 세금이 같아(0원 + 0원) 비교가 뜻이 없다(stab 2238)
    over_sum = sum(o for k, _, _, o in rows if k != 'free')
    if not early and lim is not None and over_sum > 0 and B is not None and total is not None:
        rest = w - lim
        n2 = n + 1
        left = [(k, max(0.0, a - next((t for kk, t, _, _ in _alloc(srcs, lim, None)[0] if kk == k), 0.0))) for k, a in srcs]
        lim2 = None if n2 >= 11 else (B - lim) / (11 - n2) * 1.2
        l1, t1, _, _ = _year_tax(srcs, lim, lim, eff, m, age, False)
        l2, t2, _, _ = _year_tax(left, rest, lim2, eff, (m or 1) + 1, age + 1 if age else None, False)
        if t1 is not None and t2 is not None:
            lines.append(f'비교(나눠 받기): 올해 한도까지 {won(lim)} → {won(t1)} + 내년 나머지 {won(rest)}'
                         # 내년 한도 값만 적자 '1억 ÷ (11 − 2) × 120%'처럼 맞지 않는 식을 지어낸 답이 있었다 — 식을 함께
                         + (f'(내년 한도 = ({won(B)} − {won(lim)}) ÷ (11 − {n2}) × 120% = {won(lim2)} 안, '
                            f'내년 평가액은 올해 인출만 뺀 값)' if lim2 is not None and rest <= lim2 else '')
                         + f' → {won(t2)} = 합계 {won(t1 + t2)}  ·  올해 한꺼번에 {won(w)} → {key}')
            figures += [won(t1), won(t2), won(t1 + t2)]
            assume.append('내년 평가액은 수익률 0%로 봄(올해 인출만 뺌)')
            if re.search(r'한도까지만|나눠\s*(?:받|빼)|나머지는\s*내년|내년에\s*(?:받|빼)', q):
                # 고객이 나눠 받는 경우를 물었다 — 핵심 금액은 나눠 받기 합계
                key = won(t1 + t2)
                lines.append(f'질문한 방식(올해 한도까지 + 내년 나머지)의 두 해 세금 합계 = {key} '
                             f'(한꺼번에 받을 때보다 {won(total - t1 - t2)} 적음)')
    if lim is not None:
        figures.append(won(lim))
    keys += ['retire_in'] if f.get('retire') else []
    if early:
        cl, ck = _cancel_check(q, acct)
        lines, keys = lines + cl, keys + ck
    return _block('doc39.txt', '재원별 인출 세금', lines, list(dict.fromkeys(keys)), numbers=True,
                  key_figure=key, needs=needs, assume=assume, figures=figures)


# ---------------------------------------------------------------------------
# 공용 계산 함수 — 질문 문장 없이 숫자로 부른다(알림 alerts.py · DIY 설계 diy.py · 시연 화면).
# 질문 경로(compute)와 같은 규칙·같은 식을 쓴다. 금액 단위는 모두 '만 원'.
# ---------------------------------------------------------------------------
def credit_rate(income, kind='총급여'):
    """세액공제율(%) — R-02. kind: '총급여' 또는 '종합소득'."""
    return 16.5 if income <= (5500 if kind == '총급여' else 4500) else 13.2


def eligible(savings, irp):
    """세액공제 대상 금액 — R-01. 연금저축 600, 합산 900."""
    return min(min(savings, 600) + irp, 900)


def isa_extra(isa_amount):
    """ISA 만기 전환 추가 공제 대상 — R-03."""
    return min(isa_amount * 0.1, 300)


def pension_limit(balance, year_n):
    """연금수령한도 — R-05. 11년차부터 None(한도 없음)."""
    return None if year_n >= 11 else balance / (11 - year_n) * 1.2


def age_rate(age):
    """연금소득세율(%) — R-07. 55세 미만이면 None."""
    r = rate_for_age(age)
    return r[0] if r else None


def withdraw_tax(w, free=0.0, retire=0.0, credit=0.0, balance=None, year_n=None, eff=None, actual_n=None,
                 age=None, early=False):
    """한 해 인출의 재원별 세금 — R-04·R-05·R-06·R-09·R-10.
    → {'limit', 'rows': [(재원, 인출, 한도 안, 한도 밖)], 'total'(eff 가 필요한데 없으면 None), 'lines', 'short'}"""
    lim = None
    if not early and balance is not None and year_n is not None:
        lim = pension_limit(balance, year_n)
    lines, total, rows, short = _year_tax([('free', free), ('retire', retire), ('credit', credit)], w, lim, eff,
                                          actual_n or 1, age, early)
    return {'limit': lim, 'rows': rows, 'total': total, 'lines': lines, 'short': short}


def restate_split(p):
    """재원별 인출 계산의 조건을 모두 담아 '올해 한도까지만 받고 나머지는 내년에' 를 묻는 한 문장.
    다음 행동 버튼이 이 문장을 그대로 보낸다 — 앞 대화 재작성이 금액을 잃거나 지어내는 일을 피한다."""
    f = p.get('fund') or {}
    parts = []
    if isinstance(p.get('age'), int):
        parts.append(f'만 {p["age"]}세')
    if p.get('balance') is not None:
        parts.append(f'IRP 평가액 {won(p["balance"])}')
    names = {'retire': '퇴직금', 'credit': '세액공제 받은 돈과 수익', 'free': '세액공제 안 받은 돈'}
    for k in ('retire', 'credit', 'free'):
        if f.get(k):
            parts.append(f'{names[k]} {won(f[k])}')
    if p.get('retire_eff') is not None:
        parts.append(f'퇴직소득세 실효세율 {p["retire_eff"]:g}%')
    elif p.get('rtax') is not None:
        parts.append(f'퇴직소득세 {won(p["rtax"])}')
    if p.get('year_n'):
        parts.append(f'연금수령연차 {p["year_n"]}년차')
    w = p.get('withdraw')
    if not w:
        return ''
    return (', '.join(parts) + f'예요. 올해 {won(w)}을 한꺼번에 빼지 않고, 올해는 연금수령한도까지만 받고 나머지는 '
            '내년에 받으면 세금이 어떻게 달라져요?')


def unavoidable_rule(p, q, early=None):
    """부득이한 사유 인출(R-11) — 금액 없이 규칙만. 사유로 인정받지 못할 때(연금외수령)의 규칙도 함께 싣는다.
    요양 기준은 세법상 3개월 이상이다(doc1 부득이한 사유 목록, doc20 표 주석) — 6개월은 근퇴법 중도인출(R-13) 기준."""
    if early is None:
        early = _early_eff(p)
    lines = ['세법상 부득이한 사유(가입자의 사망·해외이주·천재지변·가입자 또는 부양가족의 3개월 이상 요양·파산 또는 개인회생 등)로 '
             '인출하면 55세 전이나 중도 해지여도 연금수령으로 보아 세액공제 받은 돈·수익에 나이별 연금소득세 5.5%(69세 이하)·'
             '4.4%(70~79세)·3.3%(80세 이상) 분리과세 — 연 1,500만 원을 넘어도 다른 소득과 합산하지 않는다',
             '사유가 확인된 날부터 6개월 안에 확인 서류를 금융회사에 내야 한다 — 놓치거나 서류가 없으면 일반 인출로 기타소득세가 부과될 수 있다']
    keys = ['unavoidable', 'unavoidable_care', 'unavoidable_sep', 'unavoidable_doc']
    needs = []
    if p.get('emigrate_proof'):
        # '영주권 받아서 IRP 해지' — 영주권 취득·장기체류만으로는 부득이한 사유가 아니다(doc20). 해외이주로 단정하지 않고
        # 해외이주신고확인서가 있는지부터 묻는다(9차 검토 908)
        lines.insert(0, '단순 장기체류나 영주권 취득만으로는 세법상 부득이한 사유(해외이주)로 인정되지 않는다 — 해외로 옮겨 가도 '
                        '「해외이주법」에 따른 해외이주신고확인서가 있어야 해외이주로 인정받는다. 확인서가 없으면 아래 부득이한 '
                        '사유의 세금이 아니라 일반 해지·인출 세금이다')
        keys += ['emigrate_proof', 'emigrate_doc']
        needs.append('「해외이주법」에 따른 해외이주신고확인서가 있는지(해외이주 신고를 했는지) — 영주권 취득·장기체류만으로는 '
                     '부득이한 사유가 아님')
    if re.search(r'요양|입원|치료|질병|부상|아파|투병', q):
        lines.append('요양은 연금소득세 적용에 한도가 있다(200만 원 + 의료실비 + 휴직 월수 × 150만 원)')
    if p.get('emigrate'):
        lines.append(('해외이주신고확인서로 해외이주가 인정되면' if p.get('emigrate_proof') else '해외이주(이민)')
                     + ': 근퇴법상 IRP 중도인출 사유는 아니어서 IRP는 부분 인출이 아닌 전액 해지만 가능하지만, '
                     '세법상 부득이한 사유에는 해당한다. 「해외이주법」에 따른 해외이주신고확인서가 필요하고, '
                     '단순 장기체류나 영주권 취득만으로는 인정되지 않는다')
        lines.append('계좌에 퇴직금(이연퇴직소득)이 있으면 퇴직금 입금일부터 3년이 지나야 퇴직금도 연금수령으로 보아 퇴직소득세 30% 감면 — '
                     '3년이 안 됐으면 납입금·운용수익 부분만 연금소득세 저율과세')
        keys += ['unavoidable_emigrate', 'emigrate_proof', 'emigrate_doc', 'emigrate_retire']
    else:
        lines.append('퇴직금 재원의 부득이한 사유 인출 과세는 문서마다 조건이 달라(입금 후 3년 등) 금액을 계산하지 않음')
    if early:
        # 사유로 인정받지 못하면 — '그냥 깨면 16.5% 다 떼이죠?'에 답하려면 이 규칙도 있어야 한다
        lines.append('부득이한 사유로 인정받지 못하면 55세 전 인출·해지는 연금외수령 — 세금은 인출 순서대로 재원별: '
                     '① 세액공제 안 받은 원금은 비과세, ② 퇴직금은 퇴직소득세 100%, ③ 세액공제 받은 돈과 운용수익(공제 여부와 '
                     '상관없이)은 기타소득세 16.5% — 넣은 돈을 모두 세액공제 받았다면 전부 16.5%')
        keys += ['order', 'free', 'early_credit', 'early_retire']
    elif _late_cancel(p):
        # 55세 이후 해지에서 사유를 인정받지 못하면 '55세 전' 규칙이 아니라 개시 여부·한도로 갈린다(9차 검토 901)
        lines.append('부득이한 사유로 인정받지 못하면 55세 이후 해지는 연금 개시 여부로 갈린다 — 개시 신청 전이면 55세가 넘어도 '
                     '연금외수령(③ 세액공제 받은 돈·수익 기타소득세 16.5%, ② 퇴직금 퇴직소득세 100%, ① 비과세), 연금을 받는 중이면 '
                     '연금수령한도까지는 연금소득세, 넘는 금액은 연금외수령')
        keys += ['order', 'start_req', 'prestart_out', 'cancel_paying']
    else:
        keys.append('order')
    return _block('doc20.txt', '부득이한 사유 인출(규칙)', lines, keys, numbers=False, needs=needs)


def early_rule(p, q):
    """금액 없이 55세 전·해지 인출 과세를 묻는 질문 — 넣은 돈 전부가 아니라 재원별로 과세된다는 규칙."""
    lines = ['55세 전 인출·해지는 연금수령이 아니라 연금외수령이다(R-04)',
             '세금은 재원별로 정해진다 — 인출 순서(R-06)대로 ① 세액공제 안 받은 원금은 비과세, '
             '② 퇴직금은 퇴직소득세 100%, ③ 세액공제 받은 돈과 운용수익(공제 여부와 상관없이)은 기타소득세 16.5%(R-10). '
             '넣은 돈을 모두 세액공제 받았다면 전부 16.5%',
             '예: 2,000만 원 해지, 그중 공제 안 받은 돈 500만 원 → 1,500만 원 × 16.5% = 247만 5천 원 (전부 공제받은 돈이면 330만 원)',
             '부득이한 사유(사망·해외이주·3개월 이상 요양 등)면 연금소득세 5.5~3.3%(R-11)']
    if p.get('plan_moved'):
        # 'DC형 … IRP로 옮겨서 깨면' — 옮긴 돈이 퇴직급여라는 것을 밝힌다(stab 2261)
        lines.append('DC·DB 같은 퇴직연금에서 IRP로 옮긴 퇴직급여는 ② 퇴직금(이연퇴직소득) 재원이다 — 55세 전 해지면 퇴직소득세 100%이고 '
                     '기타소득세 16.5%가 아니다')
    # 이직·퇴직 때 받은 퇴직금은 IRP로 들어온다(55세 전 퇴직, doc51) — '퇴직금 깨면'은 IRP 규칙으로
    acct = 'IRP' if re.search(r'IRP|개인형|퇴직금|퇴직\s*연금', q, re.I) and '연금저축' not in q else '연금저축'
    # IRP 인출 요건·'집 사려고 중도인출'(주택은 부득이한 사유가 아님 → 16.5%) — 금액이 없는 질문에도 싣는다(발표 13장 장면, 10-14)
    hk = []
    if acct == 'IRP':
        irp_l, irp_k = _irp_early(q, 'IRP')
        lines += [x for x in irp_l if not x.startswith('세법상 부득이한 사유')]
        hk = [k for k in irp_k if k not in ('unavoidable', 'unavoidable_care', 'unavoidable_doc')]
    elif re.search(r'주택|전세|집\s*(?:사|구입|마련)', q):
        lines.append('주택 구입·전세보증금은 세법상 부득이한 사유가 아니어서 세금은 그대로다 — 세액공제 받은 돈·수익은 기타소득세 16.5%')
        hk = ['house_not_unavoidable']
    if p.get('emigrate_proof'):
        lines.append(_STAY_LINE)
        hk += ['emigrate_proof', 'emigrate_doc']
    cl, ck = _cancel_check(q, acct)
    needs = ['해지·인출하려는 금액', '그중 세액공제 안 받은 납입금(비과세 원금)']
    wds = [x for x in p.get('spans', []) if x['role'] == 'withdraw']
    if len(wds) >= 2:
        # '연금저축 3,500만 원이랑 IRP 1,800만 원 둘 다 해지하면' — 해지 금액을 밝혔으니 다시 묻지 않는다. 계좌마다 재원이 달라 합쳐 계산하지 않는다
        lines.append('질문의 해지·인출 금액이 계좌마다 따로 있다(' + ' · '.join(won(x['v']) for x in wds)
                     + ') — 계좌마다 위 재원별 규칙을 따로 적용한다')
        needs = ['계좌별로 그중 세액공제 안 받은 납입금(비과세 원금)']
    return _block('doc39.txt', '55세 전·해지 인출 세금(규칙)', lines + cl,
                  ['pension_req', 'order', 'free', 'early_credit', 'early_retire', 'unavoidable'] + hk + ck, numbers=False,
                  needs=needs)


# '해외 장기체류 중인데 IRP 해지' — 영주권·장기체류는 해외이주(부득이한 사유)가 아니다(doc20, 9차 검토 908)
_STAY_LINE = ('단순 장기체류나 영주권 취득만으로는 세법상 부득이한 사유(해외이주)로 인정되지 않는다 — 해외로 옮겨 가도 '
              '「해외이주법」에 따른 해외이주신고확인서가 있어야 해외이주로 인정받는다')


def late_cancel_rule(p, q):
    """만 55세 이후 해지·중도인출 — 숫자 없이 규칙과 되묻기(9차 검토 901: '60세인데 연금저축 2000만 원 해지'를 '55세 전·해지'
    블록으로 330만 원이라 냈다). 개시 신청 전이면 55세가 넘어도 연금외수령(doc5 표), 연금 지급 중 해지는 연금수령한도까지
    연금소득세·넘는 금액은 연금외수령(doc1). 개시 여부·평가액·연차·재원을 모르면 어느 쪽인지 정하지 않는다."""
    w = p['withdraw']
    a = p.get('cancel_age') or p['age']
    acct = 'IRP' if re.search(r'IRP|개인형', q, re.I) else '연금저축' if '연금저축' in q else '연금계좌'
    started = _started(q)
    age_txt = f'{a}세' if isinstance(a, int) else f'{a[1]}대' if isinstance(a, tuple) else ''
    lines = [f'입력: {acct} ' + (f'{won(w)} ' if w is not None else '') + '해지·인출' + (f', 나이 {age_txt}' if age_txt else ''),
             '만 55세 이후 해지·인출은 55세 전 해지와 다르다 — 세금은 연금 개시 여부와 연금수령한도로 갈린다(R-04·R-10). '
             '연금수령 요건: 가입 5년 이상(퇴직금이 있는 계좌는 5년 요건 없음) · 만 55세 이후 · 개시 신청 후 연금수령한도 이내']
    keys = ['pension_req', 'no_period_req', 'start_req']
    if started is not True:
        lines.append(('연금 개시 신청 전이라 ' if started is False else '연금 개시 신청 전이면 ')
                     + '55세가 넘어도 연금외수령 — 인출 순서대로 ① 세액공제 안 받은 돈 비과세, ② 퇴직금 퇴직소득세 100%, '
                       '③ 세액공제 받은 돈·운용수익 기타소득세 16.5%')
        keys += ['prestart_out', 'order', 'free', 'early_credit', 'early_retire']
    if started is not False:
        lines.append(('연금을 받는 중에 ' if started else '연금을 받는 중(개시 후)에 ')
                     + '해지하면 연금수령한도까지는 연금소득세(55~69세 5.5%, 70~79세 4.4%, 80세 이상 3.3%), 한도를 넘는 금액은 '
                       '연금외수령으로 ③ 재원은 기타소득세 16.5%, ② 퇴직금은 퇴직소득세 — 연금수령한도 = 평가액 ÷ (11 − 연금수령연차) × 120% '
                       '(11년차부터 한도 없음)')
        keys += ['cancel_paying', 'limit_formula', 'limit_rates']
    if p.get('emigrate_proof'):
        lines.append(_STAY_LINE)
        keys += ['emigrate_proof', 'emigrate_doc']
    cl, ck = _cancel_check(q, acct)
    needs = []
    if started is None:
        needs.append('연금 개시 여부(지금 연금을 받고 있는지, 개시 신청 전인지)')
    if w is None:
        needs.append('해지·인출하려는 금액')
    if started is not False:
        if p['balance'] is None:
            needs.append('연금계좌 평가액(올해 1월 1일 또는 개시일 기준) — 연금수령한도 계산에 필요')
        if not p['year_n']:
            needs.append('연금수령연차(연금 개시가 가능해진 해부터 몇 년째인지) — 연금수령한도 계산에 필요')
    needs.append('그중 세액공제 안 받은 납입금(비과세 원금)과 퇴직금 금액')
    return _block('doc1.txt', '55세 이후 해지·인출 세금(규칙)', lines + cl, list(dict.fromkeys(keys + ck)),
                  numbers=False, needs=needs)


_DC = re.compile(r'(?<![A-Za-z])DC(?![A-Za-z])|확정\s*기여', re.I)
_RP_CTX = re.compile(r'퇴직\s*연금|(?<![A-Za-z])(?:DC|IRP)(?![A-Za-z])|확정\s*기여|개인형|퇴직금', re.I)
_RP_WITHDRAW = re.compile(r'중도\s*인출|중간에\s*(?:빼|꺼내|찾)|집\s*(?:을\s*)?(?:사|구입|마련|살)|주택\s*(?:을\s*)?(?:사|구입|마련)|전세')
_LOAN = re.compile(r'담보|대출|대여|빌리|빌릴|빌려')


def retire_plan_rule(p, q, plan=None):
    """퇴직연금(DC·IRP) 중도인출·담보대출 규칙 — 금액 없이 규칙만(10-13 외부 시험 15·19·20번).
    DC 는 퇴직금 몫이 퇴직소득세, 본인이 넣은 가입자부담금 몫이 기타소득세다(doc55 표). 담보 제공은 원칙 금지·법정 사유 예외(doc16
    근퇴법 제7조), 대출 원리금 상환은 IRP 중도인출 사유(doc20 표). 사유별 한도·금리·절차는 문서에 없어 상담으로.
    plan('dc'·'retire')을 주면 중도인출 말이 없는 해지·인출 질문('DC형 퇴직연금 3000만 원 해지')에도 이 규칙을 싣는다 —
    연금계좌 해지 세금으로 계산하지 않는다(9차 검토 900)."""
    if not plan and (not _RP_CTX.search(q) or ('연금저축' in q and not re.search(r'퇴직\s*연금|IRP|DC|퇴직금|개인형', q, re.I))):
        return None
    loan, wd = bool(_LOAN.search(q)), bool(_RP_WITHDRAW.search(q)) or bool(plan)
    if not (loan or wd):
        return None
    dc = bool(_DC.search(q)) or plan == 'dc'
    house = bool(re.search(r'주택|전세|집\s*(?:을\s*)?(?:사|구입|마련|살)', q))
    lines, keys, needs = [], [], []
    if wd:
        lines.append('퇴직연금 중도인출은 DC·IRP만 가능하고 DB는 허용되지 않는다 — 무주택자의 본인 명의 주택 구입, 전세보증금 등 '
                     '법으로 정한 사유가 있어야 한다. 사유가 없으면 IRP는 계좌를 해지해 전액 꺼내는 방법뿐이다')
        keys += ['dc_withdraw_ok', 'irp_reason_req', 'irp_reasons', 'irp_cancel_only']
        if plan == 'dc':
            # 'DC 3000만 원 해지하면' — DC 는 법정 사유가 있을 때만 중도인출, 재직 중 해지해 찾는 길은 문서에 없다(doc55·doc49)
            lines.append('DC는 근로자퇴직급여보장법 시행령이 정한 사유와 요건을 갖췄을 때만 중도인출할 수 있다 — 퇴직급여를 받을 권리는 '
                         '퇴직한 뒤에 생기고, 재직 중 DC를 해지해 찾는 방법은 받은 문서에 없다')
            keys += ['dc_reason', 'retire_right']
        elif plan == 'retire':
            # 종류를 말하지 않은 퇴직연금 — DB·DC·IRP 마다 인출 길과 세금이 달라 연금계좌 해지 세금으로 계산하지 않는다
            lines.append('퇴직연금 종류에 따라 다르다 — DB는 중도인출이 허용되지 않고, DC는 법정 사유가 있을 때만 중도인출하며 '
                         '세금은 퇴직금 몫 퇴직소득세·가입자부담금(본인이 추가로 넣은 돈) 몫 기타소득세, IRP는 아래 세금')
            keys += ['dc_reason', 'dc_tax']
            needs.append('퇴직연금 종류(DB·DC·IRP 중 어느 것인지)')
        if house:
            lines.append('주택 구입 중도인출은 신청일 기준 본인 명의 주택이 없어야 하고, 주택매매계약 체결일부터 소유권 이전 등기 후 '
                         '1개월 안에 신청한다')
            keys.append('house_req')
        lines.append('신청: DC 중도인출은 재직 중인 회사에 서류를 내고, IRP 중도인출은 가까운 지점에 내점해 신청한다')
        keys.append('dc_submit')
        amt = [] if p.get('withdraw') is not None else ['중도인출하려는 금액']     # 금액을 말했으면 다시 묻지 않는다
        if dc:
            lines.append('세금(DC): 퇴직금 몫은 퇴직소득세, 가입자부담금(본인이 추가로 넣은 돈) 몫은 기타소득세')
            keys.append('dc_tax')
            # 재직 중 DC 중도인출이라 고객에게 퇴직소득 원천징수영수증이 없다 — 퇴직소득세는 지급할 때 사업자가 매긴다(10-14 m.Talk 비교 M14)
            needs = amt + ['그중 퇴직금 몫과 본인이 넣은 돈 몫']
        else:
            lines.append('세금(IRP): ① 세액공제 안 받은 돈은 비과세, ② 퇴직금은 퇴직소득세 100%, ③ 세액공제 받은 돈·운용수익은 '
                         '기타소득세 16.5%')
            keys += ['early_retire', 'early_credit']
            if house:
                lines.append('주택 구입·전세보증금은 중도인출 사유지만 세법상 부득이한 사유는 아니어서 세금이 낮아지지 않는다'
                             '(연금소득세 5.5~3.3% 적용 안 됨)')
                keys.append('house_not_unavoidable')
            else:
                # 사유에 따라 세금이 갈린다 — 요양·파산/개인회생·천재지변은 세법상 부득이한 사유도 돼 연금소득세(doc20 표, 10-14 m.Talk 비교 M08)
                lines.append('6개월 이상 요양, 파산 선고·개인회생, 천재지변처럼 세법상 부득이한 사유에도 해당하면 세액공제 받은 돈·수익은 '
                             '연금소득세 5.5~3.3%(요양은 200만 원 + 의료실비 + 휴직월수 × 150만 원 한도). 주택 구입·전세보증금·담보대출 상환은 '
                             '16.5% 그대로')
                keys += ['unavoidable', 'unavoidable_bankrupt', 'unavoidable_care', 'house_not_unavoidable']
            needs = needs + amt + ['그중 퇴직금 몫과 세액공제 안 받은 납입금']
    if loan:
        lines += _LOAN_LINES
        keys += ['loan_no', 'loan_ok', 'loan_repay']
    return _block('doc49.txt' if wd else 'doc16.txt', '퇴직연금 중도인출·담보(규칙)', lines, list(dict.fromkeys(keys)),
                  numbers=False, needs=needs)


_LOAN_LINES = ['퇴직연금 급여를 받을 권리는 원칙적으로 담보로 제공할 수 없지만, 주택 구입 등 법령이 정한 사유와 요건을 갖추면 '
               '정해진 한도 안에서 담보로 제공할 수 있다(근로자퇴직급여 보장법 제7조)',
               '담보로 대출받은 뒤 그 대출 원리금을 갚기 위한 경우는 IRP 중도인출 사유다 — 세법상 부득이한 사유는 아니어서 '
               '세액공제 받은 돈·수익은 기타소득세 16.5%',
               '담보대출의 구체적인 사유·한도·금리·신청 방법은 받은 문서에 없어 상담에서 확인해야 한다']
# 해지·인출 말 — 넣는 말의 '빼고'('회사 돈 빼고 제가 넣으면')는 아니다
_PLAN_WD = re.compile(r'인출|꺼내|빼(?:면|서|려|고\s*싶|야|도|낼|내)|찾(?:으면|아\s*(?:쓰|서))|' + _CANCEL.pattern)
# 퇴직한 뒤 퇴직급여를 받는 말 — '55세 전에 퇴직하면 퇴직금은 어떻게 받나요', '퇴직 후 DB 퇴직금을 일시금으로 찾으면'.
# DB 재직 중 인출 규칙(중도인출 불가·재직 중 해지 길 없음)은 이 질문의 답이 아니다(10차 검토 1004)
_AFTER_RETIRE = re.compile(r'퇴직\s*(?:후|뒤|이후|하고|하면서|하면|할\s*때|한\s*(?:뒤|후|다음)|해서|하게\s*되면|시(?![가-힣]))'
                           r'|퇴사|은퇴')
# 재직 중 인출이라는 말 — '퇴직 전에 중도인출', '다니면서 해지'
_IN_SERVICE = re.compile(r'중도\s*인출|중도\s*해지|재직|다니면서|퇴직\s*(?:하기\s*)?전|중간에')
# '퇴사 전·은퇴하기 전'도 재직 중이다 — _AFTER_RETIRE 가 '퇴사·은퇴' 낱말만 보아 퇴직 뒤로 읽고 DB 재직 중 블록을 뺐다(stab 2201).
# 다만 묻는 때일 수 있다 — '퇴사 전에 궁금해서요, … 퇴사하고 찾으면'은 퇴직 뒤 받는 질문이라, 이 말을 빼고도 퇴직 뒤 말이 남으면 그쪽이다
_QUIT_BEFORE = re.compile(r'(?:퇴사|은퇴)\s*(?:하기\s*)?(?:전|이전)')


def _after_retire(q):
    """퇴직한 뒤(퇴직할 때) 퇴직급여를 받는 질문인가 — 재직 중 인출 말이 없을 때만. 'DB 퇴직금을 일시금으로 찾으면'처럼
    퇴직 말 없이 일시금으로 받는 말도 같다(해지·깨는 말이 함께 있으면 재직 중 해지 질문일 수 있어 아니다)."""
    if _IN_SERVICE.search(q):
        return False
    rest = _QUIT_BEFORE.sub(' ', q)
    # '은퇴 전에 미리 알아보려고요. DB 퇴직금을 일시금으로 찾으면'은 묻는 때가 은퇴 전일 뿐 퇴직 뒤 일시금 질문이다 —
    # 이 말을 뺀 나머지에도 일시금 조건을 같이 본다(stab 재검증 R4: 일시금 조건이 빠져 DB 재직 중 블록이 붙었다)
    return bool(_AFTER_RETIRE.search(rest)) or bool(re.search(r'일시금', rest) and not _CANCEL.search(rest))


def plan_withdraw_rule(p, q):
    """DB·DC·기업형 IRP·종류를 말하지 않은 퇴직연금의 해지·인출 질문 → 규칙 블록(숫자 없음) 또는 None.
    연금계좌(IRP·연금저축)의 '55세 전·해지 인출 세금'으로 계산하면 안 된다 — 'DB형 퇴직연금 3000만 원 해지'를 연금계좌 해지로
    보아 495만 원, 'DB형 퇴직연금 주택 구입으로 1000만 원 중도인출'을 165만 원, '기업형 IRP 2000만 원 해지'를 330만 원이라 했고,
    같은 질문에 온톨로지 경로는 'DB 는 중도인출 불가(doc49)'라 프롬프트 안에서 두 말이 부딪혔다(9차 검토 900).
    DB 는 중도인출이 허용되지 않고(doc49), 회사가 허용하면 DC 로 바꾼 뒤 DC 중도인출 사유를 갖춰야 받으며(doc13), 퇴직할 때 55세
    미만이면 IRP 로 의무 이전된다(doc51). 기업형 IRP 의 해지 세금 규칙은 받은 문서에 없어 계산하지 않는다."""
    plan = p.get('plan')
    if not plan:
        return None
    if p['contrib'] or p['retire_unsure'] or p['retire_dropped'] or p['retire_db'] or p['acct_unsure'] or p.get('old_contrib'):
        return None                         # 넣는 돈 질문('DC 깨서 300만 원 넣으면 세액공제') — 세액공제 쪽이 맡는다
    # 해지·중도인출·인출을 묻는 질문에만 — '55세 전'(p['early'])·받는 금액(p['withdraw'])만으로는 붙이지 않는다. 9차는 이 둘로도
    # 붙여 'DB형 회사 다니는데 55세 전에 퇴직하면 퇴직금은 어떻게 받나요?'에 재직 중 인출 블록을 냈다(10차 검토 1004)
    if not (_RP_WITHDRAW.search(q) or _PLAN_WD.search(q) or p['unavoidable'] and re.search(r'세금|과세|세율|떼', q)):
        return None
    if _after_retire(q):
        return None                         # 퇴직한 뒤 받는 질문('퇴직 후 DB 퇴직금을 일시금으로 찾으면') — 재직 중 인출 규칙이 아니다
    if plan in ('dc', 'retire'):
        return retire_plan_rule(p, q, plan)
    w = p['withdraw']
    lines = [f'입력: {"DB(확정급여형)" if plan == "db" else "기업형 IRP"}' + (f' {won(w)}' if w is not None else '') + ' 해지·인출']
    if plan == 'db':
        lines += ['DB(확정급여형)는 중도인출이 허용되지 않는다 — 퇴직연금 중도인출은 DC·IRP만 가능하다',
                  '퇴직급여를 받을 권리는 퇴직한 뒤에 생긴다 — 재직 중 DB를 해지해 찾는 방법은 받은 문서에 없어, DB 해지·중도인출 '
                  '세금은 계산하지 않음',
                  '회사가 허용하면 중도인출을 위해 DB에서 DC로 퇴직급여제도를 바꿀 수 있다 — 회사 규정의 신청 시기를 지키고 '
                  'DC 중도인출 사유(무주택자 주택 구입 등 법으로 정한 사유)와 시기를 갖춰야 받을 수 있어, 회사 퇴직연금규약이나 '
                  '인사팀에서 확인해야 한다',
                  'DC로 바꿔 중도인출하면 세금은 퇴직금 몫 퇴직소득세, 가입자부담금(본인이 추가로 넣은 돈) 몫 기타소득세',
                  '퇴직할 때 55세 미만이면 DB 퇴직급여는 IRP로 옮겨야 하고(의무 이전), 55세 이상이면 IRP·연금저축·일반계좌 중 고를 수 있다']
        keys = ['dc_withdraw_ok', 'retire_right', 'rp_reason', 'db_to_dc', 'db_dc_reason', 'dc_tax', 'db_irp_route']
        if p['unavoidable'] or p['emigrate']:
            lines.append('요양·파산 같은 사유가 있어도 DB에서는 중도인출이 허용되지 않는다 — DC로 바꾼 뒤 DC 중도인출 사유에 해당해야 한다')
    else:
        lines += ['기업형 IRP 중도인출은 DC와 같은 신청서(회사 명판·등록인감 날인)로 신청한다 — 개인형 IRP 중도인출신청서와 다르다',
                  '퇴직연금 중도인출은 법으로 정한 사유(무주택자 주택 구입 등)가 있을 때만 허용된다',
                  '기업형 IRP를 해지·인출할 때의 세금 규칙은 받은 문서에 따로 없어 금액을 계산하지 않음 — 개인형 IRP의 해지 세금'
                  '(55세 전 해지는 연금외수령)을 그대로 적용할 수 있는지 문서로 확인되지 않아 회사·금융회사 상담에서 확인해야 한다']
        keys = ['corp_irp_form', 'rp_reason', 'dc_withdraw_ok']
    if _LOAN.search(q):
        lines += _LOAN_LINES
        keys += ['loan_no', 'loan_ok', 'loan_repay']
    return _block('doc49.txt', '퇴직연금 중도인출·해지(규칙)', lines, keys, numbers=False)


# 'DC형 연금상품으로 수령 시'(10-14 실측 재작성문)도 받는다
_PAYOUT = re.compile(r'연금(?:\s*(?:상품|계좌|형태|형식))?\s*(?:으로|로)\s*(?:받|수령|타)|연금\s*(?:을\s*)?(?:수령|개시)')
_PAYOUT_TAX = re.compile(r'세금|비과세|과세|세율|퇴직소득세|연금소득세|떼|감면')


def dc_payout_ask(q):
    """'연금으로 받으면 세금은?' 꼴 — 계좌 이름은 보지 않는다(앞 대화의 DC 를 이어 붙일 때도 쓴다)."""
    return bool(_PAYOUT.search(q) and _PAYOUT_TAX.search(q)) and not (_RP_WITHDRAW.search(q) or _LOAN.search(q))


def dc_payout_rule(p, q):
    """DC 적립금을 연금으로 받을 때 세금 — 금액 없이 규칙만(10-13 외부 시험 22번: 적립금 전체에 5.5%를 붙여 '198만 원'이라 했다).
    DC 운용수익도 퇴직 때 퇴직소득(doc42), DC 법정퇴직금은 55세 미만 퇴직이면 IRP 의무이전(doc51 표), 퇴직금 몫은 한도 안 연금수령 시
    30~50% 감면(doc39), 감면은 퇴직소득세에만·세액공제 받은 돈과 수익은 연금소득세(doc51). DC 에 본인이 넣은 돈이 IRP 로 옮겨질 때
    어느 재원으로 나뉘는지는 문서에 없어 상담으로."""
    if not (_DC.search(q) and dc_payout_ask(q)):
        return None
    lines = ['비과세는 아니다 — DC에서 운용해 생긴 수익도 퇴직할 때 퇴직소득으로 과세되고, 퇴직금 몫은 연금으로 받아도 퇴직소득세를 낸다'
             '(다만 감면됨)',
             'DC 퇴직금은 퇴직할 때 IRP로 옮겨 IRP에서 연금으로 받는다 — 55세 미만에 퇴직하면 IRP 이전이 의무, 55세 이상이면 IRP·일반계좌 중 선택',
             '퇴직금 몫을 연금수령한도 안에서 받으면 퇴직소득세를 1~10년차 30%, 11~20년차 40%, 21년차부터 50% 감면받는다'
             '(원래 세금의 70~50%만 냄)',
             '감면은 퇴직소득세에만 적용된다 — 연금계좌에서 세액공제를 받은 납입금과 그 운용수익은 연금소득세 5.5~3.3%'
             '(만 55~69세 5.5%, 70~79세 4.4%, 80세 이상 3.3%)',
             '세액공제를 받지 않은 납입금은 꺼낼 때 비과세',
             '한도를 넘겨 받으면 넘은 금액 중 퇴직금 몫은 퇴직소득세 그대로, 세액공제 받은 돈·수익은 기타소득세 16.5%',
             'DC에 본인이 추가로 넣은 돈이 IRP로 옮겨질 때 어느 몫으로 나뉘는지는 받은 문서에 없어 상담에서 확인해야 한다']
    keys = ['dc_profit', 'dc_irp_route', 'retire_in', 'retire_years', 'retire_only', 'limit_rates', 'free', 'retire_over',
            'over_limit']
    # 빠진 정보는 질문에 없는 것만 — 'DC형 적립금 1억을 IRP로 받아서'에 적립금 규모를 다시 물었다(_payout_retire 와 같은 까닭)
    needs = [n for n, have in (('DC 적립금(퇴직금) 규모', p.get('balance') is not None or (p.get('fund') or {}).get('retire')),
                               ('퇴직소득세(퇴직소득 원천징수영수증)', p.get('rtax') is not None or p.get('retire_eff') is not None),
                               ('그중 본인이 넣어 세액공제 받은 돈', False),
                               ('연금 받기 시작할 나이', isinstance(p.get('age'), int) or p.get('rate_age'))) if not have]
    return _block('doc51.txt', 'DC 연금 수령 세금(규칙)', lines, keys, numbers=False, needs=needs)


def compute(q):
    """질문 → {'blocks': [...], 'summary': str, 'parsed': dict} 또는 None(넣을 게 없음)."""
    try:
        return _compute(normalize(norm_ws(q)))
    except Exception:
        return None                       # 계산기 오류로 답변이 깨지면 안 된다


def _compute(q):
    p = parse(q)
    if p['old']:
        return None
    try:
        from understand_guard import old_pension      # 가드와 같은 정의를 쓴다
        if old_pension(q):
            return None
    except Exception:
        pass
    if p['insure'] and not p['private']:
        return None
    blocks = []
    # DB·기업형 IRP 만 말한 해지·인출 — 연금계좌 해지 세금(①②③ 재원·16.5%)으로 계산하지 않고 제도 규칙만
    # (9차 검토 900: 'DB형 퇴직연금 3000만 원 해지'를 연금계좌 해지로 495만 원). DC·종류 모를 퇴직연금은 아래에서
    # 연금계좌 해지 블록이 나올 때만 퇴직연금 중도인출 규칙으로 바꾼다
    plan_b = plan_withdraw_rule(p, q) if p.get('plan') in ('db', 'irp_corp') else None
    # 재원별 인출(퇴직금이 섞인 계좌·55세 전 해지)이 먼저 — 아니면 ③ 재원 기준 연금수령한도
    pension_ctx = p['private'] or bool(p['fund_mentioned']) or '연금' in q
    if p.get('plan') in ('db', 'irp_corp') and not plan_b and _after_retire(q):
        # 퇴직한 뒤 DB·기업형 IRP 퇴직급여를 받는 질문('DB형 퇴직연금 퇴직할 때 해지하면') — 재직 중 인출 블록을 빼면서 연금계좌
        # 해지 세금(55세 전·해지 블록)으로 넘기지 않는다(10차 검토 1004, 9차 900 과 같은 까닭)
        pension_ctx = False
    src_b = by_source(p, q) if pension_ctx and not plan_b else None
    # '올해 처음으로 연금 받기 시작했는데 계좌에 1억'처럼 계좌 이름 없이 연금 계좌 얘기를 하는 경우도 받는다
    lim = None if src_b or plan_b else \
        withdraw_limit(p, q) if p['private'] or (p['balance'] is not None and '연금' in q) else None
    # '작년에 600 넣고 공제받았는데 54살이라 그거 빼면 세금' — 공제 말이 돈을 설명하는 지난 일뿐이고 묻는 동사가 인출이면 세액공제
    # 질문이 아니다(stab 2229·2236: 인출 세금 대신 세액공제액을 냈다). 인출 금액을 못 읽었으면 55세 전 인출 규칙(숫자 없음)으로
    ded_past = bool(_DED_Q.search(q) and _PLAN_WD.search(q) and not _DED_Q.search(_DED_PAST.sub(' ', q)))
    if not plan_b and not src_b and not lim and (p['early'] or ded_past and _early_eff(p)) and pension_ctx and \
            not p['unavoidable'] and p['withdraw'] is None and not p['payout'] and _TAX_Q.search(q):
        # '55세 전에 빼면 넣은 돈 전부에 16.5% 떼죠?' — 금액 없는 전제 질문. 55세 이후로 분명하면 개시 여부·한도 규칙(9차 901)
        src_b = late_cancel_rule(p, q) if _late_cancel(p) else early_rule(p, q)
    if not plan_b and not src_b and not lim and p['unavoidable'] and pension_ctx and _TAX_Q.search(q) and \
            (p['early'] or p['withdraw'] is not None or re.search(r'인출|해지|깨|정리|찾|빼', q)):
        # '이민 가는데 55세 전에 깨면 16.5% 다 떼이죠?' — 부득이한 사유 규칙(+ 인정받지 못할 때의 규칙)
        src_b = unavoidable_rule(p, q)
    if (src_b or lim) and p.get('plan') in ('dc', 'retire'):
        # 'DC형 퇴직연금 3000만 원 해지'·'퇴직연금 주택 구입으로 1000만 원 중도인출' — 연금계좌가 아닌(또는 종류를 모르는) 퇴직연금을
        # 연금계좌 해지 세금으로 계산하지 않는다(9차 검토 900). 연금계좌 블록이 없던 질문('DC 해지할 수 있어요?')은 그대로 둔다
        plan_b = retire_plan_rule(p, q, p['plan'])
        src_b = lim = None
    if plan_b:
        blocks.append(plan_b)
    elif src_b:
        blocks.append(src_b)
    elif lim:
        blocks.append(lim)
    elif (_TAX_Q.search(q) or len(p['payout']) >= 2 and _ALT_Q.search(q) or p['payout'] and _OVER1500_Q.search(q)) \
            and not p['unavoidable']:
        # '한 곳에서 연 900, 다른 데서 연 800 받으면 1,500 넘는 거예요?' — 세금 말이 없어도 1,500만 원 판단은 수령 세금 질문이다(stab 2244)
        # '연 1,500만 원씩 받는 것과 연 2,000만 원씩 받는 것 중 어느 쪽이 나은가요?' — 세금 말이 없어도 수령 방식 비교는 세금 비교다
        b = payout(p, q)
        if b:
            blocks.append(b)
    ded_intent = (_DED_Q.search(q) and not ded_past) or (p['isa'] and re.search(r'세금|절세|아끼|아낄|이득|공제|나아|나을|유리|어디로', q)) \
        or (p['income'] and len(p['contrib']) >= 2 and re.search(r'비교|어느\s*쪽|뭐가\s*(?:나아|나을|더)|차이|각각|(?<![A-Za-z])vs(?![A-Za-z])'
                                                              r'|어떤\s*게\s*(?:나아|나을|더)|중에|두\s*(?:경우|개|가지)', q, re.I)) \
        or (p['income'] and _acct_choice(p, q))
    # 넣는 계좌를 몰라 납입에서 뺀 금액(acct_unsure)도 되묻기 블록을 낸다 — 소득을 말하지 않으면 블록 없이 모델이 금액을 채울 수 있다
    if ded_intent and (p['income'] or p['contrib'] or p['isa'] or p['income_unknown_kind'] or p.get('acct_unsure')) and not blocks:
        blocks.extend(deduction(p, q))
    # 퇴직연금 중도인출·담보 규칙 — 담보를 물었거나 DC 이거나 다른 블록이 없을 때(IRP 해지 세금 블록과 겹치지 않게)
    if not plan_b and not any(b.get('numbers') for b in blocks) and (_LOAN.search(q) or _DC.search(q) or not blocks):
        rp = retire_plan_rule(p, q) or dc_payout_rule(p, q)
        if rp:
            blocks.append(rp)
    if not blocks:
        return None
    amount_assume = [n['text'] for n in p.get('amount_notes', [])]
    if amount_assume:
        for b in blocks:
            if b.get('numbers'):
                b['assume'] = list(dict.fromkeys(b['assume'] + amount_assume))
                b['text'] = b['text'].replace('\n[원문]\n', '\n- 금액 읽기(질문에 단위가 없어 이렇게 봄): '
                                              + ' · '.join(amount_assume) + '\n[원문]\n', 1)
                break
    rids = list(dict.fromkeys(r for b in blocks for r in b.get('rids', [])))
    return {'blocks': blocks, 'parsed': p, 'rids': rids, 'compare': bool(_COMPARE_Q.search(q)),
            'ambiguous': [n for n in p.get('amount_notes', []) if n.get('ask')],
            'needs': list(dict.fromkeys(x for b in blocks for x in b.get('needs', []))),
            'assume': list(dict.fromkeys(x for b in blocks for x in b.get('assume', []))),
            'figures': [x for b in blocks for x in b.get('figures', [])],
            'summary': ' / '.join(b['topic'] + (f'({"·".join(b["rids"])})' if b.get('rids') else '') + ': '
                                  + b['text'].split('\n')[1][2:80]
                                  + (f' → {b["key_figure"]}' if b.get('key_figure') else '')
                                  + (f' · 빠진 정보 {len(b["needs"])}개' if b.get('needs') else '') for b in blocks)}


# ---------------------------------------------------------------------------
# 사후 검사 — '1,500만 원 초과분만 16.5%' 같은 분할 과세 서술을 찾고 고친다
# ---------------------------------------------------------------------------
_MISREAD = [
    # 0: '1,500만 원 초과분(을 넘는 금액)에 16.5%/종합과세'
    re.compile(r'1[,.]?500\s*만\s*원?\s*(?:을|를)?\s*(?:초과|넘)(?:하는|는|한)?\s*(?:금액|분|부분|액수)[^.\n]{0,25}?(?:16\.5\s*%|종합\s*과세|분리\s*과세)'),
    # 1: '(1,500만 원 …) 이를 초과하는 금액/초과분에 16.5%' — 앞에 1,500만 원이 있어야 한다
    re.compile(r'초과(?:분|하는\s*(?:금액|부분))\s*(?:\(?\s*\**\d[\d,]*\s*만\s*원\**\s*\)?)?\s*(?:에|에만|만|은|는)\s*(?:대해서?(?:는|만)?\s*)?(?:\**\s*)?(?:16\.5\s*%|종합\s*과세)'),
    # 2: '1,500만 원까지는 5.5% … 초과/나머지'
    re.compile(r'1[,.]?500\s*만\s*원?\s*까지(?:는|만)?\s*[^.\n]{0,12}?(?:5\.5|4\.4|3\.3)\s*%[^.\n]{0,40}?(?:초과|나머지|그\s*이상|넘는)'),
]
# 오독을 바로잡으려고 인용한 문장, 또는 전액 과세를 말하는 문장은 오독이 아니다
_OK_SENT = re.compile(r'아니|않|전부|모두|총액|전액|전체|오해|착각|잘못|틀|흔히|생각하기\s*쉽')


def _sentences(text):
    out, start = [], 0
    for m in re.finditer(r'[.!?。]\s|\n', text):
        out.append((start, m.end()))
        start = m.end()
    if start < len(text):
        out.append((start, len(text)))
    return out


def misread_spans(text, calc=None):
    """분할 과세 오독 문장들 [(시작, 끝, 구절)]."""
    if not text:
        return []
    found = []
    for a, b in _sentences(text):
        sent = text[a:b]
        if _OK_SENT.search(sent):
            continue
        for k, rx in enumerate(_MISREAD):
            m = rx.search(sent)
            if not m:
                continue
            if k == 1:
                ctx = text[max(0, a + m.start() - 70):a + m.start()]
                if not re.search(r'1[,.]?500\s*만', ctx) or re.search(r'한도|연금외수령', sent[max(0, m.start() - 12):m.start()]) \
                        or '기타소득' in sent:
                    continue        # '연금수령한도 초과분은 16.5% 기타소득세'는 맞는 서술이다(doc39)
            found.append((a, b, m.group(0)))
            break
    if calc:
        # 숫자로 확인: 연 X(>1,500)를 '1,500까지 r% + 초과분 16.5%'로 나눠 계산한 금액
        for blk in calc['blocks']:
            x = blk.get('yearly')
            if not x or x <= 1500 or blk['topic'] != '연금 수령 세금':
                continue
            band = rate_for_age(rate_age(calc['parsed']))
            wrong = [won((x - 1500) * 0.165)]
            if band:
                wrong.append(won(1500 * band[0] / 100 + (x - 1500) * 0.165))
            for w in wrong:
                if w in blk['text']:
                    continue        # 계산 블록에 정답으로도 나오는 금액은 오독 표지가 아니다
                for m in re.finditer(re.escape(w), text):
                    if any(a <= m.start() < b for a, b, _ in found):
                        continue
                    sa, sb = next(((a, b) for a, b in _sentences(text) if a <= m.start() < b), (m.start(), m.end()))
                    if re.search(r'초과|나머지|합계|총', text[max(sa, m.start() - 40):m.start()]):
                        found.append((sa, sb, w))
    return sorted(set(found))


def misread(text, calc=None):
    """오독 구절 하나(없으면 None)."""
    s = misread_spans(text, calc)
    return s[0][2] if s else None


def correction(calc, cite=None):
    """오독 문장을 갈아 끼울 문장."""
    ref = f'[문서{cite}]' if cite else ''
    for blk in (calc or {}).get('blocks', []):
        x = blk.get('yearly')
        if blk['topic'] == '연금 수령 세금' and x and x > 1500:
            return (f'연 {won(x)}은 1,500만 원을 넘으므로 초과분만이 아니라 수령액 전액({won(x)})이 종합과세 또는 '
                    f'16.5% 분리과세 대상이며, 16.5% 분리과세를 고르면 {won(x * 0.165)}입니다{ref}. ')
    return ('세액공제 받은 납입금·운용수익을 연 1,500만 원 넘게 연금으로 받으면 초과분만이 아니라 수령액 전액이 '
            f'종합과세 또는 16.5% 분리과세 대상입니다{ref}. ')


def _split_pieces(calc):
    """분할 과세로 나눠 계산하면 나오는 금액들 — '1,500만 원까지 r%' 몫, '초과분 16.5%' 몫, 그 합.
    계산 블록에 정답으로도 나오는 금액은 뺀다."""
    out = set()
    for blk in (calc or {}).get('blocks', []):
        x = blk.get('yearly')
        if not x or x <= 1500 or blk['topic'] != '연금 수령 세금':
            continue
        over = (x - 1500) * 0.165
        band = rate_for_age(rate_age(calc['parsed']))
        rates = [band[0]] if band else [r for r, _ in _BANDS]
        low = {won(1500 * r / 100) for r in rates}
        out |= {won(over)} | {won(1500 * r / 100 + over) for r in rates}
        out -= {w for w in list(out) if w in blk['text']}
        # '1,500만 원까지 5.5% → 82만 5천 원'은 블록에도(1,500만 원 이하로 받을 때의 비교값) 나올 수 있다 —
        # 오독과 함께 '1,500만 원까지·이하' 구간 몫으로 쓰였을 때만 분할 조각이다
        out |= {'LOW:' + w for w in low}
    return out


_LOW_CTX = re.compile(r'1[,.]?500\s*만\s*원?\s*(?:까지|이하|이내)')


def _is_piece(seg, pieces):
    if any(w in seg for w in pieces if not w.startswith('LOW:')):
        return True
    return bool(_LOW_CTX.search(seg)) and any(w[4:] in seg for w in pieces if w.startswith('LOW:'))


_SPLIT_CTX = re.compile(r'1[,.]?500\s*만\s*원?\s*(?:까지|이하|이내)|초과|합계|따라서|총|더하면|\+')


def repair(text, calc=None, cite=None):
    """(고친 글, 고친 곳 수). 오독 문장 첫 개를 바른 문장으로 바꾸고 나머지 오독 문장은 지운다.
    분할 계산의 나머지 조각(1,500만 원까지 몫·초과분 몫·합계 줄)도 지운다 — 검토: 오독 문장만 바꾸면
    '따라서 세금은 82만 5천 + 49만 5천 = 132만 원'이 남았고, 표 안에서 고치면 표가 깨졌다."""
    if not misread_spans(text, calc):
        return text, 0
    pieces = _split_pieces(calc)
    n = 0
    # 1) 표 — 오독이나 분할 조각이 든 행을 지우고, 바른 문장은 표 뒤에 둔다. 머리줄만 남은 표는 통째로 지운다
    lines = text.split('\n')
    out_lines, table, put_after = [], [], False

    def flush():
        nonlocal table, put_after
        body = [t for t in table if not re.match(r'\s*\|?\s*:?-{2,}', t)]
        if len(body) > 1:
            out_lines.extend(table)
        if put_after:
            out_lines.append('')
            out_lines.append(correction(calc, cite).rstrip())
        table, put_after = [], False

    for ln in lines:
        if ln.lstrip().startswith('|'):
            bad = misread_spans(ln, calc) or _is_piece(ln, pieces)
            if bad:
                n += 1
                put_after = put_after or bool(misread_spans(ln, calc)) or bool(_SPLIT_CTX.search(ln))
                continue
            table.append(ln)
            continue
        if table or put_after:
            flush()
        out_lines.append(ln)
    if table or put_after:
        flush()
    text2 = '\n'.join(out_lines)
    corrected = n > 0 and correction(calc, cite).rstrip() in text2
    # 2) 문장 — 첫 오독 문장은 바른 문장으로(표에서 이미 넣었으면 지우기만), 나머지 오독·분할 조각 문장은 지운다
    spans = misread_spans(text2, calc)
    drop = [(a, b) for a, b in _sentences(text2)
            if not any(a <= x < b for x, _, _ in spans) and _is_piece(text2[a:b], pieces)
            and _SPLIT_CTX.search(text2[a:b])]
    marks = sorted([(a, b, 'fix') for a, b, _ in spans] + [(a, b, 'drop') for a, b in drop])
    out, last = [], 0
    for a, b, kind in marks:
        if a < last:
            continue
        out.append(text2[last:a])
        if kind == 'fix' and not corrected:
            tail = '\n' if text2[a:b].endswith('\n') else ''
            out.append(correction(calc, cite).rstrip() + (tail or ' '))
            corrected = True
        elif text2[a:b].endswith('\n'):
            out.append('\n')
        last = b
        n += 1
    out.append(text2[last:])
    fixed = re.sub(r'\n{3,}', '\n\n', ''.join(out))
    fixed = '\n'.join(ln for ln in fixed.split('\n') if not re.fullmatch(r'\s*[-*]\s*', ln))
    return fixed, n
